// 82 units (20-101)
window.__UNITS_DATA__ = [{"id": 20, "file": "20-开场破冰", "title": "开场破冰", "titleRaw": "20、开启面试", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Hi, Steve, it's nice to meet you. Thanks for being available today, how are you doing?", "Nice to meet you too. Thanks for inviting me, I'm doing great ,and yourself?", "Same here, thanks. Before we kick-start just introduce myself briefly, I'm John from the product team and also the interviewer for this round. Our interview may take around half an hour. During the process ,I may interrupt you from time to time for any follow-up questions, hope you don't mind.", "Not at all!"], "dialogueZH": ["嗨，Steve，很高兴见到你。感谢你今天能来，最近怎么样？", "我也很高兴见到你。谢谢邀请，我很好，你呢？ 我也很好，谢谢。在我们正式开始前，我先简单自我介绍一下。我是产品团队的John，也是这轮面试的面试官。我们的面试大约需要半小时。过程中我可能会不时打断你，提一些后续问题，希望你不要介意。", "完全没关系！"], "vocabulary": [{"en": "available", "phonetic": "/əˈveɪ.lə.bəl/", "pos": "adj.", "zh": "有空的；可参加的", "source": "Thanks for being available today"}, {"en": "How are you doing?", "phonetic": "/haʊ ɑːr juː ˈduː.ɪŋ/", "pos": "phrase", "zh": "你最近怎么样？(比How are you更口语)", "source": "how are you doing?"}, {"en": "kick-start", "phonetic": "/ˈkɪk.stɑːrt/", "pos": "v.", "zh": "开始；启动(会议/项目)", "source": "Before we kick-start..."}, {"en": "briefly", "phonetic": "/ˈbriːf.li/", "pos": "adv.", "zh": "简短地；简要地", "source": "introduce myself briefly"}, {"en": "interviewer", "phonetic": "/ˈɪn.tə.vjuː.ər/", "pos": "n.", "zh": "面试官；采访者", "source": "the interviewer for this round"}, {"en": "follow-up questions", "phonetic": "/ˈfɑː.loʊˌʌp/", "pos": "n. phr.", "zh": "后续追问；补充问题", "source": "for any follow-up questions"}, {"en": "interrupt", "phonetic": "/ˌɪn.təˈrʌpt/", "pos": "v.", "zh": "打断；中断", "source": "I may interrupt you from time to time"}, {"en": "mind", "phonetic": "/maɪnd/", "pos": "v.", "zh": "介意；反对", "source": "hope you don't mind"}, {"en": "Not at all", "phonetic": "/nɑːt æt ɔːl/", "pos": "phrase", "zh": "一点也不；完全没关系", "source": "Not at all!"}, {"en": "Same here", "phonetic": "/seɪm hɪr/", "pos": "phrase", "zh": "我也一样(口语常用附和)", "source": "Same here, thanks"}], "grammar": [{"title": "介词 + 动名词", "structure": "preposition + V-ing", "example": "Thanks for being available today.", "explanation": "介词(for/about/in/without等)后面必须跟动词的-ing形式。for是介词，所以be变being。", "practice": "填空：Thank you for ______ (come) to the interview. (答案: coming)"}, {"title": "Before 引导时间状语从句", "structure": "Before + 主谓, 祈使句/主句", "example": "Before we kick-start, let me introduce myself briefly.", "explanation": "Before从句表示'在...之前'，主句常用祈使句或将来时。", "practice": "仿写：Before the meeting ______ (start), let me check the attendees."}, {"title": "情态动词 May 表示可能性", "structure": "may + 动词原形", "example": "Our interview may take around half an hour.", "explanation": "may表示'可能/或许'，语气比can更正式礼貌。", "practice": "仿写：The meeting ______ ______ (可能持续) around two hours."}], "coreSentences": [{"original": "It's nice to meet you.", "function": "初次见面问候", "alternative": "Great to finally meet you in person. / Pleasure to meet you."}, {"original": "Thanks for being available today.", "function": "感谢对方出席", "alternative": "Thanks for taking the time today. / Appreciate you making time for this."}, {"original": "How are you doing?", "function": "寒暄问候", "alternative": "How's everything going? / How have you been?"}, {"original": "Before we kick-start, let me introduce myself briefly.", "function": "面试开场白", "alternative": "Before we dive in, let me give you a quick overview."}, {"original": "Hope you don't mind.", "function": "礼貌预防", "alternative": "I hope that's okay with you. / Please let me know if that's an issue."}, {"original": "Not at all!", "function": "大方回应", "alternative": "Not a problem at all. / Absolutely no worries."}, {"original": "Our interview may take around half an hour.", "function": "说明时长预期", "alternative": "The meeting should take about 30 minutes."}], "exercises": {"vocabChoice": [{"question": "\"kick-start\" 在商务场景中的意思是？", "options": ["踢一脚", "开始/启动", "快速奔跑", "终结"], "answer": 1}, {"question": "\"follow-up questions\" 的中文意思是？", "options": ["跟进的问题", "后续追问", "补充问题", "简单问题"], "answer": 2}, {"question": "哪个词表示\"介意\"？", "options": ["mind", "briefly", "interrupt", "start"], "answer": 0}], "fillBlank": [{"sentence": "Before we ______-______, let me introduce myself.", "answer": "kick-start", "hint": "开始/启动"}, {"sentence": "Thanks for ______ available today.", "answer": "being", "hint": "介词后的be动词形式"}, {"sentence": "I hope you don't ______ if I ask a few questions.", "answer": "mind", "hint": "介意"}], "grammarChoice": [{"question": "在 \"Thanks for being available\" 中，being 是动名词，因为：", "options": ["for 是介词，后面跟V-ing", "进行时态", "被动语态", "固定搭配"], "answer": 0}], "sentenceReorder": [{"scrambled": ["started", "let me", "Before", "we get", "myself", "introduce"], "answer": "Before we get started, let me introduce myself."}]}, "cultureNote": "在西方商务面试中，通常以轻松的small talk开场(天气、交通等)，而非直奔主题。面试官可能会问'How are you doing?'来缓解紧张气氛，回答'I'm fine, thank you'即可，不必长篇大论。", "interviewTip": "开场破冰时保持微笑和眼神交流，回答不要太短(像在走流程)，也不要太长(像在即兴演讲)，一两句话回应+简单反问对方是比较好的策略。", "difficulty": "🟢入门"}, {"id": 21, "file": "21-自我介绍", "title": "自我介绍", "titleRaw": "21、自我介绍", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["So Steve, please tell me a bit about yourself, especially your education and work background.", "Sure. I went to the Tsinghua University as an undergraduate majoring in marketing, then I pursued a Master's degree in economics at Peking University.Upon graduation, I started my career as data analyst at Baidu, where I stayed for 2 years. Then I left for Lenovo Group, supporting key accounts in project department. Having been in this role for almost4 years now, I feel it's time to further advance my career."], "dialogueZH": ["所以 Steve，请你介绍一下你自己，尤其是你的教育和工作背景。", "当然可以。我在清华大学读了市场营销本科，之后在北京大学攻读经济学硕士。毕业后，我在百度担任数据分析师工作了两年。随后我加入联想集团，在项目部门支持重点客户。到现在我在这个岗位已经将近四年了，我觉得是时候进一步提升我的职业发展。"], "vocabulary": [{"en": "undergraduate", "phonetic": "/ˌʌn.dəˈɡrædʒ.u.ət/", "pos": "n./adj.", "zh": "本科生；本科的", "source": "as an undergraduate"}, {"en": "major in", "phonetic": "/ˈmeɪ.dʒər ɪn/", "pos": "v. phr.", "zh": "主修(某专业)", "source": "majoring in marketing"}, {"en": "pursue", "phonetic": "/pərˈsuː/", "pos": "v.", "zh": "追求；攻读(学位)", "source": "pursued a Master's degree"}, {"en": "upon graduation", "phonetic": "/əˈpɑːn ˌɡrædʒ.uˈeɪ.ʃən/", "pos": "adv. phr.", "zh": "毕业时；毕业后", "source": "Upon graduation, I started..."}, {"en": "data analyst", "phonetic": "/ˈdeɪ.tə ˈæn.ə.lɪst/", "pos": "n.", "zh": "数据分析师", "source": "as data analyst"}, {"en": "key accounts", "phonetic": "/kiː əˈkaʊnts/", "pos": "n. phr.", "zh": "关键客户；大客户", "source": "supporting key accounts"}, {"en": "further advance", "phonetic": "/ˈfɜːr.ðər ədˈvæns/", "pos": "v. phr.", "zh": "进一步发展；推进", "source": "further advance my career"}, {"en": "career", "phonetic": "/kəˈrɪr/", "pos": "n.", "zh": "职业；职业生涯", "source": "advance my career"}, {"en": "Master's degree", "phonetic": "/ˈmæs.tərz dɪˈɡriː/", "pos": "n.", "zh": "硕士学位", "source": "a Master's degree in economics"}, {"en": "in this role", "phonetic": "/ɪn ðɪs roʊl/", "pos": "phr.", "zh": "在这个岗位/职位上", "source": "in this role for almost 4 years"}], "grammar": [{"title": "现在分词短语作定语", "structure": "名词 + V-ing + 宾语", "example": "I went to Tsinghua as an undergraduate majoring in marketing.", "explanation": "majoring in...是现在分词短语，修饰前面的名词undergraduate，相当于who majored in...。让表达更紧凑。", "practice": "改写：I joined the company. I worked as a PM. -> I joined the company, ______ as a PM. (答案: working)"}, {"title": "Having been... 完成式分词作状语", "structure": "Having been + 状态 + 时间段, 主句", "example": "Having been in this role for almost 4 years, I feel it's time to further advance my career.", "explanation": "Having been是现在分词的完成式，表示主句动作之前已持续的状态。相当于'已经在...之后'。", "practice": "仿写：______ ______ in this company for 3 years, I feel ready for a new challenge. (答案: Having been)"}], "coreSentences": [{"original": "Please tell me a bit about yourself.", "function": "请求自我介绍", "alternative": "Walk me through your background. / Could you introduce yourself briefly?"}, {"original": "I went to Tsinghua University as an undergraduate majoring in marketing.", "function": "介绍教育背景", "alternative": "I graduated from...with a degree in... / I hold a Bachelor's degree in..."}, {"original": "I pursued a Master's degree in economics at Peking University.", "function": "介绍研究生学历", "alternative": "I earned my Master's in... / I completed a graduate program in..."}, {"original": "Upon graduation, I started my career as data analyst at Baidu.", "function": "介绍第一份工作", "alternative": "After graduating, I began working as... / My first role after college was..."}, {"original": "I left for Lenovo Group, supporting key accounts.", "function": "介绍跳槽", "alternative": "I moved on to...where I was responsible for... / I then joined...to..."}, {"original": "Having been in this role for almost 4 years, I feel it's time to further advance my career.", "function": "表达求职动机", "alternative": "After X years, I'm ready for the next challenge. / I'm looking to take my career to the next level."}], "exercises": {"vocabChoice": [{"question": "\"major in\" 的意思是？", "options": ["辅修", "主修", "专业是", "退学"], "answer": 1}, {"question": "\"upon graduation\" 相当于？", "options": ["毕业前", "毕业后/毕业时", "退学", "录取时"], "answer": 1}, {"question": "\"key accounts\" 指什么？", "options": ["关键账户", "钥匙账户", "重要客户/大客户", "账户密码"], "answer": 2}], "fillBlank": [{"sentence": "I ______ my Master's degree at Peking University.", "answer": "pursued", "hint": "攻读"}, {"sentence": "______ graduation, I started my career at Baidu.", "answer": "Upon", "hint": "在...之后/...时"}], "grammarChoice": [{"question": "在\"Having been in this role for 4 years\"中，Having been 表示：", "options": ["正在进行", "被动语态", "已完成/已持续的状态", "将来进行"], "answer": 2}], "sentenceReorder": [{"scrambled": ["university", "an undergraduate", "I went to", "as", "majoring in", "Tsinghua", "marketing"], "answer": "I went to Tsinghua University as an undergraduate majoring in marketing."}]}, "cultureNote": "西方自我介绍通常遵循'教育-工作-成就-求职动机'的时间线。不宜过于谦虚，也不宜过于自负。用具体的学校和公司名称会增加可信度。", "interviewTip": "自我介绍控制在1-2分钟内，不要背诵简历。建议按'教育->经历->为什么适合这个岗位'的逻辑，末尾加一句'我很期待这个角色因为...'来自然过渡。", "difficulty": "🟢入门"}, {"id": 22, "file": "22-工作经历问答1", "title": "工作经历问答1", "titleRaw": "22、工作经历描述", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Can you elaborate on your employment experience here in Lenovo?", "All right, my responsibility is to deliver projects to key accounts. I'd like to expand on my work scope in different phases of a project. In phase of initiation, I will engage with the business owner for the business requirement, and help produce business related documents if necessary."], "dialogueZH": ["你能详细说明一下你在联想的工作经历吗？", "好的。我的主要职责是为重点客户交付项目。我可以从项目的不同阶段来展开说明我的工作范围。在项目启动阶段，我会与业务负责人沟通业务需求，并在必要时协助产出与业务相关的文档。"], "vocabulary": [{"en": "elaborate on", "phonetic": "/ɪˈlæb.ər.eɪt ɑːn/", "pos": "v. phr.", "zh": "详细说明；展开阐述", "source": "Can you elaborate on your employment experience?"}, {"en": "deliver", "phonetic": "/dɪˈlɪv.ər/", "pos": "v.", "zh": "交付；传达", "source": "deliver projects to key accounts"}, {"en": "expand on", "phonetic": "/ɪkˈspænd ɑːn/", "pos": "v. phr.", "zh": "进一步展开说明", "source": "expand on my work scope"}, {"en": "phase of initiation", "phonetic": "/feɪz əv ɪˌnɪʃ.iˈeɪ.ʃən/", "pos": "n. phr.", "zh": "启动阶段", "source": "In phase of initiation"}, {"en": "engage with", "phonetic": "/ɪnˈɡeɪdʒ wɪð/", "pos": "v. phr.", "zh": "与...对接/沟通/互动", "source": "engage with the business owner"}, {"en": "business owner", "phonetic": "/ˈbɪz.nɪs ˈoʊ.nər/", "pos": "n.", "zh": "业务负责人/需求方", "source": "the business owner"}, {"en": "business requirement", "phonetic": "/ˈbɪz.nɪs rɪˈkwaɪr.mənt/", "pos": "n.", "zh": "业务需求", "source": "for the business requirement"}, {"en": "produce", "phonetic": "/prəˈduːs/", "pos": "v.", "zh": "产出；制作(文件/报告)", "source": "help produce business related documents"}, {"en": "work scope", "phonetic": "/wɜːrk skoʊp/", "pos": "n.", "zh": "工作范围", "source": "expand on my work scope"}], "grammar": [{"title": "I'd like to + 动词原形 (礼貌表达意愿)", "structure": "I would like to + 动词原形", "example": "I'd like to expand on my work scope in different phases of a project.", "explanation": "I'd like to = I would like to，是I want to的礼貌说法，面试中最常用的表达个人意愿的句型。", "practice": "仿写：I'd like to take this ______ to talk about my experience. (答案: opportunity)"}, {"title": "省略主谓的条件句 if necessary", "structure": "主句 + if + 形容词", "example": "I will help produce business related documents if necessary.", "explanation": "if necessary = if it is necessary，省略主谓，简短表达。类似：if possible, if needed, if any。", "practice": "仿写：Please let me know ______ ______. (答案: if possible)"}], "coreSentences": [{"original": "Can you elaborate on your employment experience?", "function": "请求详细说明", "alternative": "Could you walk me through your experience? / Could you tell me more about your background?"}, {"original": "My responsibility is to deliver projects to key accounts.", "function": "概括核心职责", "alternative": "My main role is to... / I'm primarily responsible for..."}, {"original": "I'd like to expand on my work scope in different phases.", "function": "展开叙述", "alternative": "Let me break it down by phases. / I'll walk you through each stage."}, {"original": "In the phase of initiation, I will engage with the business owner.", "function": "分阶段说明", "alternative": "During the initial phase, I... / At the kickoff stage, my responsibility is to..."}, {"original": "I will help produce business related documents if necessary.", "function": "说明辅助职责", "alternative": "I assist in creating...when needed. / I support the team in...as required."}], "exercises": {"vocabChoice": [{"question": "\"elaborate on\" 的意思是？", "options": ["忽略", "反驳", "详细说明", "拒绝"], "answer": 2}, {"question": "\"engage with\" 最接近的意思是？", "options": ["打架", "沟通对接", "离开", "忽略"], "answer": 1}], "fillBlank": [{"sentence": "Can you ______ on your work experience?", "answer": "elaborate", "hint": "详细说明"}, {"sentence": "I will ______ with the business owner for requirements.", "answer": "engage", "hint": "与...对接沟通"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "面试中面试官说'Can you elaborate on...'是想听具体的例子和细节，而非重复简历概括。这是面试中最高频的追问句式之一。", "interviewTip": "回答'Can you elaborate on...'时，用STAR法则(Situation-Task-Action-Result)来组织回答，每段控制在1分钟内。", "difficulty": "🔵中级"}, {"id": 23, "file": "23-工作经历问答2", "title": "工作经历问答2", "titleRaw": "23、工作经历描述2", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["In the phase of planning, I will engage with cross-functional departments to request resources and put together the project team, meanwhile I will draw up the project plan, which includes action items, relevant pics and expected timeline. After the plan is finalized, I will invite all stakeholders to have a kickoff meeting to walk through the project background, key milestones as well as requested deadline. After the meeting, I will put bullet points in meeting minutes and share in the group chat, making sure everyone is on the same page."], "dialogueZH": ["在项目规划阶段，我会与跨职能部门沟通以申请资源，并组建项目团队。同时，我会起草项目计划，其中包括行动项、相关负责人以及预期时间表。计划最终确定后，我会邀请所有相关方召开启动会议，介绍项目背景、关键里程碑以及要求的截止时间。会议结束后，我会将要点整理成会议纪要并分享到群聊中，确保所有人对项目理解一致。"], "vocabulary": [{"en": "cross-functional", "phonetic": "/krɔːs ˈfʌŋk.ʃən.əl/", "pos": "adj.", "zh": "跨职能的；跨部门的", "source": "cross-functional departments"}, {"en": "put together", "phonetic": "/pʊt təˈɡeð.ər/", "pos": "v. phr.", "zh": "组建；拼凑(团队/计划)", "source": "put together the project team"}, {"en": "draw up", "phonetic": "/drɔː ʌp/", "pos": "v. phr.", "zh": "起草；拟定(文件/计划)", "source": "draw up the project plan"}, {"en": "action items", "phonetic": "/ˈæk.ʃən ˈaɪ.təmz/", "pos": "n. phr.", "zh": "行动事项；待办任务", "source": "includes action items"}, {"en": "PIC (Person In Charge)", "phonetic": "/piː aɪ siː/", "pos": "n. abbr.", "zh": "负责人；对接人", "source": "relevant pics"}, {"en": "timeline", "phonetic": "/ˈtaɪm.laɪn/", "pos": "n.", "zh": "时间表；时间线", "source": "expected timeline"}, {"en": "stakeholders", "phonetic": "/ˈsteɪkˌhoʊl.dərz/", "pos": "n.", "zh": "利益相关方；相关人", "source": "invite all stakeholders"}, {"en": "kickoff meeting", "phonetic": "/ˈkɪk.ɔːf ˈmiː.tɪŋ/", "pos": "n.", "zh": "项目启动会", "source": "have a kickoff meeting"}, {"en": "milestones", "phonetic": "/ˈmaɪl.stoʊnz/", "pos": "n.", "zh": "里程碑；关键节点", "source": "key milestones"}, {"en": "walk through", "phonetic": "/wɔːk θruː/", "pos": "v. phr.", "zh": "逐项过一遍；详细讲解", "source": "walk through the project background"}, {"en": "on the same page", "phonetic": "/ɑːn ðə seɪm peɪdʒ/", "pos": "idiom", "zh": "达成共识；理解一致", "source": "everyone is on the same page"}, {"en": "bullet points", "phonetic": "/ˈbʊl.ɪt pɔɪnts/", "pos": "n.", "zh": "要点；条目式摘要", "source": "put bullet points in meeting minutes"}, {"en": "meeting minutes", "phonetic": "/ˈmiː.tɪŋ ˈmɪn.ɪts/", "pos": "n.", "zh": "会议纪要", "source": "in meeting minutes"}], "grammar": [{"title": "Which 引导的非限定性定语从句", "structure": "名词 + , + which + 从句", "example": "I will draw up the project plan, which includes action items, relevant pics and expected timeline.", "explanation": "which指代前面的project plan。逗号表示非限定性定语从句(补充信息)。去掉从句主句意思仍完整。", "practice": "仿写：I will write a report, ______ includes key findings. (答案: which)"}, {"title": "Making sure... 分词短语表目的", "structure": "主句, making sure + 从句", "example": "I will share in the group chat, making sure everyone is on the same page.", "explanation": "making sure表示动作的目的(确保...)，现在分词作伴随状语，可替换为to make sure。", "practice": "仿写：I will send an email, ______ ______ everyone is aware. (答案: making sure)"}], "coreSentences": [{"original": "I will engage with cross-functional departments to request resources.", "function": "跨部门协调", "alternative": "I coordinate with different teams to secure resources."}, {"original": "I will draw up the project plan.", "function": "制定计划", "alternative": "I draft the project blueprint. / I put together the project schedule."}, {"original": "I will invite all stakeholders to have a kickoff meeting.", "function": "组织会议", "alternative": "I bring all relevant parties together for a launch meeting."}, {"original": "I will walk through the project background, key milestones and deadlines.", "function": "介绍项目概况", "alternative": "I'll go over the project overview, major checkpoints, and deadlines."}, {"original": "Making sure everyone is on the same page.", "function": "确保共识", "alternative": "To ensure alignment across the team. / Making certain we're all in sync."}], "exercises": {"vocabChoice": [{"question": "\"stakeholders\" 的意思是？", "options": ["持股人", "利益相关方", "法官", "董事"], "answer": 1}, {"question": "\"on the same page\" 表示？", "options": ["在同一页上", "意见一致/理解相同", "读同一本书", "在同级别"], "answer": 1}, {"question": "\"draw up\" 最接近的意思是？", "options": ["画画", "起草/拟定", "拉起来", "撤销"], "answer": 1}], "fillBlank": [{"sentence": "I will ______ up the project plan.", "answer": "draw", "hint": "起草(与up搭配)"}, {"sentence": "Make sure everyone is on the same ______.", "answer": "page", "hint": "共识(固定搭配)"}], "grammarChoice": [], "sentenceReorder": [{"scrambled": ["stakeholders", "a kickoff meeting", "I", "invite", "will", "all"], "answer": "I will invite all stakeholders to have a kickoff meeting."}]}, "cultureNote": "西方项目管理中非常看重'stakeholder management'和'alignment'。反复出现的'on the same page'就是这种文化的典型体现——信息对称和共识比命令执行更重要。", "interviewTip": "描述工作流程时，用分阶段(phase by phase)的方式会让逻辑非常清晰。每个阶段点出1-2个关键词即可，不要陷入细节。", "difficulty": "🔵中级"}, {"id": 24, "file": "24-工作经历问答3", "title": "工作经历问答3", "titleRaw": "24、工作经历描述3", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Next it will be the phase of implementation, the main focus is to track the project on regular basis. My common practice is to have weekly or biweekly catch-ups with the team, where POCs from different sides update the status and report risks.", "Before the project is close to release, I will engage with tech team to make a go-live checklist and contingency plan, to ensure the launch is a success."], "dialogueZH": ["接下来就是项目实施阶段，主要重点是定期跟踪项目进展。我的常规做法是每周或每两周与团队进行一次例会，由各方的对接人更新项目状态并汇报风险。", "在项目接近发布前，我会与技术团队合作制定上线检查清单和应急预案，以确保项目顺利上线。"], "vocabulary": [{"en": "implementation", "phonetic": "/ˌɪm.plɪ.menˈteɪ.ʃən/", "pos": "n.", "zh": "实施；执行", "source": "the phase of implementation"}, {"en": "track", "phonetic": "/træk/", "pos": "v.", "zh": "追踪；跟踪", "source": "track the project"}, {"en": "on a regular basis", "phonetic": "/ɑːn ə ˈreɡ.jə.lɚ ˈbeɪ.sɪs/", "pos": "adv. phr.", "zh": "定期地", "source": "on regular basis"}, {"en": "catch-up", "phonetic": "/ˈkætʃ.ʌp/", "pos": "n.", "zh": "碰头会；进度同步会议", "source": "weekly or biweekly catch-ups"}, {"en": "biweekly", "phonetic": "/baɪˈwiːk.li/", "pos": "adj./adv.", "zh": "每两周一次的", "source": "weekly or biweekly"}, {"en": "POC (Point of Contact)", "phonetic": "/piː oʊ siː/", "pos": "n. abbr.", "zh": "对接人；联络人", "source": "POCs from different sides"}, {"en": "go-live", "phonetic": "/ɡoʊ laɪv/", "pos": "n./adj.", "zh": "上线；投产", "source": "go-live checklist"}, {"en": "contingency plan", "phonetic": "/kənˈtɪn.dʒən.si plæn/", "pos": "n.", "zh": "应急计划；备选方案", "source": "contingency plan"}, {"en": "launch", "phonetic": "/lɔːntʃ/", "pos": "n./v.", "zh": "发布；上线；推出", "source": "ensure the launch is a success"}, {"en": "checklist", "phonetic": "/ˈtʃek.lɪst/", "pos": "n.", "zh": "检查清单；核对表", "source": "a go-live checklist"}], "grammar": [{"title": "Where 引导的定语从句(非物理地点)", "structure": "名词(会议/场合/阶段) + where + 从句", "example": "My common practice is to have weekly catch-ups, where POCs update the status.", "explanation": "where不只指物理地点，也可指会议、情境、阶段等抽象场所。此处where指代catch-ups(碰头会)。", "practice": "仿写：We hold weekly meetings ______ each team reports progress. (答案: where)"}], "coreSentences": [{"original": "The main focus is to track the project on regular basis.", "function": "说明核心任务", "alternative": "The key priority is to monitor progress regularly. / The primary goal is ongoing tracking."}, {"original": "My common practice is to have weekly catch-ups with the team.", "function": "描述工作习惯", "alternative": "I typically hold weekly sync meetings. / My usual approach is to have regular check-ins."}, {"original": "POCs from different sides update the status and report risks.", "function": "描述例会内容", "alternative": "Team leads from each function share updates and flag risks."}, {"original": "I will engage with tech team to make a go-live checklist.", "function": "跨团队协作", "alternative": "I work with engineering to create a launch checklist."}, {"original": "To ensure the launch is a success.", "function": "表达目标", "alternative": "To guarantee a smooth rollout. / To make sure everything goes live without issues."}], "exercises": {"vocabChoice": [{"question": "\"contingency plan\" 的意思是？", "options": ["连续计划", "应急计划/备用方案", "保险计划", "旅行计划"], "answer": 1}, {"question": "\"go-live\" 指什么？", "options": ["去生活", "上线/投产", "直播", "离开"], "answer": 1}, {"question": "\"on a regular basis\" 表示？", "options": ["在规则基础上", "偶尔", "定期地", "一次性地"], "answer": 2}], "fillBlank": [{"sentence": "We track the project on a ______ basis.", "answer": "regular", "hint": "定期的"}, {"sentence": "I will make a go-live ______ to ensure a smooth launch.", "answer": "checklist", "hint": "检查清单"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "在西方项目管理中，'catch-up'是最常见的轻量级会议形式，暗示简短、轻松、高频的沟通文化。", "interviewTip": "用'weekly/biweekly catch-ups'替代'regular meetings'显得更地道。面试中用正确的术语(go-live、contingency plan)展示你的专业度。", "difficulty": "🔵中级"}, {"id": 25, "file": "25-风险管理", "title": "风险管理", "titleRaw": "25、能力考察", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["All right, impressive. Then how do you usually deal with risks?", "Whenever risks arise during implementation, my common practice is to first evaluate the impacts. If the final delivery is affected, I will pull relevant people together to work out the solution. Meanwhile, I will give a heads-up to the business owner and keep all relevant stakeholders in the loop until the risks are finally defused."], "dialogueZH": ["好的，令人印象深刻。那么你通常是如何处理风险的？", "每当在实施阶段出现风险时，我的常规做法是先评估其影响。如果会影响最终交付，我会把相关人员召集起来共同制定解决方案。同时，我会提前向业务负责人预警，并让所有相关干系人保持同步，直到风险被完全化解。"], "vocabulary": [{"en": "impressive", "phonetic": "/ɪmˈpres.ɪv/", "pos": "adj.", "zh": "令人印象深刻的", "source": "All right, impressive."}, {"en": "deal with", "phonetic": "/diːl wɪð/", "pos": "v. phr.", "zh": "处理；应对", "source": "how do you usually deal with risks"}, {"en": "arise", "phonetic": "/əˈraɪz/", "pos": "v.", "zh": "出现；产生", "source": "Whenever risks arise"}, {"en": "evaluate", "phonetic": "/ɪˈvæl.ju.eɪt/", "pos": "v.", "zh": "评估；评价", "source": "evaluate the impacts"}, {"en": "pull together", "phonetic": "/pʊl təˈɡeð.ər/", "pos": "v. phr.", "zh": "召集(人员)；集中(资源)", "source": "pull relevant people together"}, {"en": "work out", "phonetic": "/wɜːrk aʊt/", "pos": "v. phr.", "zh": "制定出；解决；算出", "source": "work out the solution"}, {"en": "escalate", "phonetic": "/ˈes.kə.leɪt/", "pos": "v.", "zh": "升级；向上汇报", "source": "escalate to my business lead"}, {"en": "heads-up", "phonetic": "/ˈhedz.ʌp/", "pos": "n.", "zh": "预警；提前通知", "source": "give a heads-up"}, {"en": "keep sb. posted", "phonetic": "/kiːp ˈpoʊ.stɪd/", "pos": "idiom", "zh": "保持信息同步；随时告知进展", "source": "keep all relevant stakeholders posted"}, {"en": "in the loop", "phonetic": "/ɪn ðə luːp/", "pos": "idiom", "zh": "在信息圈内；知情", "source": "keep ... in the loop"}, {"en": "defused", "phonetic": "/dɪˈfjuːzd/", "pos": "adj.", "zh": "被化解的；被缓和的", "source": "until the risks are finally defused"}], "grammar": [{"title": "Whenever 引导时间状语从句(强调重复习惯)", "structure": "Whenever + 从句, 主句", "example": "Whenever risks arise during implementation, my common practice is to first evaluate the impacts.", "explanation": "Whenever = every time / at any time when。比when更强调'每次都会这样做'的惯例。", "practice": "仿写：______ an issue comes up, I analyze the cause first. (答案: Whenever)"}, {"title": "If 条件句 + 被动语态", "structure": "If + 主语 + be + 过去分词, 主句", "example": "If the final delivery is affected, I will pull relevant people together.", "explanation": "使用被动语态(is affected)使表达更加客观，是商务英语中常见的表达方式。", "practice": "仿写：If the deadline is ______ (risk), I will inform the PM. (答案: at risk / threatened)"}], "coreSentences": [{"original": "How do you usually deal with risks?", "function": "行为面试提问", "alternative": "How do you handle unexpected challenges? / What's your approach to managing risks?"}, {"original": "Whenever risks arise, my common practice is to first evaluate the impacts.", "function": "描述应对流程", "alternative": "When issues come up, I always start by assessing the impact."}, {"original": "I will pull relevant people together to work out the solution.", "function": "团队协作解决问题", "alternative": "I bring the right people together to figure out a fix."}, {"original": "I will give a heads-up to the business owner.", "function": "提前预警", "alternative": "I flag potential issues to my manager in advance. / I give early warning to stakeholders."}, {"original": "Keep all relevant stakeholders in the loop until the risks are fully defused.", "function": "强调持续沟通", "alternative": "Keep everyone updated until the issue is completely resolved."}], "exercises": {"vocabChoice": [{"question": "\"escalate\" 在工作场景中的意思是？", "options": ["上电梯", "降低", "升级汇报", "加速"], "answer": 2}, {"question": "\"keep sb. in the loop\" 表示？", "options": ["把某人困住", "保持信息同步/让某人知情", "发布公告", "联系某人"], "answer": 1}, {"question": "\"heads-up\" 的意思是？", "options": ["抬头", "预警/提前通知", "头向上", "帽子"], "answer": 1}], "fillBlank": [{"sentence": "Whenever risks ______, I evaluate the impacts first.", "answer": "arise", "hint": "出现"}, {"sentence": "I will give a ______-______ to the business owner.", "answer": "heads-up", "hint": "预警/提前通知"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方职场非常看重'risk management'和'escalation'能力。主动识别风险并给出解决方案被视为成熟的表现，而非能力不足。提前预警(heads-up)是非常重要的工作习惯。", "interviewTip": "回答风险管理类问题，展示你的框架思维(评估-方案-执行-同步)，用具体例子佐证。使用escalate、in the loop、heads-up等专业术语提分。", "difficulty": "🔵中级"}, {"id": 26, "file": "26-业务成就", "title": "业务成就", "titleRaw": "26、业绩亮点", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Okay, what do you consider to be your greatest accomplishment?", "Sure, we outsourced a portion of one project to the 3rd-party company. After the first phase, I was assigned to take over because the previous project manager left. I quickly got up to speed on the details and realized that some work could be done by our own because we already had the capabilities in place. I only spent half a day figuring things out and we were charged 35% less for the second phase."], "dialogueZH": ["好的，你认为自己最大的成就是什么？", "去年，我被指派接手一个外包给第三方供应商的项目。之前的项目经理已经离职，所以我必须迅速熟悉项目细节。在审阅项目范围后，我意识到其中有一部分工作其实可以由内部团队完成，因为我们已经具备相关能力。通过梳理情况并重新分配工作量，我们在项目第二阶段成功将成本降低了 35%。这是我们当时负责的项目。"], "vocabulary": [{"en": "accomplishment", "phonetic": "/əˈkɑːm.plɪʃ.mənt/", "pos": "n.", "zh": "成就；成绩", "source": "your greatest accomplishment"}, {"en": "outsource", "phonetic": "/ˈaʊt.sɔːrs/", "pos": "v.", "zh": "外包；外判", "source": "outsourced a portion of one project"}, {"en": "3rd-party", "phonetic": "/θɜːrd ˈpɑːr.ti/", "pos": "adj.", "zh": "第三方的", "source": "the 3rd-party company"}, {"en": "take over", "phonetic": "/teɪk ˈoʊ.vər/", "pos": "v. phr.", "zh": "接手；接管", "source": "assigned to take over"}, {"en": "get up to speed", "phonetic": "/ɡet ʌp tə spiːd/", "pos": "idiom", "zh": "迅速熟悉/跟上进度", "source": "got up to speed on the details"}, {"en": "capabilities", "phonetic": "/ˌkeɪ.pəˈbɪl.ə.tiz/", "pos": "n.", "zh": "能力；功能", "source": "had the capabilities in place"}, {"en": "figure out", "phonetic": "/ˈfɪɡ.jər aʊt/", "pos": "v. phr.", "zh": "弄清楚；想明白", "source": "figuring things out"}, {"en": "charged", "phonetic": "/tʃɑːrdʒd/", "pos": "v.", "zh": "收费；索价", "source": "were charged 35% less"}], "grammar": [{"title": "被动语态 in \"I was assigned\"", "structure": "be + 过去分词", "example": "I was assigned to take over because the previous project manager left.", "explanation": "被动语态在商务英语中常用于强调动作的承受者，而非执行者。I was assigned比They assigned me更符合职场叙述习惯。", "practice": "仿写：我被要求在一周内完成报告。I ______ ______ to complete the report within a week. (答案: was asked)"}], "coreSentences": [{"original": "What do you consider to be your greatest accomplishment?", "function": "面试经典提问(成就)", "alternative": "What achievement are you most proud of? / Tell me about a time you made a significant impact."}, {"original": "I was assigned to take over because the previous project manager left.", "function": "说明接手背景", "alternative": "I stepped in when the previous PM departed. / I inherited this project when..."}, {"original": "I quickly got up to speed on the details.", "function": "描述快速上手", "alternative": "I rapidly familiarized myself with the project. / I quickly came up to speed."}, {"original": "I realized that some work could be done by our own team.", "function": "描述发现问题", "alternative": "I identified an opportunity to in-source part of the work. / I noticed we had the capability to handle it internally."}, {"original": "We were charged 35% less for the second phase.", "function": "量化成就", "alternative": "We reduced costs by 35% in the subsequent phase. / We achieved a 35% cost saving."}], "exercises": {"vocabChoice": [{"question": "\"take over\" 的意思是？", "options": ["拿走", "接手/接管", "翻转", "删除"], "answer": 1}, {"question": "\"get up to speed\" 表示？", "options": ["加速跑步", "迅速熟悉/跟上进度", "站起来", "快速的"], "answer": 1}, {"question": "\"outsource\" 的意思是？", "options": ["内部开发", "外包", "招聘", "出口"], "answer": 1}], "fillBlank": [{"sentence": "I quickly got up to ______ on the project details.", "answer": "speed", "hint": "跟上进度(固定搭配)"}, {"sentence": "I was assigned to ______ over the project.", "answer": "take", "hint": "接手"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方面试中，'greatest accomplishment'问题期望你用STAR法则回答。关键是用具体数字量化成就(如35%成本削减)，而非只讲过程。数字是最有说服力的证据。", "interviewTip": "成就描述一定要有数字！成本降了多少、效率提了多少、时间省了多少。没有数据的成就在面试中显得苍白。另外，主动发现机会(+内部化外包)比被动完成任务更能体现价值。", "difficulty": "🔵中级"}, {"id": 27, "file": "27-失败教训", "title": "失败教训", "titleRaw": "27、失败教训", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Could you describe one experience you failed to meet the deadline?", "With proper planning and effective execution, normally I think it’s hard to miss the deadline. But once in the middle of one project, our clients requested to change one assignment that we already completed. We estimated the changes and informed them of a possible delay, at least 5 more days were needed even if we put in extra hours. Initially they didn’t buy it but finally compromised as it was due to their own reason. Afterwards, I solicited opinions from both ends and established an SOP to avoid similar issues in the future."], "dialogueZH": ["你能描述一次你未能按时完成任务的经历吗？", "尽管我们做了充分的规划和执行，但有一次我们确实没能按时交付。客户在我们已经完成任务后提出了修改要求。我们告知他们这会导致延期，并评估了所需的额外时间。同时，我们也加班加点以尽量加快进度。起初客户并不接受，但最终他们做出了妥协。项目交付后，我们向双方征求了意见，并制定了标准作业流程（SOP），以避免类似情况再次发生。"], "vocabulary": [{"en": "meet the deadline", "phonetic": "/miːt ðə ˈded.laɪn/", "pos": "v. phr.", "zh": "按时完成；赶上截止日期", "source": "failed to meet the deadline"}, {"en": "proper planning", "phonetic": "/ˈprɑː.pər ˈplæn.ɪŋ/", "pos": "n. phr.", "zh": "适当的规划", "source": "With proper planning"}, {"en": "effective execution", "phonetic": "/ɪˈfek.tɪv ˌek.sɪˈkjuː.ʃən/", "pos": "n. phr.", "zh": "有效执行", "source": "effective execution"}, {"en": "client", "phonetic": "/ˈklaɪ.ənt/", "pos": "n.", "zh": "客户", "source": "our clients requested"}, {"en": "estimate", "phonetic": "/ˈes.tɪ.meɪt/", "pos": "v.", "zh": "估计；评估", "source": "We estimated the changes"}, {"en": "delay", "phonetic": "/dɪˈleɪ/", "pos": "n./v.", "zh": "延迟；延期", "source": "a possible delay"}, {"en": "put in extra hours", "phonetic": "/pʊt ɪn ˈek.strə aʊərz/", "pos": "v. phr.", "zh": "加班", "source": "even if we put in extra hours"}, {"en": "didn't buy it", "phonetic": "/dɪdnt baɪ ɪt/", "pos": "idiom", "zh": "不接受；不买账", "source": "they didn't buy it"}, {"en": "compromise", "phonetic": "/ˈkɑːm.prə.maɪz/", "pos": "v.", "zh": "妥协；让步", "source": "finally compromised"}, {"en": "solicit", "phonetic": "/səˈlɪs.ɪt/", "pos": "v.", "zh": "征求(意见)；请求", "source": "solicited opinions from both ends"}, {"en": "SOP (Standard Operating Procedure)", "phonetic": "/es oʊ piː/", "pos": "n. abbr.", "zh": "标准作业流程", "source": "established an SOP"}], "grammar": [{"title": "With + 名词短语 作状语(表示条件/方式)", "structure": "With + n. + and + n., 主句", "example": "With proper planning and effective execution, normally I think it's hard to miss the deadline.", "explanation": "With + 名词短语表示'在...的条件下'，相当于条件状语。让表达简洁有力。", "practice": "仿写：______ careful preparation, I think we can succeed. (答案: With)"}, {"title": "It's hard to + 动词原形", "structure": "It + be + adj. + to + 动词原形", "example": "I think it's hard to miss the deadline.", "explanation": "it作形式主语，真正的主语是to miss the deadline。避免头重脚轻。", "practice": "仿写：It's important to ______ (communicate) with clients early. (答案: communicate)"}], "coreSentences": [{"original": "Could you describe one experience you failed to meet the deadline?", "function": "面试经典提问(失败)", "alternative": "Tell me about a time you missed a deadline. / Walk me through a project that didn't go as planned."}, {"original": "With proper planning and effective execution, normally it's hard to miss the deadline.", "function": "铺垫背景(先扬后抑)", "alternative": "Generally speaking, with solid preparation, things go smoothly. But..."}, {"original": "We estimated the changes and informed them of a possible delay.", "function": "主动评估并沟通", "alternative": "We assessed the impact and communicated the timeline risk proactively."}, {"original": "Initially they didn't buy it but finally compromised.", "function": "描述客户态度转变", "alternative": "At first they pushed back, but eventually they came around. / They resisted initially, then agreed."}, {"original": "I established an SOP to avoid similar issues in the future.", "function": "总结教训+改进措施", "alternative": "I created a standard process to prevent this from happening again. / We institutionalized the lesson learned."}], "exercises": {"vocabChoice": [{"question": "\"meet the deadline\" 的意思是？", "options": ["见面截止日期", "按时完成/赶上截止日期", "避开截止日期", "设定截止日期"], "answer": 1}, {"question": "\"didn't buy it\" 在这里的意思是？", "options": ["没买", "不接受/不买账", "没花钱买", "买了便宜货"], "answer": 1}, {"question": "\"SOP\" 是什么的缩写？", "options": ["Standard Operating Procedure", "Special Order Process", "System Operation Plan", "Standard Output Protocol"], "answer": 0}], "fillBlank": [{"sentence": "We failed to ______ the deadline due to unexpected changes.", "answer": "meet", "hint": "赶上/按时完成"}, {"sentence": "We ______ opinions from both sides to improve the process.", "answer": "solicited", "hint": "征求(意见)"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方面试中'失败教训'问题是检验诚实度和成长性的关键。回答公式：承认失败 + 说明背景 + 你做了什么补救 + 学到了什么 + 如何防止复发。最重要的是展示你从失败中成长的能力。", "interviewTip": "失败教训不要选致命错误(如泄密/严重失职)，也不要选太小的失误。理想的素材是：因流程缺陷导致的困难，你主动沟通解决了问题，并建立了SOP。这正是本场景展示的模式。", "difficulty": "🔵中级"}, {"id": 28, "file": "28-岗位匹配度", "title": "岗位匹配度", "titleRaw": "28.经验匹配度", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["This position requires much client-facing work, what do you bring to the table in terms of customer interaction?", "To start with, I'm a people person. I've always been proactive in building relationships, and I think this is born out in my previous experiences. For example, I was a co-founder of my college debate club, and networked with different kinds of people to hold debate contests. During my experience at Lenovo, I was also extensively involved in meetings with our clients."], "dialogueZH": ["这个岗位需要大量与客户直接沟通的工作，你在客户互动方面能带来什么优势？", "首先，我是一个非常擅长与人打交道的人。我一直都很主动地建立关系，这一点在我过去的经历中也有所体现。比如，我是大学辩论社的联合创始人，需要与各种不同背景的人沟通来组织辩论比赛。在联想的工作经历中，我也经常参与与客户的会议。"], "vocabulary": [{"en": "client-facing", "phonetic": "/ˈklaɪ.ənt ˈfeɪ.sɪŋ/", "pos": "adj.", "zh": "面向客户的；对客的", "source": "much client-facing work"}, {"en": "bring to the table", "phonetic": "/brɪŋ tə ðə ˈteɪ.bəl/", "pos": "idiom", "zh": "(你能)带来什么；贡献什么", "source": "what do you bring to the table"}, {"en": "people person", "phonetic": "/ˈpiː.pəl ˈpɜːr.sən/", "pos": "n.", "zh": "善于交际的人；人缘好的人", "source": "I'm a people person"}, {"en": "proactive", "phonetic": "/proʊˈæk.tɪv/", "pos": "adj.", "zh": "积极主动的；主动出击的", "source": "I've always been proactive"}, {"en": "build relationships", "phonetic": "/bɪld rɪˈleɪ.ʃən.ʃɪps/", "pos": "v. phr.", "zh": "建立关系", "source": "proactive in building relationships"}, {"en": "born out", "phonetic": "/bɔːrn aʊt/", "pos": "v. phr.", "zh": "体现；证实(from borne out)", "source": "this is born out in my previous experiences"}, {"en": "co-founder", "phonetic": "/koʊ ˈfaʊn.dər/", "pos": "n.", "zh": "联合创始人", "source": "a co-founder of my college debate club"}, {"en": "network", "phonetic": "/ˈnet.wɜːrk/", "pos": "v.", "zh": "建立人脉；社交", "source": "networked with different kinds of people"}, {"en": "extensively", "phonetic": "/ɪkˈsten.sɪv.li/", "pos": "adv.", "zh": "广泛地；大量地", "source": "extensively involved in meetings"}], "grammar": [{"title": "What do you bring to the table? (习语疑问句)", "structure": "What do you bring to the table?", "example": "What do you bring to the table in terms of customer interaction?", "explanation": "What do you bring to the table?是面试高频提问，字面'你给桌子上带来什么'，实际意思'你有什么优势/贡献'。in terms of = 在...方面。", "practice": "仿写：在数据分析方面，你带来什么优势？What do you ______ to the table ______ ______ data analysis? (答案: bring, in terms of)"}], "coreSentences": [{"original": "This position requires much client-facing work.", "function": "说明岗位要求", "alternative": "This role involves significant customer interaction. / The position is heavily client-focused."}, {"original": "What do you bring to the table in terms of customer interaction?", "function": "问你能贡献什么", "alternative": "What strengths can you offer in this area? / What sets you apart in client engagement?"}, {"original": "I'm a people person.", "function": "自述性格优势", "alternative": "I thrive on interpersonal interaction. / I'm naturally sociable and communicative."}, {"original": "I've always been proactive in building relationships.", "function": "描述行为习惯", "alternative": "I take the initiative to connect with people. / I actively seek to establish rapport."}, {"original": "This is born out in my previous experiences.", "function": "用经历佐证", "alternative": "My track record shows this. / My past experience confirms this."}], "exercises": {"vocabChoice": [{"question": "\"people person\" 是什么意思？", "options": ["人口专家", "善于交际的人", "普通人", "个人主义者"], "answer": 1}, {"question": "\"bring to the table\" 表示？", "options": ["端菜上桌", "带来贡献/提供价值", "带到桌子", "放在桌上"], "answer": 1}, {"question": "\"proactive\" 的意思是？", "options": ["被动的", "积极主动的", "专业的", "生产性的"], "answer": 1}], "fillBlank": [{"sentence": "I'm a ______ person and enjoy client-facing work.", "answer": "people", "hint": "善于交际(固定表达)"}, {"sentence": "What do you ______ to the table?", "answer": "bring", "hint": "带来/贡献"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "'People person'是西方面试中非常高频的自述词，但光说不够，必须用具体例子证明。'Bring to the table'是地道的商务习语，面试官常用。", "interviewTip": "当被问'你能带来什么'时，不要只列技能，要关联到岗位需求。先说你有什么特质(people person)，再用具体经历证明(辩论社、客户会议)，最后说明这个特质如何帮到这个岗位。", "difficulty": "🔵中级"}, {"id": 29, "file": "29-职场冲突处理", "title": "职场冲突处理", "titleRaw": "29、职场情商", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["What do you do when you are at odds with others?", "First I’m a candid and upfront person, and don’t like to bottle up my ideas. I can deal with different kinds of people very well. When I have different ideas with others, I tend to bring it to the table and try to address the differences to everyone’s satisfaction, so I can also work without distractions. I believe the best way to iron out differences is to walk in each other’s shoes."], "dialogueZH": ["当我和别人意见不一致时，我会怎么处理？", "首先，我是一个坦诚直接的人，不喜欢把想法憋在心里。我也非常擅长与不同类型的人相处。当我和别人有不同观点时，我通常会把问题摆到桌面上来讨论，努力找到让各方都满意的解决方式，这样我自己也能专注工作、不受干扰。我相信，化解分歧的最佳方式就是设身处地地理解对方。"], "vocabulary": [{"en": "at odds with", "phonetic": "/æt ɑːdz wɪð/", "pos": "idiom", "zh": "与...意见不合；与...有分歧", "source": "at odds with others"}, {"en": "candid", "phonetic": "/ˈkæn.dɪd/", "pos": "adj.", "zh": "坦诚的；直言不讳的", "source": "a candid and upfront person"}, {"en": "upfront", "phonetic": "/ʌpˈfrʌnt/", "pos": "adj.", "zh": "坦率的；直截了当的", "source": "candid and upfront"}, {"en": "bottle up", "phonetic": "/ˈbɑː.təl ʌp/", "pos": "v. phr.", "zh": "压抑；憋在心里", "source": "don't like to bottle up my ideas"}, {"en": "bring it to the table", "phonetic": "/brɪŋ ɪt tə ðə ˈteɪ.bəl/", "pos": "idiom", "zh": "把问题摆上台面讨论", "source": "bring it to the table"}, {"en": "address", "phonetic": "/əˈdres/", "pos": "v.", "zh": "处理；解决(问题)", "source": "address the differences"}, {"en": "to everyone's satisfaction", "phonetic": "/tə ˈev.ri.wʌnz ˌsæt.ɪsˈfæk.ʃən/", "pos": "phr.", "zh": "到每个人都满意", "source": "to everyone's satisfaction"}, {"en": "iron out", "phonetic": "/ˈaɪ.ərn aʊt/", "pos": "v. phr.", "zh": "消除；解决(分歧/问题)", "source": "iron out differences"}, {"en": "walk in each other's shoes", "phonetic": "/wɔːk ɪn iːtʃ ˈʌð.ərz ʃuːz/", "pos": "idiom", "zh": "换位思考；站在对方角度看问题", "source": "walk in each other's shoes"}], "grammar": [{"title": "When 引导的时间状语从句 + 现在时表惯例", "structure": "When + 主语 + 现在时, 主语 + tend to + 动词原形", "example": "When I have different ideas with others, I tend to bring it to the table.", "explanation": "When从句用一般现在时，主句用tend to表示习惯性的行为模式。这是行为面试回答的标准句式。", "practice": "仿写：When conflicts arise, I tend to ______ (seek) common ground first. (答案: seek)"}], "coreSentences": [{"original": "What do you do when you are at odds with others?", "function": "行为面试提问(冲突处理)", "alternative": "How do you handle disagreements at work? / Tell me about a time you had a conflict at work."}, {"original": "I'm a candid and upfront person, and don't like to bottle up my ideas.", "function": "自述沟通风格", "alternative": "I prefer open and direct communication. / I believe in transparent conversations."}, {"original": "I bring it to the table and try to address the differences to everyone's satisfaction.", "function": "描述冲突处理方法", "alternative": "I raise the issue openly and work toward a win-win solution. / I discuss differences openly to find common ground."}, {"original": "The best way to iron out differences is to walk in each other's shoes.", "function": "总结心得", "alternative": "The key to resolving conflicts is empathy and perspective-taking. / Understanding the other side is the first step to resolution."}], "exercises": {"vocabChoice": [{"question": "\"at odds with\" 的意思是？", "options": ["很奇怪", "与...意见不合", "与...打赌", "奇数"], "answer": 1}, {"question": "\"bottle up\" 表示？", "options": ["装瓶", "压抑/憋在心里", "喝酒", "保存"], "answer": 1}, {"question": "\"walk in each other's shoes\" 的意思？", "options": ["穿别人的鞋", "换位思考/设身处地", "走路", "买新鞋"], "answer": 1}], "fillBlank": [{"sentence": "I don't like to ______ up my ideas.", "answer": "bottle", "hint": "压抑/憋着"}, {"sentence": "The best way to iron out differences is to walk in each other's ______.", "answer": "shoes", "hint": "换位思考(固定习语)"}], "grammarChoice": [], "sentenceReorder": [{"scrambled": ["differences", "to iron out", "is to walk", "The best way", "shoes", "in each other's"], "answer": "The best way to iron out differences is to walk in each other's shoes."}]}, "cultureNote": "西方职场鼓励'candid feedback'和直接沟通，'bottle up'(压抑不说)被视为不健康的沟通方式。但同时强调表达方式要尊重(iron out而非confront)。这是西方面试中情商考察的典型问题。", "interviewTip": "回答冲突处理类问题，展示'直接但不粗暴'的平衡。强调你主动沟通(不逃避)、寻求共赢(不独断)、换位思考(不固执)。使用iron out、walk in shoes等习语展示地道表达。", "difficulty": "🔵中级"}, {"id": 30, "file": "30-加班与压力", "title": "加班与压力", "titleRaw": "30、看待加班", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["What do you think of working OT?", "First, I don't mind working overtime, but personally I am not really in favor of excessive OT. With proper planning of resources, some unnecessary overtime can be avoided. For instance, whenever I am delegated with tasks, I usually schedule my work beforehand, and prioritize the tasks based on urgency and importance. With that being said, in some scenarios when clients require us to work overtime or some urgent deadlines require us to do so, I don't mind at all because it is all for the sake of work."], "dialogueZH": ["你怎么看待加班？", "首先，我不介意加班，但我个人并不赞成过度加班。通过合理规划资源，很多不必要的加班是可以避免的。比如，当我被分配任务时，我通常会提前安排好工作，并根据紧急性和重要性来排序优先级。话虽如此，在某些情况下，如果客户要求加班，或者有紧急的截止时间需要我们加班，我完全不介意，因为这是为了工作本身。"], "vocabulary": [{"en": "OT (Overtime)", "phonetic": "/ˈoʊ.vər.taɪm/", "pos": "n. abbr.", "zh": "加班", "source": "What do you think of working OT?"}, {"en": "don't mind", "phonetic": "/doʊnt maɪnd/", "pos": "v. phr.", "zh": "不介意", "source": "I don't mind working overtime"}, {"en": "in favor of", "phonetic": "/ɪn ˈfeɪ.vər əv/", "pos": "phr.", "zh": "赞成；支持", "source": "not really in favor of"}, {"en": "excessive", "phonetic": "/ɪkˈses.ɪv/", "pos": "adj.", "zh": "过度的；过多的", "source": "excessive OT"}, {"en": "proper planning", "phonetic": "/ˈprɑː.pər ˈplæn.ɪŋ/", "pos": "n. phr.", "zh": "合理规划", "source": "With proper planning of resources"}, {"en": "delegate", "phonetic": "/ˈdel.ɪ.ɡeɪt/", "pos": "v.", "zh": "委派；分配(任务)", "source": "I am delegated with tasks"}, {"en": "prioritize", "phonetic": "/praɪˈɔːr.ɪ.taɪz/", "pos": "v.", "zh": "按优先级排序", "source": "prioritize the tasks"}, {"en": "urgency", "phonetic": "/ˈɜːr.dʒən.si/", "pos": "n.", "zh": "紧急程度", "source": "based on urgency and importance"}, {"en": "for the sake of", "phonetic": "/fər ðə seɪk əv/", "pos": "phr.", "zh": "为了...；看在...的份上", "source": "for the sake of work"}], "grammar": [{"title": "With that being said (转折过渡句)", "structure": "With that being said, + 转折句", "example": "With that being said, in some scenarios when clients require us to work overtime, I don't mind at all.", "explanation": "With that being said = '话虽如此'。用于承认前面观点后引出例外情况。是面试中非常地道的转折表达。类似：That said, ... / Having said that, ...", "practice": "仿写：I prefer to avoid overtime. ______ ______ ______ ______, I'm happy to stay late when there's an urgent deadline. (答案: With that being said)"}], "coreSentences": [{"original": "What do you think of working OT?", "function": "面试提问(加班态度)", "alternative": "How do you feel about overtime? / What's your view on working extra hours?"}, {"original": "I don't mind working overtime, but I'm not really in favor of excessive OT.", "function": "表达平衡观点", "alternative": "I'm okay with occasional overtime, but I don't believe in overwork as a norm."}, {"original": "With proper planning, some unnecessary overtime can be avoided.", "function": "展示效率思维", "alternative": "Better planning can eliminate a lot of unnecessary extra hours."}, {"original": "I prioritize the tasks based on urgency and importance.", "function": "描述时间管理方法", "alternative": "I sort tasks by urgency and importance. / I use a priority matrix to manage workload."}, {"original": "I don't mind at all because it is all for the sake of work.", "function": "表达尽责态度", "alternative": "I'm fully on board when it's truly necessary for the project. / I'm committed to doing what it takes."}], "exercises": {"vocabChoice": [{"question": "\"OT\" 是什么的缩写？", "options": ["Off Time", "Overtime", "On Time", "Over Time"], "answer": 1}, {"question": "\"excessive\" 的意思是？", "options": ["足够的", "过度的/过多的", "优秀的", "排除的"], "answer": 1}, {"question": "\"prioritize\" 表示？", "options": ["忽略", "按优先级排序", "推迟", "优先权"], "answer": 1}], "fillBlank": [{"sentence": "With proper ______, unnecessary overtime can be avoided.", "answer": "planning", "hint": "规划"}, {"sentence": "I ______ tasks based on urgency and importance.", "answer": "prioritize", "hint": "按优先级排序"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "在西方职场，加班(OT)通常被视为效率问题而非奉献问题。雇主期望你靠prioritization和planning避免加班，而非以加班为荣。但在必要时刻愿意flexible也被看重。回答要体现这种平衡。", "interviewTip": "加班问题没有标准答案，关键是展示你有思考。先表态(不介意合理加班)，再展示方法论(规划避免不必要加班)，最后留例外(紧急时全力以赴)。这样既不做workaholic也不做slacker。", "difficulty": "🔵中级"}, {"id": 31, "file": "31-职位匹配", "title": "职位匹配", "titleRaw": "31、职位匹配度", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Okay, got that. So why do you think this is the right job for you?", "All right. First off, I possess the experience and qualifications you are looking for. I'm a great team player that can keep the team together and I excel in building strong and long-term customer relationships, which I am sure will contribute to your organization. On top of that, I'm passionate and ambitious about this industry and will always give 100%. So I consider myself the perfect fit for this position."], "dialogueZH": ["好的，我明白了。那么你为什么认为这份工作适合你？", "首先，我具备你们所寻找的经验和资质。我是一个优秀的团队合作型人才，能够让团队保持凝聚力，并且我在建立稳固且长期的客户关系方面表现出色，我相信这会为贵公司带来价值。除此之外，我对这个行业充满热情和抱负，并且始终全力以赴。因此，我认为自己非常适合这个职位。"], "vocabulary": [{"en": "first off", "phonetic": "/fɜːrst ɔːf/", "pos": "adv. phr.", "zh": "首先(比first更口语)", "source": "First off, I possess..."}, {"en": "possess", "phonetic": "/pəˈzes/", "pos": "v.", "zh": "拥有；具备", "source": "I possess the experience and qualifications"}, {"en": "qualifications", "phonetic": "/ˌkwɑː.lɪ.fɪˈkeɪ.ʃənz/", "pos": "n.", "zh": "资质；资格", "source": "experience and qualifications"}, {"en": "team player", "phonetic": "/tiːm ˈpleɪ.ər/", "pos": "n.", "zh": "有团队精神的人；善于合作的人", "source": "I'm a great team player"}, {"en": "keep the team together", "phonetic": "/kiːp ðə tiːm təˈɡeð.ər/", "pos": "v. phr.", "zh": "保持团队凝聚力", "source": "can keep the team together"}, {"en": "excel in", "phonetic": "/ɪkˈsel ɪn/", "pos": "v. phr.", "zh": "在...方面出色；擅长", "source": "I excel in building strong relationships"}, {"en": "on top of that", "phonetic": "/ɑːn tɑːp əv ðæt/", "pos": "phr.", "zh": "除此之外；而且", "source": "On top of that, I'm passionate"}, {"en": "passionate", "phonetic": "/ˈpæʃ.ən.ət/", "pos": "adj.", "zh": "充满热情的", "source": "I'm passionate about this industry"}, {"en": "give 100%", "phonetic": "/ɡɪv wʌn ˈhʌn.drəd pərˈsent/", "pos": "idiom", "zh": "全力以赴", "source": "will always give 100%"}, {"en": "perfect fit", "phonetic": "/ˈpɜːr.fɪkt fɪt/", "pos": "n. phr.", "zh": "完美匹配；非常合适", "source": "I consider myself the perfect fit"}], "grammar": [{"title": "Which引导的非限定性定语从句(补充说明)", "structure": "...名词, which + 从句", "example": "I excel in building strong and long-term customer relationships, which I am sure will contribute to your organization.", "explanation": "which指代building strong relationships这件事。非限定性定语从句提供额外信息，去掉后句子仍然完整。", "practice": "仿写：I have 5 years of PM experience, ______ I believe will benefit this role. (答案: which)"}], "coreSentences": [{"original": "Why do you think this is the right job for you?", "function": "面试提问(为何适合)", "alternative": "What makes you the right person for this role? / Why should we hire you?"}, {"original": "I possess the experience and qualifications you are looking for.", "function": "展示匹配度", "alternative": "My background aligns well with what you're seeking. / I have exactly the skills this role requires."}, {"original": "I'm a great team player that can keep the team together.", "function": "强调团队协作", "alternative": "I'm collaborative and help unify the team. / I thrive in team environments."}, {"original": "On top of that, I'm passionate and ambitious about this industry.", "function": "叠加优势", "alternative": "Additionally, I have genuine enthusiasm for this field. / Moreover, I'm deeply committed to this industry."}, {"original": "I consider myself the perfect fit for this position.", "function": "自信总结", "alternative": "I believe I'm ideally suited for this role. / This position is exactly what I'm looking for."}], "exercises": {"vocabChoice": [{"question": "\"team player\" 是什么意思？", "options": ["球队成员", "有团队精神的人", "团队领导", "运动队"], "answer": 1}, {"question": "\"excel in\" 表示？", "options": ["不及格", "在...方面出色/擅长", "排除", "使用Excel"], "answer": 1}, {"question": "\"perfect fit\" 的意思是？", "options": ["完美的衣服", "完美匹配/非常合适", "完全健康", "完美安装"], "answer": 1}], "fillBlank": [{"sentence": "I ______ in building strong customer relationships.", "answer": "excel", "hint": "擅长(与in搭配)"}, {"sentence": "I'm a great ______ player who can keep the team together.", "answer": "team", "hint": "团队合作者"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方职场非常看重'team player'这个概念。它不等于'不发表意见的老好人'，而是既能为团队贡献力量，又能主动解决冲突的人。", "interviewTip": "回答'为什么你适合这个岗位'时，用3点法：技能匹配(qualifications)、软实力(team player/relationship building)、态度(passion/100%)。结尾用'perfect fit'自信但不傲慢地总结。", "difficulty": "🔵中级"}, {"id": 32, "file": "32-离职原因", "title": "离职原因", "titleRaw": "32、离职动机", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Separately, I feel you're doing a good job in your current company. May I ask why you decide to leave.", "Yes, it's true I'm doing pretty well in previous position, and my previous company is also top-notch in the industry. But like I mentioned, I've been there for 4 years and reached the ceiling in career advancement. So personally I want to step out and explore more possibilities."], "dialogueZH": ["另外，我觉得你在现在的公司表现得很好。我可以问一下你为什么决定离开吗？", "是的，我在之前的岗位确实表现不错，而且我之前的公司在行业里也属于顶尖水平。但正如我提到的，我在那里已经工作了四年，职业发展也到了天花板。所以我个人想走出去，探索更多的可能性。"], "vocabulary": [{"en": "separately", "phonetic": "/ˈsep.ər.ət.li/", "pos": "adv.", "zh": "另外；顺便提一下(用于切换话题)", "source": "Separately, I feel..."}, {"en": "top-notch", "phonetic": "/tɑːp nɑːtʃ/", "pos": "adj.", "zh": "顶尖的；一流的", "source": "my previous company is also top-notch"}, {"en": "reach the ceiling", "phonetic": "/riːtʃ ðə ˈsiː.lɪŋ/", "pos": "idiom", "zh": "触及天花板；到达瓶颈", "source": "reached the ceiling in career advancement"}, {"en": "career advancement", "phonetic": "/kəˈrɪr ədˈvæns.mənt/", "pos": "n. phr.", "zh": "职业发展；晋升", "source": "ceiling in career advancement"}, {"en": "step out", "phonetic": "/step aʊt/", "pos": "v. phr.", "zh": "走出去；踏出(舒适区)", "source": "step out and explore more"}, {"en": "explore possibilities", "phonetic": "/ɪkˈsplɔːr ˌpɑː.səˈbɪl.ə.tiz/", "pos": "v. phr.", "zh": "探索更多可能性", "source": "explore more possibilities"}, {"en": "decide to leave", "phonetic": "/dɪˈsaɪd tə liːv/", "pos": "v. phr.", "zh": "决定离开", "source": "why you decide to leave"}, {"en": "personally", "phonetic": "/ˈpɜːr.sən.əl.i/", "pos": "adv.", "zh": "就个人而言", "source": "So personally I want to step out"}], "grammar": [{"title": "It's true (that) + 从句 (让步)", "structure": "It's true (that) + 让步从句, but + 主句", "example": "It's true I'm doing pretty well in previous position, and my previous company is also top-notch. But like I mentioned, I've been there for 4 years and reached the ceiling.", "explanation": "It's true + but结构用于先让步后转折。面试中常用于'为什么离开好公司'：先肯定前公司，再说合理原因。", "practice": "仿写：______ ______ I enjoyed my previous role, ______ I feel it's time for a new challenge. (答案: It's true, but)"}], "coreSentences": [{"original": "May I ask why you decide to leave?", "function": "面试提问(离职原因)", "alternative": "What prompted your decision to move on? / Why are you looking to leave your current role?"}, {"original": "It's true I'm doing pretty well in my previous position.", "function": "先扬后抑(肯定现状)", "alternative": "I've had a great run at my current company. / I've learned a lot in my current role."}, {"original": "My previous company is also top-notch in the industry.", "function": "肯定前公司(避免负面)", "alternative": "My current employer is an excellent organization. / I have great respect for my company."}, {"original": "I've reached the ceiling in career advancement.", "function": "说明客观原因", "alternative": "I've hit a plateau in terms of growth. / There's limited room for upward mobility."}, {"original": "I want to step out and explore more possibilities.", "function": "表达积极动机", "alternative": "I'm ready to take on broader challenges. / I'm looking for a new platform to grow."}], "exercises": {"vocabChoice": [{"question": "\"top-notch\" 的意思是？", "options": ["顶部缺口", "顶尖的/一流的", "高处的", "顶层的"], "answer": 1}, {"question": "\"reach the ceiling\" 表示？", "options": ["碰到天花板", "到达瓶颈/触及上限", "达到顶峰", "登上屋顶"], "answer": 1}, {"question": "\"step out\" 在这里的意思是？", "options": ["出去走走", "走出去/踏出舒适区", "辞职", "退出"], "answer": 1}], "fillBlank": [{"sentence": "I've ______ the ceiling in career advancement.", "answer": "reached", "hint": "到达(瓶颈)"}, {"sentence": "I want to ______ out and explore more possibilities.", "answer": "step", "hint": "踏出(舒适区)"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方面试中，不要说前公司的坏话。最好的离职原因是'成长受限(reached the ceiling)'和'寻求新挑战(explore possibilities)'，而不是'老板不好''同事难搞'。", "interviewTip": "离职原因要体现积极动机(pull factor而非push factor)。说你被新机会吸引(pulled toward)，而不是被旧环境赶走(pushed out)。避免抱怨，展示你对成长的渴求。", "difficulty": "🔵中级"}, {"id": 33, "file": "33-职业规划", "title": "职业规划", "titleRaw": "33、职业规划", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["So what is your career plan in the next 5 years?", "As for long-term development, in the first few years, I'm hoping to become a strong contributor to business growth of the company, while honing my skills by learning on the job. Looking forwards to the next 5 years, I look at really becoming a recognized expert in managing small and large projects."], "dialogueZH": ["那么，你未来五年的职业规划是什么？", "从长期发展来看，在最初的几年里，我希望能够成为公司业务增长的重要贡献者，同时通过在岗学习不断打磨自己的技能。展望未来五年，我希望真正成长为在大小项目管理方面都受到认可的专家。"], "vocabulary": [{"en": "long-term", "phonetic": "/lɔːŋ tɜːrm/", "pos": "adj.", "zh": "长期的", "source": "long-term development"}, {"en": "contributor", "phonetic": "/kənˈtrɪb.jə.tər/", "pos": "n.", "zh": "贡献者", "source": "a strong contributor"}, {"en": "business growth", "phonetic": "/ˈbɪz.nɪs ɡroʊθ/", "pos": "n. phr.", "zh": "业务增长", "source": "business growth of the company"}, {"en": "hone", "phonetic": "/hoʊn/", "pos": "v.", "zh": "磨练；打磨(技能)", "source": "honing my skills"}, {"en": "learning on the job", "phonetic": "/ˈlɜːr.nɪŋ ɑːn ðə dʒɑːb/", "pos": "n. phr.", "zh": "在岗学习", "source": "by learning on the job"}, {"en": "look forward to", "phonetic": "/lʊk ˈfɔːr.wərd tə/", "pos": "v. phr.", "zh": "展望；期待", "source": "Looking forwards to the next 5 years"}, {"en": "recognized", "phonetic": "/ˈrek.əɡ.naɪzd/", "pos": "adj.", "zh": "被认可的", "source": "a recognized expert"}, {"en": "career plan", "phonetic": "/kəˈrɪr plæn/", "pos": "n.", "zh": "职业规划", "source": "your career plan in the next 5 years"}, {"en": "strong contributor", "phonetic": "/strɔːŋ kənˈtrɪb.jə.tər/", "pos": "n. phr.", "zh": "重要贡献者", "source": "a strong contributor to business growth"}], "grammar": [{"title": "As for + 名词, 主句 (用于引出话题)", "structure": "As for + n., 主句", "example": "As for long-term development, in the first few years, I'm hoping to become a strong contributor.", "explanation": "As for = 至于.../就...而言。用于从泛泛回答过渡到具体细节，是面试中非常好用的组织语。", "practice": "仿写：______ ______ my career goals, I plan to become a team lead in 3 years. (答案: As for)"}, {"title": "Looking forward to + 时间段, 主句", "structure": "Looking forward to + 时间段, 主句", "example": "Looking forwards to the next 5 years, I look at really becoming a recognized expert.", "explanation": "Looking forward + 时间段 = 展望未来...。注意与look forward to doing(期待做某事)的区别。", "practice": "仿写：______ ______ to the next 3 years, I hope to take on more leadership roles. (答案: Looking forward)"}], "coreSentences": [{"original": "What is your career plan in the next 5 years?", "function": "面试提问(职业规划)", "alternative": "Where do you see yourself in five years? / What are your long-term career goals?"}, {"original": "In the first few years, I'm hoping to become a strong contributor to business growth.", "function": "描述近期目标(贡献价值)", "alternative": "Initially, I aim to make a meaningful impact on the company's growth. / My short-term goal is to deliver real value."}, {"original": "I'm honing my skills by learning on the job.", "function": "表达学习态度", "alternative": "I plan to sharpen my skills through hands-on experience. / I'll continue learning and improving in the role."}, {"original": "I look at really becoming a recognized expert in managing small and large projects.", "function": "描述长远目标", "alternative": "In the long run, I aspire to be a go-to expert in project management. / My long-term vision is to become a leading professional in this field."}], "exercises": {"vocabChoice": [{"question": "\"hone\" 的意思是？", "options": ["放弃", "磨练/打磨", "选择", "忽略"], "answer": 1}, {"question": "\"contributor\" 指的是？", "options": ["贡献者", "反对者", "经理", "旁观者"], "answer": 0}, {"question": "\"learning on the job\" 表示？", "options": ["离开工作学习", "在工作中学/在岗学习", "职业培训", "返校学习"], "answer": 1}], "fillBlank": [{"sentence": "I hope to become a strong ______ to the company's growth.", "answer": "contributor", "hint": "贡献者"}, {"sentence": "I'm ______ my skills through hands-on experience.", "answer": "honing", "hint": "磨练"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "职业规划问题的重点不是让你预言未来，而是看你的职业方向是否与公司能给的匹配。建议分短期(1-2年)和长期(3-5年)两个阶段回答。短期要强调贡献(而非索取)，长期要展示成长野心。", "interviewTip": "回答职业规划，短期讲'我能为公司带来什么价值'，长期讲'我希望成为什么样的专家'。不要只谈'我想升职加薪'，要谈'我想在什么领域深耕'。honing skills / learning on the job这些说法体现成长型思维。", "difficulty": "🔵中级"}, {"id": 34, "file": "34-流程管控", "title": "流程管控", "titleRaw": "34、逆商考察", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["But what if you underperform in your new role?", "Yes, I did have such concerns before. If you want to pursue better career growth in the long run, sometimes you need to take on the risks, but if you stand still or stick to staying within comfort zone, then you will never have the chance to grow, which is a matter of trade-off. I really thrive on challenges, so I choose to jump out for the sake of my personal growth.", "Yeah, you make a good point."], "dialogueZH": ["但如果你在新岗位表现不佳怎么办？", "是的，我之前确实有过这样的担忧。如果你想在长期内获得更好的职业发展，有时候就需要承担一定的风险；但如果你停滞不前，或者一直待在舒适区，那你永远不会有成长的机会，这本质上是一种取舍。我非常享受挑战，所以我选择跳出来，为了自己的成长迈出这一步。", "嗯，你说得很有道理。"], "vocabulary": [{"en": "underperform", "phonetic": "/ˌʌn.dər.pərˈfɔːrm/", "pos": "v.", "zh": "表现不佳；未达到预期", "source": "what if you underperform"}, {"en": "in the long run", "phonetic": "/ɪn ðə lɔːŋ rʌn/", "pos": "adv. phr.", "zh": "从长远来看", "source": "in the long run"}, {"en": "take on the risks", "phonetic": "/teɪk ɑːn ðə rɪsks/", "pos": "v. phr.", "zh": "承担风险", "source": "take on the risks"}, {"en": "stand still", "phonetic": "/stænd stɪl/", "pos": "v. phr.", "zh": "停滞不前", "source": "if you stand still"}, {"en": "comfort zone", "phonetic": "/ˈkʌm.fərt zoʊn/", "pos": "n.", "zh": "舒适区", "source": "staying within comfort zone"}, {"en": "trade-off", "phonetic": "/ˈtreɪd.ɔːf/", "pos": "n.", "zh": "取舍；权衡", "source": "a matter of trade-off"}, {"en": "thrive on", "phonetic": "/θraɪv ɑːn/", "pos": "v. phr.", "zh": "以...为乐；在...中茁壮成长", "source": "I really thrive on challenges"}, {"en": "jump out", "phonetic": "/dʒʌmp aʊt/", "pos": "v. phr.", "zh": "跳出来(指离开舒适区)", "source": "I choose to jump out"}, {"en": "make a good point", "phonetic": "/meɪk ə ɡʊd pɔɪnt/", "pos": "v. phr.", "zh": "说得好；有道理", "source": "you make a good point"}], "grammar": [{"title": "What if + 主语 + 动词? (假设提问)", "structure": "What if + 主语 + 现在时?", "example": "What if you underperform in your new role?", "explanation": "What if = '如果...怎么办？'，用于提出假设性反问，是面试中压力测试的典型句式。", "practice": "仿写：______ ______ the project goes over budget? (答案: What if)"}, {"title": "If...then... 条件论证", "structure": "If 主语..., then 主语 will never...", "example": "If you stand still or stick to staying within comfort zone, then you will never have the chance to grow.", "explanation": "If...then...用于逻辑论证。在回答假设性问题时，用此结构展示你思考问题的深度和逻辑性。", "practice": "仿写：If you never take risks, ______ you will never discover new opportunities. (答案: then)"}], "coreSentences": [{"original": "What if you underperform in your new role?", "function": "压力面试提问", "alternative": "How would you handle it if things didn't work out? / What if this isn't the right fit?"}, {"original": "Sometimes you need to take on the risks.", "function": "承认风险存在", "alternative": "Growth involves a certain amount of risk. / You can't grow without taking some chances."}, {"original": "If you stand still, you will never have the chance to grow.", "function": "论证进取必要性", "alternative": "Staying put means missing out on growth. / Without change, there's no progress."}, {"original": "It's a matter of trade-off.", "function": "总结为取舍", "alternative": "It comes down to a trade-off. / It's about balancing risk and reward."}, {"original": "I really thrive on challenges.", "function": "表达积极态度", "alternative": "I'm energized by challenges. / Challenges bring out the best in me."}], "exercises": {"vocabChoice": [{"question": "\"underperform\" 的意思是？", "options": ["表现优异", "表现不佳/未达标", "在下面表演", "超额完成"], "answer": 1}, {"question": "\"comfort zone\" 表示？", "options": ["舒适区域", "舒适区/心理安全区", "空调房", "放松的地方"], "answer": 1}, {"question": "\"trade-off\" 的意思是？", "options": ["交易", "取舍/权衡", "贸易", "关闭"], "answer": 1}], "fillBlank": [{"sentence": "Don't just stay within your comfort ______.", "answer": "zone", "hint": "区域(固定搭配)"}, {"sentence": "I really ______ on challenges.", "answer": "thrive", "hint": "以...为乐/茁壮成长"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "逆商(Adversity Quotient)在西方职场越来越被重视。面试官通过'what if you fail'类问题考察你是否具备成长型思维(growth mindset)。承认风险但显示勇气和理性分析能力是最佳策略。", "interviewTip": "面对'what if'类假设问题，不要否认(我不会失败的)，也不要过度担忧(那怎么办啊...)。展示你理性分析过风险(承认trade-off)，有应对计划(how to mitigate)，并且保持积极(thrive on challenges)。", "difficulty": "🔴进阶"}, {"id": 35, "file": "35-风险管理处理", "title": "风险管理-处理", "titleRaw": "35、经历空窗期", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["I see. Just out of curiosity, I saw a little gap here in your résumé… 5 months… what were you doing then?", "Well, when I submitted resignation in my previous company, my supervisor actually proposed to give me a pay rise and promotion to make me stay. But to be honest, it wasn’t an area I wanted to stay for long. So after deliberation, I took the plunge and quitted, and I spent that 5-month window period honing my skills for this application."], "dialogueZH": ["我明白了。只是出于好奇，我看到你简历里这里有一段空档……五个月……那段时间你在做什么？", "嗯，当我在上一家公司递交辞呈时，我的主管其实提出给我加薪和升职，希望我留下。但说实话，那并不是我想长期发展的方向。所以经过慎重考虑，我还是决定勇敢迈出这一步辞职了，并利用这五个月的空档期提升自己的能力，为这次申请做准备。"], "vocabulary": [{"en": "out of curiosity", "phonetic": "/aʊt əv ˌkjʊr.iˈɑː.sə.ti/", "pos": "phr.", "zh": "出于好奇(用于礼貌提问)", "source": "Just out of curiosity"}, {"en": "gap", "phonetic": "/ɡæp/", "pos": "n.", "zh": "空档；间隙(简历中的空白期)", "source": "a little gap in your resume"}, {"en": "resume", "phonetic": "/ˈrez.ə.meɪ/", "pos": "n.", "zh": "简历", "source": "I saw a little gap in your resume"}, {"en": "submit resignation", "phonetic": "/səbˈmɪt ˌrez.ɪɡˈneɪ.ʃən/", "pos": "v. phr.", "zh": "提交辞呈", "source": "submitted resignation"}, {"en": "pay rise", "phonetic": "/peɪ raɪz/", "pos": "n.", "zh": "加薪", "source": "proposed to give me a pay rise"}, {"en": "deliberation", "phonetic": "/dɪˌlɪb.əˈreɪ.ʃən/", "pos": "n.", "zh": "慎重考虑；商议", "source": "after deliberation"}, {"en": "take the plunge", "phonetic": "/teɪk ðə plʌndʒ/", "pos": "idiom", "zh": "下定决心；勇敢迈出一步", "source": "I took the plunge and quitted"}, {"en": "window period", "phonetic": "/ˈwɪn.doʊ ˈpɪr.i.əd/", "pos": "n.", "zh": "窗口期；空档期", "source": "that 5-month window period"}, {"en": "hone skills", "phonetic": "/hoʊn skɪlz/", "pos": "v. phr.", "zh": "提升/打磨技能", "source": "honing my skills for this application"}], "grammar": [{"title": "When引导的时间状语从句 + 插入语", "structure": "When + 从句, 插入语, 主句", "example": "When I submitted resignation, my supervisor actually proposed to give me a pay rise.", "explanation": "actually在此是插入语，表示'其实/居然'，增强对比效果。可用于引导出人意料的情节。", "practice": "仿写：When I announced my departure, my manager ______ (actually) asked me to reconsider. (答案: actually)"}], "coreSentences": [{"original": "Just out of curiosity, I saw a gap in your resume.", "function": "礼貌询问空档期", "alternative": "I noticed a gap in your work history. / Could you tell me about this break in your career?"}, {"original": "My supervisor proposed to give me a pay rise and promotion to make me stay.", "function": "说明被挽留(间接证明能力)", "alternative": "My manager tried to retain me with a promotion. / They offered a raise to keep me."}, {"original": "To be honest, it wasn't an area I wanted to stay for long.", "function": "说明离开真正原因", "alternative": "Truthfully, I didn't see myself growing in that direction. / Frankly, my interests lay elsewhere."}, {"original": "After deliberation, I took the plunge and quitted.", "function": "描述决策过程", "alternative": "After careful consideration, I made the leap. / I weighed the pros and cons and decided to go for it."}, {"original": "I spent that window period honing my skills.", "function": "说明空档期用途(积极利用)", "alternative": "I used that time to upskill and prepare for this opportunity. / I invested the break in professional development."}], "exercises": {"vocabChoice": [{"question": "\"take the plunge\" 的意思是？", "options": ["跳水", "下定决心/勇敢迈出一步", "陷入困境", "跳进去"], "answer": 1}, {"question": "\"gap\" 在简历语境中指的是？", "options": ["差距", "空档/空白期", "代沟", "缝隙"], "answer": 1}, {"question": "\"deliberation\" 表示？", "options": ["忽略", "快速决定", "慎重考虑/商议", "删除"], "answer": 2}], "fillBlank": [{"sentence": "After careful ______, I took the plunge and resigned.", "answer": "deliberation", "hint": "慎重考虑"}, {"sentence": "I used that window ______ to hone my skills.", "answer": "period", "hint": "时期/时段"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "简历空档期在西方职场也会被问，但不像中国那样严重。关键在于你如何解释——'我在那段时间提升了技能'比'我在休息'要好得多。take the plunge是地道习语，表达'鼓起勇气跳槽'。", "interviewTip": "解释空档期三要素：1)离开是经过深思熟虑的(deliberation) 2)不是因为被开除(我被挽留了) 3)空档期被积极利用(honing skills)。展示你的决策是主动的、积极的。", "difficulty": "🔴进阶"}, {"id": 36, "file": "36-缺点与不足", "title": "缺点与不足", "titleRaw": "36、缺点描述", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["So, moving on now… What do you think your greatest weakness is?", "Like I said, I tend to wear my heart on my sleeves when I am at odds with others in work, and there are good and bad sides to this.", "In what ways? Can you expand on that a little?", "Well, being straightforward can reduce costs of communication and contribute to better collaboration. But honestly, this trait might be seen as a drawback in some scenarios. For example, once in a meeting of multiple participants, I challenged one of my teammates quite bluntly, which caused discomfort to him, and he was uncooperative with me afterwards. From this case, I realized the necessity of adopting flexible styles in different situations. After a period of adjustment, now I have addressed this properly and become an adaptable communicator."], "dialogueZH": ["那么，我们继续……你认为自己最大的弱点是什么？", "就像我之前说的，当我在工作中与别人意见不一致时，我往往比较情绪外露。这种特质既有好处，也有不利的一面。", "具体是指哪些方面？你能再展开说一下吗？", "坦率直接可以降低沟通成本，并促进更好的协作。但说实话，这种特质在某些场景下也可能被视为缺点。比如，有一次在一个多人会议上，我比较直接地质疑了一位同事，这让他感到不舒服，之后他对我也不太配合。通过这件事，我意识到在不同情境下采用灵活沟通方式的重要性。经过一段时间的调整，现在我已经能够很好地处理这类情况，并成为一名更具适应性的沟通者。"], "vocabulary": [{"en": "weakness", "phonetic": "/ˈwiːk.nəs/", "pos": "n.", "zh": "弱点；缺点", "source": "your greatest weakness"}, {"en": "wear my heart on my sleeves", "phonetic": "/wer maɪ hɑːrt ɑːn maɪ sliːvz/", "pos": "idiom", "zh": "情绪外露；喜怒形于色", "source": "wear my heart on my sleeves"}, {"en": "at odds with", "phonetic": "/æt ɑːdz wɪð/", "pos": "idiom", "zh": "与...意见不合", "source": "at odds with others in work"}, {"en": "straightforward", "phonetic": "/ˌstreɪtˈfɔːr.wərd/", "pos": "adj.", "zh": "坦率的；直截了当的", "source": "being straightforward"}, {"en": "reduce costs of communication", "phonetic": "/rɪˈduːs kɔːsts əv kəˌmjuː.nɪˈkeɪ.ʃən/", "pos": "v. phr.", "zh": "降低沟通成本", "source": "reduce costs of communication"}, {"en": "drawback", "phonetic": "/ˈdrɔː.bæk/", "pos": "n.", "zh": "缺点；弊端", "source": "seen as a drawback"}, {"en": "challenge", "phonetic": "/ˈtʃæl.ɪndʒ/", "pos": "v.", "zh": "质疑；挑战", "source": "challenged one of my teammates"}, {"en": "bluntly", "phonetic": "/ˈblʌnt.li/", "pos": "adv.", "zh": "直率地；生硬地", "source": "challenged...quite bluntly"}, {"en": "discomfort", "phonetic": "/dɪˈskʌm.fərt/", "pos": "n.", "zh": "不适；不舒服", "source": "caused discomfort"}, {"en": "uncooperative", "phonetic": "/ˌʌn.koʊˈɑː.pər.ə.tɪv/", "pos": "adj.", "zh": "不合作的", "source": "uncooperative with me"}, {"en": "adopt flexible styles", "phonetic": "/əˈdɑːpt ˈflek.sə.bəl staɪlz/", "pos": "v. phr.", "zh": "采用灵活的方式", "source": "adopting flexible styles"}, {"en": "adaptable", "phonetic": "/əˈdæp.tə.bəl/", "pos": "adj.", "zh": "适应力强的；能变通的", "source": "become an adaptable communicator"}], "grammar": [{"title": "There are good and bad sides to this (两面性表达)", "structure": "There are good and bad sides to + 名词/代词", "example": "There are good and bad sides to this.", "explanation": "用于客观评价一个特质的双面性。面试中描述缺点时非常地道的表达——先承认特质本身，再说它有正反面。", "practice": "仿写：There ______ good and bad ______ to being a perfectionist. (答案: are, sides)"}, {"title": "过去分词短语作状语 (After + being + 过去分词)", "structure": "After + being + 过去分词, 主句", "example": "After a period of adjustment, now I have addressed this properly.", "explanation": "After引导的时间状语。原文省略了being，完整可以是 After (being) adjusted for a period...", "practice": "仿写：After ______ of practice, I improved my communication style. (答案: a period)"}], "coreSentences": [{"original": "What do you think your greatest weakness is?", "function": "面试经典提问(缺点)", "alternative": "What area do you think you could improve on? / What would your manager say is your development area?"}, {"original": "I tend to wear my heart on my sleeves when I am at odds with others.", "function": "诚实地描述缺点", "alternative": "I can be too transparent with my emotions during disagreements. / I sometimes express my frustration too openly."}, {"original": "There are good and bad sides to this.", "function": "客观分析特质两面性", "alternative": "This trait has its pros and cons. / It is a double-edged sword."}, {"original": "Being straightforward can reduce costs of communication.", "function": "说明特质的积极面", "alternative": "Directness can streamline discussions. / Being candid helps avoid misunderstandings."}, {"original": "From this case, I realized the necessity of adopting flexible styles.", "function": "总结学到的教训", "alternative": "I learned that different situations call for different approaches. / This taught me the importance of adaptability."}, {"original": "After a period of adjustment, I have addressed this properly.", "function": "强调已经改进", "alternative": "I have since worked on this and made significant improvements. / With conscious effort, I managed to turn this around."}], "exercises": {"vocabChoice": [{"question": "\"wear my heart on my sleeves\" 的意思是？", "options": ["穿心形袖子的衣服", "情绪外露/喜怒形于色", "把心藏在袖子里", "展示心脏"], "answer": 1}, {"question": "\"drawback\" 的意思是？", "options": ["优点", "画画", "缺点/弊端", "拉回来"], "answer": 2}, {"question": "\"adaptable\" 表示？", "options": ["固执的", "适应力强的/能变通的", "可改编的", "可采用的"], "answer": 1}], "fillBlank": [{"sentence": "I tend to wear my ______ on my sleeves when I disagree with others.", "answer": "heart", "hint": "情绪外露(习语)"}, {"sentence": "I realized the necessity of adopting ______ styles in different situations.", "answer": "flexible", "hint": "灵活的"}], "grammarChoice": [], "sentenceReorder": [{"scrambled": ["good and bad", "There are", "to this", "sides"], "answer": "There are good and bad sides to this."}]}, "cultureNote": "西方面试中描述缺点时，不要选致命弱点(如不诚实/不守时)，也不要假装完美。最好的策略是选一个真实但已改进的缺点，展示成长过程。本场景就是标准模板：坦率->有时伤人->学会灵活沟通->已改善。", "interviewTip": "缺点的回答公式：1)缺点是什么 2)它有什么积极面(optional) 3)曾在什么场景带来问题 4)你学到了什么 5)你现在如何管理它。关键是展示self-awareness和growth。", "difficulty": "🔴进阶"}, {"id": 37, "file": "37-优点与提问", "title": "优点与提问", "titleRaw": "37、优点描述", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Could you please describe your personal characteristics? Two to three keywords will do.", "I would describe myself as conscientious, highly motivated, and perseverant. I adapt well to challenging circumstances and can consistently deliver results even under tight deadlines. I also tend to take initiative in my projects, and when necessary, I’m willing to take on tasks beyond my formal responsibilities to ensure the work moves forward smoothly."], "dialogueZH": ["你能描述一下你的个人特质吗？两到三个关键词即可。", "我会形容自己是一个认真负责、积极进取、坚持不懈的人。我能够很好地适应各种挑战，并在紧迫的截止时间下依然稳定交付成果。同时，我在项目中通常会主动承担责任，并在需要时愿意接手超出本职范围的任务，以确保工作顺利推进。"], "vocabulary": [{"en": "characteristics", "phonetic": "/ˌker.ək.təˈrɪs.tɪks/", "pos": "n.", "zh": "特征；特质", "source": "describe your personal characteristics"}, {"en": "conscientious", "phonetic": "/ˌkɑːn.ʃiˈen.ʃəs/", "pos": "adj.", "zh": "认真负责的；尽责的", "source": "describe myself as conscientious"}, {"en": "highly motivated", "phonetic": "/ˈhaɪ.li ˈmoʊ.tɪ.veɪ.tɪd/", "pos": "adj. phr.", "zh": "积极进取的；高度自驱的", "source": "highly motivated"}, {"en": "perseverant", "phonetic": "/ˌpɜːr.sɪˈvɪr.ənt/", "pos": "adj.", "zh": "坚持不懈的", "source": "perseverant"}, {"en": "adapt", "phonetic": "/əˈdæpt/", "pos": "v.", "zh": "适应", "source": "adapt well to challenging circumstances"}, {"en": "tight deadlines", "phonetic": "/taɪt ˈded.laɪnz/", "pos": "n. phr.", "zh": "紧迫的截止时间", "source": "under tight deadlines"}, {"en": "take initiative", "phonetic": "/teɪk ɪˈnɪʃ.ə.tɪv/", "pos": "v. phr.", "zh": "主动承担；率先行动", "source": "take initiative in my projects"}, {"en": "beyond my formal responsibilities", "phonetic": "/bɪˈjɑːnd maɪ ˈfɔːr.məl rɪˌspɑːn.səˈbɪl.ə.tiz/", "pos": "phr.", "zh": "超出我正式职责范围", "source": "beyond my formal responsibilities"}], "grammar": [{"title": "I would describe myself as... (自我描述)", "structure": "I would describe myself as + adj. + adj. + and + adj.", "example": "I would describe myself as conscientious, highly motivated, and perseverant.", "explanation": "Would describe myself as是面试中描述性格的经典句式。用三个形容词并列，既有节奏感又全面。比I am...更柔和礼貌。", "practice": "仿写：I ______ describe myself ______ detail-oriented, proactive, and collaborative. (答案: would, as)"}], "coreSentences": [{"original": "Could you describe your personal characteristics? Two to three keywords will do.", "function": "面试提问(性格特质)", "alternative": "How would you describe yourself in three words? / What are your key personality traits?"}, {"original": "I would describe myself as conscientious, highly motivated, and perseverant.", "function": "用关键词自述", "alternative": "I'm someone who is diligent, driven, and persistent. / Three words I'd use: responsible, self-driven, and tenacious."}, {"original": "I adapt well to challenging circumstances.", "function": "描述适应力", "alternative": "I'm flexible and can thrive in tough environments. / I adjust quickly to difficult situations."}, {"original": "I consistently deliver results even under tight deadlines.", "function": "展示抗压能力", "alternative": "I produce quality work even when time is short. / My performance stays high under pressure."}, {"original": "I'm willing to take on tasks beyond my formal responsibilities.", "function": "展示主动性", "alternative": "I go above and beyond my job description. / I step up to help wherever needed."}], "exercises": {"vocabChoice": [{"question": "\"conscientious\" 的意思是？", "options": ["粗心的", "认真的/尽责的", "有意识的", "快速的"], "answer": 1}, {"question": "\"take initiative\" 表示？", "options": ["等待指令", "主动承担/率先行动", "制定计划", "开始行动"], "answer": 1}, {"question": "\"perseverant\" 指的是？", "options": ["放弃的", "动摇的", "坚持不懈的", "保守的"], "answer": 2}], "fillBlank": [{"sentence": "I would describe myself as ______ and highly motivated.", "answer": "conscientious", "hint": "认真负责的"}, {"sentence": "I'm willing to take on tasks ______ my formal responsibilities.", "answer": "beyond", "hint": "超出"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方面试中描述自己优点时，选2-3个关键词+每个词有1-2句例子支撑，是最佳结构。关键词不要太多(显得自恋)，也不要太少(显得无特点)。conscientious是高频夸人词。", "interviewTip": "选3个关键词，每个都要能用1-2句话举例。优先选与岗位相关的特质。比如PM岗位：organized + proactive + collaborative。最后加一句beyond formal responsibilities体现你的ownership精神。", "difficulty": "🟢入门"}, {"id": 38, "file": "38-面试提问", "title": "面试提问（反提问）", "titleRaw": "38、反问面试官", "roles": {"A": "Steve (候选人)", "B": "John (面试官)"}, "dialogueEN": ["Great. We’re just about finished. Do you have any questions for me?", "Yes, can you please specify the functions this role deals with regularly? And what is the typical career path for someone in this role?", "Sure. This role needs to engage with various functions, mainly with the product and tech team, as there is a lot of communication required for the whole life cycle of a project. Career-path-wise, you will lead a team if your performance is quite good, as our business is still at the stage of hyper-growth and we need to hire more people. Does that answer your question?"], "dialogueZH": ["很好，我们差不多要结束了。你有什么想问我的吗？", "有的。您能具体说明一下这个岗位平时主要对接哪些职能部门吗？另外，这个岗位的典型职业发展路径是什么？", "当然可以。这个岗位需要与多个部门合作，主要是产品团队和技术团队，因为整个项目生命周期中需要大量沟通。至于职业发展，如果你的表现足够好，你会带领一个团队。我们目前处于高速增长阶段，也需要招聘更多人。这样回答能解决你的疑问吗？"], "vocabulary": [{"en": "just about finished", "phonetic": "/dʒʌst əˈbaʊt ˈfɪn.ɪʃt/", "pos": "phr.", "zh": "差不多要结束了", "source": "We're just about finished."}, {"en": "specify", "phonetic": "/ˈspes.ɪ.faɪ/", "pos": "v.", "zh": "具体说明；明确", "source": "can you please specify"}, {"en": "deal with", "phonetic": "/diːl wɪð/", "pos": "v. phr.", "zh": "与...打交道；处理", "source": "functions this role deals with"}, {"en": "career path", "phonetic": "/kəˈrɪr pæθ/", "pos": "n.", "zh": "职业发展路径", "source": "typical career path"}, {"en": "life cycle", "phonetic": "/laɪf ˈsaɪ.kəl/", "pos": "n.", "zh": "生命周期", "source": "the whole life cycle of a project"}, {"en": "hyper-growth", "phonetic": "/ˈhaɪ.pər ɡroʊθ/", "pos": "n.", "zh": "高速增长", "source": "at the stage of hyper-growth"}, {"en": "engage with", "phonetic": "/ɪnˈɡeɪdʒ wɪð/", "pos": "v. phr.", "zh": "与...对接/沟通", "source": "engage with various functions"}, {"en": "career-path-wise", "phonetic": "/kəˈrɪr pæθ waɪz/", "pos": "adv.", "zh": "在职业发展方面", "source": "Career-path-wise, you will..."}, {"en": "lead a team", "phonetic": "/liːd ə tiːm/", "pos": "v. phr.", "zh": "带领团队", "source": "you will lead a team"}], "grammar": [{"title": "Does that answer your question? (确认式反问)", "structure": "Does that answer your question?", "example": "Does that answer your question?", "explanation": "回答完后用此句确认对方是否满意。非常礼貌且高效，让对方有机会追问。也可用'Does that make sense?'", "practice": "仿写：I hope this clarifies. ______ that ______ your question? (答案: Does, answer)"}], "coreSentences": [{"original": "We're just about finished. Do you have any questions for me?", "function": "面试进入尾声", "alternative": "That wraps up my questions. Is there anything you'd like to ask me?"}, {"original": "Can you please specify the functions this role deals with regularly?", "function": "反问岗位日常职责", "alternative": "What does the day-to-day look like for this role? / Which teams would I work most closely with?"}, {"original": "What is the typical career path for someone in this role?", "function": "问职业发展", "alternative": "How does career progression work here? / What growth opportunities does this position offer?"}, {"original": "Our business is still at the stage of hyper-growth.", "function": "描述公司发展阶段", "alternative": "We're in rapid expansion mode. / The company is scaling up quickly."}, {"original": "Does that answer your question?", "function": "确认对方满意", "alternative": "Is that helpful? / Let me know if you'd like me to elaborate."}], "exercises": {"vocabChoice": [{"question": "\"career path\" 的意思是？", "options": ["职业道路", "职业发展路径", "生涯规划", "工作方向"], "answer": 1}, {"question": "\"specify\" 表示？", "options": ["推测", "具体说明/明确", "简化", "忽略"], "answer": 1}, {"question": "\"hyper-growth\" 指的是？", "options": ["消极增长", "高速增长", "正常增长", "无增长"], "answer": 1}], "fillBlank": [{"sentence": "Can you ______ the functions this role deals with?", "answer": "specify", "hint": "具体说明"}, {"sentence": "What is the typical ______ path for this position?", "answer": "career", "hint": "职业发展"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方面试中，反提问环节是面试的一部分(非附加项)。问得好加分，不问可能扣分。问题应关注岗位、团队、成长空间，不要问薪资福利(除非面试官主动提)。", "interviewTip": "准备2-3个反提问。好问题：1)岗位日常职责 2)团队结构和协作方式 3)职业发展路径。bad问题：薪资、假期、是否加班。显示你是来做事的，不是来享受的。", "difficulty": "🔵中级"}, {"id": 39, "file": "39-面试收尾", "title": "面试收尾", "titleRaw": "39、面试收尾", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Yes, it does. It’s really encouraging to hear. And also one quick question, roughly when can I get the interview feedback?", "Honestly, it’s a rat race among candidates. We are short-listing all the candidates this week, and next week we will inform eligible candidates for the second-round interview.", "Great, thanks a lot! I am looking forward to your reply.", "No worries, you can ping me anytime on WeChat if you have any further questions."], "dialogueZH": ["是的，回答了。听到这些真的很鼓舞人心。 另外我还有个小问题，大概什么时候能收到面试反馈？", "说实话，候选人之间竞争非常激烈。我们会在本周完成所有候选人的初筛，下周会通知符合条件的人参加第二轮面试。", "太好了，非常感谢！我期待您的回复。", "不客气，如果你还有其他问题，随时可以在微信上联系我。"], "vocabulary": [{"en": "encouraging", "phonetic": "/ɪnˈkɜːr.ɪ.dʒɪŋ/", "pos": "adj.", "zh": "令人鼓舞的", "source": "really encouraging to hear"}, {"en": "rat race", "phonetic": "/ræt reɪs/", "pos": "n.", "zh": "激烈竞争(尤指职场)", "source": "it's a rat race among candidates"}, {"en": "short-list", "phonetic": "/ʃɔːrt lɪst/", "pos": "v.", "zh": "筛选；列入候选名单", "source": "short-listing all the candidates"}, {"en": "eligible", "phonetic": "/ˈel.ɪ.dʒə.bəl/", "pos": "adj.", "zh": "符合条件的；有资格的", "source": "inform eligible candidates"}, {"en": "ping", "phonetic": "/pɪŋ/", "pos": "v.", "zh": "(口语)发消息；联系", "source": "you can ping me anytime"}, {"en": "compensation", "phonetic": "/ˌkɑːm.penˈseɪ.ʃən/", "pos": "n.", "zh": "薪酬；报酬", "source": "expected compensation"}, {"en": "privilege", "phonetic": "/ˈprɪv.əl.ɪdʒ/", "pos": "n.", "zh": "荣幸；特权", "source": "It's a great privilege"}, {"en": "base salary", "phonetic": "/beɪs ˈsæl.ər.i/", "pos": "n.", "zh": "基本工资", "source": "base salary"}, {"en": "year-end bonuses", "phonetic": "/jɪr end ˈboʊ.nəs.ɪz/", "pos": "n.", "zh": "年终奖金", "source": "year-end bonuses"}, {"en": "subsidies", "phonetic": "/ˈsʌb.sə.diz/", "pos": "n.", "zh": "补贴；补助", "source": "housing subsidies"}, {"en": "within our budget", "phonetic": "/wɪˈðɪn aʊər ˈbʌdʒ.ɪt/", "pos": "phr.", "zh": "在我们的预算范围内", "source": "within our budget"}, {"en": "battle-tested", "phonetic": "/ˈbæt.əl ˌtes.tɪd/", "pos": "adj.", "zh": "久经考验的；身经百战的", "source": "a battle-tested veteran"}, {"en": "C-suite", "phonetic": "/siː swiːt/", "pos": "n.", "zh": "高管层(CEO/CTO/CFO等)", "source": "our C-suite"}, {"en": "org chart", "phonetic": "/ɔːrɡ tʃɑːrt/", "pos": "n.", "zh": "组织架构图", "source": "a bigger picture of our org chart"}], "grammar": [{"title": "It's a great privilege to... (表达荣幸)", "structure": "It's a great privilege to + 动词原形", "example": "It's a great privilege to have the opportunity to join your company.", "explanation": "非常正式礼貌的表达，用于接受offer或表达感谢。比'I'm happy to be here'正式得多。", "practice": "仿写：______ a great ______ to work with such a talented team. (答案: It's, privilege)"}], "coreSentences": [{"original": "Roughly when can I get the interview feedback?", "function": "询问面试反馈时间", "alternative": "What's the expected timeline for hearing back? / When should I expect to hear from you?"}, {"original": "It's a rat race among candidates.", "function": "形容竞争激烈", "alternative": "The competition is fierce. / We have many strong applicants."}, {"original": "You can ping me anytime on WeChat.", "function": "保持联系邀请", "alternative": "Feel free to reach out anytime. / Don't hesitate to message me."}, {"original": "It's a great privilege to have the opportunity to join your company.", "function": "表达荣幸(收到offer)", "alternative": "I'm honored by the opportunity. / It would be a privilege to be part of the team."}, {"original": "This figure is within our budget, but let me double confirm.", "function": "薪资谈判回应", "alternative": "That aligns with our range, but I need to verify internally. / Let me check with leadership and get back to you."}, {"original": "He is a battle-tested veteran with over a decade of experience.", "function": "介绍资深入职人员", "alternative": "He's an industry veteran with extensive experience. / He brings over 10 years of proven expertise."}], "exercises": {"vocabChoice": [{"question": "\"rat race\" 的意思是？", "options": ["老鼠赛跑", "激烈竞争(职场)", "比赛", "追逐游戏"], "answer": 1}, {"question": "\"C-suite\" 指的是？", "options": ["C级套房", "高管层(CEO/CTO等)", "员工食堂", "普通办公室"], "answer": 1}, {"question": "\"battle-tested\" 表示？", "options": ["还未经过考验", "久经考验的/身经百战的", "失败的", "新兵"], "answer": 1}], "fillBlank": [{"sentence": "It's a great ______ to have the opportunity to join your company.", "answer": "privilege", "hint": "荣幸"}, {"sentence": "You can ______ me anytime on WeChat if you have questions.", "answer": "ping", "hint": "发消息(口语)"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "面试收尾包含多个子场景：询问反馈时间、薪资谈判、入职介绍。西方薪资谈判中，先问薪酬结构(compensation structure)，再报价，是标准做法。入职介绍(new joiner introduction)通常会安排正式介绍给全团队。", "interviewTip": "薪资谈判时不要先说一个具体数字。先问薪酬结构(base/bonus/benefits)，再基于你的能力和市场水平报区间。报高了可能被拒，报低了会吃亏。做功课了解行业薪资区间后再谈。", "difficulty": "🔴进阶"}, {"id": 40, "file": "40-内部评估", "title": "内部评估", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Hi Peter, how was your interview with Steve?", "Yeah, he is one of the impressive candidates. I believe he is capable of taking on the role. Plus, his competency and skill set also give him an edge over others.", "Yes, I see what you are saying. He is indeed an old hand at solving problems and has a pretty good track record. Apart from that, he has unique traits, which I believe will bring positive impacts on our team."], "dialogueZH": ["嗨 Peter，你和 Steve 的面试怎么样？", "是的，他是让我印象深刻的候选人之一。我认为他有能力胜任这个岗位。此外，他的能力和技能组合也让他比其他人更有优势。", "是的，我明白你的意思。他确实是处理问题的老手，而且过去的表现记录也很好。除此之外，他还有一些独特的特质，我相信这些会给我们的团队带来积极影响。"], "vocabulary": [{"en": "impressive", "phonetic": "/ɪmˈpres.ɪv/", "pos": "adj.", "zh": "令人印象深刻的", "source": "one of the impressive candidates"}, {"en": "capable of", "phonetic": "/ˈkeɪ.pə.bəl əv/", "pos": "phr.", "zh": "有能力做某事", "source": "capable of taking on the role"}, {"en": "take on", "phonetic": "/teɪk ɑːn/", "pos": "v. phr.", "zh": "承担；接手", "source": "taking on the role"}, {"en": "competency", "phonetic": "/ˈkɑːm.pə.tən.si/", "pos": "n.", "zh": "能力；胜任力", "source": "his competency and skill set"}, {"en": "give an edge over", "phonetic": "/ɡɪv ən edʒ ˈoʊ.vər/", "pos": "idiom", "zh": "使...比...更有优势", "source": "give him an edge over others"}, {"en": "old hand", "phonetic": "/oʊld hænd/", "pos": "n.", "zh": "老手；经验丰富的人", "source": "an old hand at solving problems"}, {"en": "track record", "phonetic": "/træk ˈrek.ərd/", "pos": "n.", "zh": "过往记录；业绩记录", "source": "a pretty good track record"}, {"en": "bring positive impacts", "phonetic": "/brɪŋ ˈpɑː.zə.tɪv ˈɪm.pækts/", "pos": "v. phr.", "zh": "带来积极影响", "source": "bring positive impacts on our team"}], "grammar": [{"title": "I believe... (表示主观判断)", "structure": "I believe (that) + 从句", "example": "I believe he is capable of taking on the role.", "explanation": "I believe 用于表达个人看法/判断，比 I think 更正式，适合面试评估场合。"}], "coreSentences": [{"original": "He is one of the impressive candidates.", "function": "正面评价候选人", "alternative": "He stands out among all applicants. / He made a strong impression."}, {"original": "He is an old hand at solving problems.", "function": "称赞经验丰富", "alternative": "He's a veteran in problem-solving. / He has extensive experience handling issues."}, {"original": "His competency gives him an edge over others.", "function": "说明竞争优势", "alternative": "His skills set him apart from others. / His expertise makes him the top choice."}, {"original": "He has a pretty good track record.", "function": "评价过往表现", "alternative": "His past performance has been consistently strong. / He has a proven history of success."}], "exercises": {"vocabChoice": [{"question": "\"old hand\" 的意思是？", "options": ["老人的手", "老手/经验丰富的人", "新手", "手工活"], "answer": 1}, {"question": "\"track record\" 指什么？", "options": ["田径记录", "过往记录/业绩记录", "追踪器", "轨迹"], "answer": 1}], "fillBlank": [{"sentence": "His skills give him an ______ over other candidates.", "answer": "edge", "hint": "优势"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方职场面试后，面试官之间会进行'校准会议'(calibration)，对候选人进行横向比较。使用competency等专业术语而非笼统的'good'更能展示专业度。", "interviewTip": "", "difficulty": "🔵中级"}, {"id": 41, "file": "41-期望薪资", "title": "期望薪资", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["I’m glad that you’ve passed all the rounds of interviews, now let’s talk about your expected compensation.", "Wow, thanks. It’s a great privilege to have the opportunity to join your company. But before we get there, can I ask what the compensation structure is like for this position?", "Of course. Based on the rounds of interviews, we will grade the candidate based on his experience and competency. Compensation-structure-wise, we offer TP for this position, which consists of base salary and year-end bonuses. Base salary is determined by your grading, and year-end bonuses range from 2 to 4 months of salary based on the performance rating of the whole year. Also, we offer benefits like monthly housing subsidies of 1500 RMB.", "I see, the structure makes much sense, and I’m looking for a salary on the high end of your range. So based on my skillset and expertise, I would say 30k RMB per month for the base salary."], "dialogueZH": ["我很高兴你已经通过了所有面试环节，现在我们来谈谈你的薪酬期望。", "哇，非常感谢。能够有机会加入贵公司是我的荣幸。但在此之前，我想问一下，这个岗位的薪酬结构是怎样的？", "当然可以。根据多轮面试情况，我们会根据候选人的经验和能力进行评级。关于薪酬结构，这个岗位采用 TP 模式，包括基本工资和年终奖金。基本工资由评级决定，年终奖金根据全年绩效评定，一般为 2 到 4 个月的工资。此外，我们还提供每月 1500 元的住房补贴等福利。", "我明白，这个薪酬结构很合理。我希望能拿到你们区间的高端水平。基于我的技能和专业能力，我认为基本工资 30k 元每月是合适的。"], "vocabulary": [{"en": "passed all rounds", "phonetic": "/pæst ɔːl raʊndz/", "pos": "phr.", "zh": "通过了所有轮次", "source": "passed all the rounds of interviews"}, {"en": "compensation", "phonetic": "/ˌkɑːm.penˈseɪ.ʃən/", "pos": "n.", "zh": "薪酬；报酬", "source": "expected compensation"}, {"en": "privilege", "phonetic": "/ˈprɪv.əl.ɪdʒ/", "pos": "n.", "zh": "荣幸；特权", "source": "It's a great privilege"}, {"en": "compensation structure", "phonetic": "/ˌkɑːm.penˈseɪ.ʃən ˈstrʌk.tʃər/", "pos": "n. phr.", "zh": "薪酬结构", "source": "what the compensation structure is like"}, {"en": "grade", "phonetic": "/ɡreɪd/", "pos": "v.", "zh": "评级；打分", "source": "grade the candidate"}, {"en": "base salary", "phonetic": "/beɪs ˈsæl.ər.i/", "pos": "n.", "zh": "基本工资", "source": "consists of base salary and year-end bonuses"}, {"en": "year-end bonus", "phonetic": "/jɪr end ˈboʊ.nəs/", "pos": "n.", "zh": "年终奖金", "source": "year-end bonuses"}, {"en": "performance rating", "phonetic": "/pərˈfɔːr.məns ˈreɪ.tɪŋ/", "pos": "n.", "zh": "绩效评级", "source": "based on the performance rating"}, {"en": "benefits", "phonetic": "/ˈben.ə.fɪts/", "pos": "n.", "zh": "福利；待遇", "source": "we offer benefits"}, {"en": "housing subsidies", "phonetic": "/ˈhaʊ.zɪŋ ˈsʌb.sə.diz/", "pos": "n.", "zh": "住房补贴", "source": "monthly housing subsidies of 1500 RMB"}, {"en": "high end of the range", "phonetic": "/haɪ end əv ðə reɪndʒ/", "pos": "phr.", "zh": "区间的高端", "source": "looking for a salary on the high end of your range"}], "grammar": [{"title": "Compensation-structure-wise (复合副词)", "structure": "名词-wise = 在...方面", "example": "Compensation-structure-wise, we offer TP for this position.", "explanation": "-wise后缀表示\"在...方面\"。类似：time-wise, cost-wise, career-wise。是商务英语中非常地道、简洁的表达方式。"}], "coreSentences": [{"original": "Let's talk about your expected compensation.", "function": "切入薪资话题", "alternative": "Shall we discuss your salary expectations? / Let's go over the compensation package."}, {"original": "It's a great privilege to have the opportunity to join your company.", "function": "表达荣幸", "alternative": "I'm honored to be considered for this role. / It would be a privilege to join the team."}, {"original": "Can I ask what the compensation structure is like?", "function": "询问薪资结构", "alternative": "Could you walk me through the comp package? / How is the compensation structured?"}, {"original": "I'm looking for a salary on the high end of your range.", "function": "报价策略", "alternative": "I'm targeting the upper end of the band. / Based on my experience, I'd expect the higher end."}], "exercises": {"vocabChoice": [{"question": "\"compensation\" 在职场语境中表示？", "options": ["补偿", "薪酬/报酬", "赔偿金", "弥补"], "answer": 1}, {"question": "\"base salary\" 指什么？", "options": ["基础工资/底薪", "奖金", "福利", "津贴"], "answer": 0}], "fillBlank": [{"sentence": "It's a great ______ to join your company.", "answer": "privilege", "hint": "荣幸"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方薪资谈判中，先问薪酬结构再报价是标准流程。不要第一个说出数字——让雇主先给范围。用'high end of the range'表达期望，既自信又不咄咄逼人。", "interviewTip": "薪资谈判黄金法则：永远不要先说数字。先了解薪酬结构(base/bonus/benefits)，再做功课了解市场水平，最后基于自身价值报一个合理区间。", "difficulty": "🔴进阶"}, {"id": 42, "file": "42-HR谈薪资", "title": "HR谈薪资", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Okay, this figure is indeed within our budget, but let me double confirm with my supervisor and the BU manager, and get back to you by the end of this week, does that work for you?", "Great. Thanks a lot. I truly value this opportunity to become part of the company, and I’m looking forward to your feedback.", "I’m calling to discuss your salary, Steve.", "Go ahead.", "After several rounds of discussion with my managers, we believe you are the most suitable for this position. So we are offering you 28k.", "But to be frank, my compensation expectation is 30k. This is the least I can accept, and I believe it is a fair figure.", "Okay, I will try again."], "dialogueZH": ["好的，这个数字确实在我们的预算范围内，但我需要再和我的主管以及事业部经理确认一下，本周末之前再回复你，这样可以吗？", "太好了，非常感谢。我非常珍惜能够成为公司一员的机会，并期待您的反馈。", "我打电话来是想和你讨论一下薪资问题，Steve。", "请说。", "经过多轮与管理层的讨论，我们认为你是这个岗位最合适的人选。所以我们给你的报价是 28k。", "但坦白说，我的薪资期望是 30k。这是我能接受的最低数字，我认为这个数字是合理的。", "好的，我会再争取一下。"], "vocabulary": [{"en": "within our budget", "phonetic": "/wɪˈðɪn aʊər ˈbʌdʒ.ɪt/", "pos": "phr.", "zh": "在预算范围内", "source": "within our budget"}, {"en": "double confirm", "phonetic": "/ˈdʌb.əl kənˈfɜːrm/", "pos": "v. phr.", "zh": "再次确认", "source": "let me double confirm"}, {"en": "BU manager", "phonetic": "/biː juː ˈmæn.ɪ.dʒər/", "pos": "n.", "zh": "事业部经理(Business Unit)", "source": "the BU manager"}, {"en": "get back to you", "phonetic": "/ɡet bæk tə juː/", "pos": "phr.", "zh": "回复你；再联系你", "source": "get back to you by the end of this week"}, {"en": "offering", "phonetic": "/ˈɔː.fər.ɪŋ/", "pos": "v.", "zh": "报价；提供", "source": "we are offering you 28k"}, {"en": "to be frank", "phonetic": "/tə biː fræŋk/", "pos": "phr.", "zh": "坦白说", "source": "to be frank"}, {"en": "fair figure", "phonetic": "/fer ˈfɪɡ.jər/", "pos": "n. phr.", "zh": "合理的数字", "source": "I believe it is a fair figure"}, {"en": "value this opportunity", "phonetic": "/ˈvæl.juː ðɪs ˌɑː.pərˈtuː.nə.ti/", "pos": "v. phr.", "zh": "珍惜这个机会", "source": "I truly value this opportunity"}], "grammar": [{"title": "Does that work for you? (征求同意)", "structure": "Does that work for you?", "example": "Does that work for you?", "explanation": "非常地道的商务确认句型，比 Is that OK? 更正式。可在任何提议后使用。"}], "coreSentences": [{"original": "This figure is within our budget, but let me double confirm.", "function": "HR回应报价", "alternative": "That's in our range, but I need to check with leadership. / The number works, let me verify internally."}, {"original": "We are offering you 28k.", "function": "正式报价", "alternative": "Our offer is 28k. / We'd like to extend an offer of 28k."}, {"original": "To be frank, my expectation is 30k.", "function": "坦诚还价", "alternative": "Honestly, I was hoping for 30k. / To be candid, I'm looking for something closer to 30k."}, {"original": "I truly value this opportunity.", "function": "表达诚意", "alternative": "This role means a lot to me. / I'm genuinely excited about this position."}], "exercises": {"vocabChoice": [{"question": "\"to be frank\" 的意思是？", "options": ["法兰克人", "坦白说/老实说", "法国人", "弗兰克"], "answer": 1}, {"question": "\"get back to you\" 表示？", "options": ["回到你身边", "回复你/再联系", "拿回来", "回去"], "answer": 1}], "fillBlank": [{"sentence": "This figure is ______ our budget.", "answer": "within", "hint": "在...之内"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方HR谈薪资通常有2-3轮来回。第一轮HR报价通常不是最终数字——留了谈判空间。'Let me double confirm with my supervisor'是标准的暂缓话术。", "interviewTip": "", "difficulty": "🔴进阶"}, {"id": 43, "file": "43-信任引荐", "title": "信任引荐", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Before our weekly meeting, I’m delighted to introduce a new member to our team — Steve, please give him a warm welcome. Steve just joined us from Lenovo Group and will be project lead responsible for project set management in his primary scope. He is a battle-tested veteran with over a decade of experience in project management. Before joining us, Steve also worked for some other top-of-industry companies. We hope to see him bring some fresh perspectives and ideas to our BU. This is his first week, please help him to fit in.", "Steve, would you like to say something?"], "dialogueZH": ["在我们开始每周例会之前，我很高兴向大家介绍我们团队的新成员——Steve，请大家热烈欢迎他。Steve 刚从联想集团加入我们，将担任项目负责人，主要负责项目集管理。他是一位久经沙场的老将，拥有十多年项目管理经验。在加入我们之前，他也曾在多家行业顶尖公司任职。我们希望他能为我们的事业部带来新的视角和想法。这是他入职的第一周，请大家多多帮助他融入团队。", "Steve，你愿意说几句吗？"], "vocabulary": [{"en": "delighted", "phonetic": "/dɪˈlaɪ.tɪd/", "pos": "adj.", "zh": "高兴的；欣喜的", "source": "I'm delighted to introduce"}, {"en": "warm welcome", "phonetic": "/wɔːrm ˈwel.kəm/", "pos": "n. phr.", "zh": "热烈欢迎", "source": "give him a warm welcome"}, {"en": "project lead", "phonetic": "/ˈprɑː.dʒekt liːd/", "pos": "n.", "zh": "项目负责人", "source": "will be project lead"}, {"en": "battle-tested", "phonetic": "/ˈbæt.əl ˌtes.tɪd/", "pos": "adj.", "zh": "久经考验的", "source": "a battle-tested veteran"}, {"en": "veteran", "phonetic": "/ˈvet.ər.ən/", "pos": "n.", "zh": "老手；资深人士", "source": "a battle-tested veteran"}, {"en": "fresh perspectives", "phonetic": "/freʃ pərˈspek.tɪvz/", "pos": "n. phr.", "zh": "新视角；新思路", "source": "bring some fresh perspectives"}, {"en": "fit in", "phonetic": "/fɪt ɪn/", "pos": "v. phr.", "zh": "融入；适应", "source": "help him to fit in"}, {"en": "primary scope", "phonetic": "/ˈpraɪ.mer.i skoʊp/", "pos": "n.", "zh": "主要职责范围", "source": "project set management in his primary scope"}], "grammar": [{"title": "I'm delighted to + V (正式介绍语)", "structure": "I'm delighted to + 动词原形", "example": "I'm delighted to introduce a new member to our team.", "explanation": "比 I'm happy to 更正式，适合在团队会议或邮件中使用。"}], "coreSentences": [{"original": "I'm delighted to introduce a new member to our team.", "function": "正式引荐新人", "alternative": "It's my pleasure to introduce... / I'm thrilled to welcome..."}, {"original": "Please give him a warm welcome.", "function": "请大家欢迎", "alternative": "Let's give him a big welcome. / Please join me in welcoming..."}, {"original": "He is a battle-tested veteran with over a decade of experience.", "function": "介绍资深背景", "alternative": "He brings over 10 years of proven expertise. / He's a seasoned professional in this field."}, {"original": "We hope to see him bring fresh perspectives and ideas.", "function": "表达期望", "alternative": "We look forward to his insights. / We're excited about the new perspectives he'll bring."}], "exercises": {"vocabChoice": [{"question": "\"battle-tested\" 的意思是？", "options": ["战场测试", "久经考验的", "新兵", "未测试的"], "answer": 1}, {"question": "\"fit in\" 表示？", "options": ["锻炼", "融入/适应", "安装", "修理"], "answer": 1}], "fillBlank": [{"sentence": "Please give him a ______ welcome.", "answer": "warm", "hint": "热烈的"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方职场有正式的'new hire announcement'文化——新员工入职会由经理发邮件或在会议上正式介绍。这种仪式感有助于新人快速融入。", "interviewTip": "", "difficulty": "🟢入门"}, {"id": 44, "file": "44-入职介绍", "title": "入职介绍", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Hey guys, I am so excited to be here, and it’s my pleasure to join this amazing organization. Again, I am Steve. I graduated from PKU majoring in financial analysis and have been devoted to this field after graduation. Like John said, I will be supporting our business line in the role of project lead. I’m fresh off the boat and trying to settle in here, please take care of everything. Also, I am easy-going, extroverted and outspoken, so please feel free to hit me up for a coffee chat or show me around. Looking forward immensely to working with you here."], "dialogueZH": ["大家好，我非常兴奋能够来到这里，也很荣幸加入这样一个优秀的组织。我再自我介绍一下，我叫 Steve，毕业于北大，主修金融分析，毕业后一直从事这一领域的工作。正如 John 所说，我将以项目负责人的角色支持我们的业务线。我刚加入公司，还在适应环境，也请大家多多关照。另外，我性格随和、外向，也比较直爽，大家随时可以约我喝咖啡或带我熟悉一下环境。我非常期待能和大家一起共事。"], "vocabulary": [{"en": "amazing organization", "phonetic": "/əˈmeɪ.zɪŋ ˌɔːr.ɡən.ɪˈzeɪ.ʃən/", "pos": "n. phr.", "zh": "优秀的组织/公司", "source": "join this amazing organization"}, {"en": "financial analysis", "phonetic": "/faɪˈnæn.ʃəl əˈnæl.ə.sɪs/", "pos": "n.", "zh": "金融分析", "source": "majoring in financial analysis"}, {"en": "devoted to", "phonetic": "/dɪˈvoʊ.tɪd tə/", "pos": "adj. phr.", "zh": "致力于；专注于", "source": "been devoted to this field"}, {"en": "business line", "phonetic": "/ˈbɪz.nɪs laɪn/", "pos": "n.", "zh": "业务线；事业部", "source": "supporting our business line"}, {"en": "fresh off the boat", "phonetic": "/freʃ ɔːf ðə boʊt/", "pos": "idiom", "zh": "刚来的；新加入的", "source": "fresh off the boat"}, {"en": "settle in", "phonetic": "/ˈset.əl ɪn/", "pos": "v. phr.", "zh": "安顿下来；适应", "source": "trying to settle in here"}, {"en": "easy-going", "phonetic": "/ˈiː.zi ˌɡoʊ.ɪŋ/", "pos": "adj.", "zh": "随和的；好相处的", "source": "I am easy-going"}, {"en": "hit me up", "phonetic": "/hɪt miː ʌp/", "pos": "phr.", "zh": "联系我；找我(口语)", "source": "feel free to hit me up"}], "grammar": [{"title": "I graduated from...majoring in...", "structure": "I graduated from + 学校 + majoring in + 专业", "example": "I graduated from PKU majoring in financial analysis.", "explanation": "现在分词majoring修饰主语I，在自我介绍中同时说明学校和专业，简洁高效。"}], "coreSentences": [{"original": "It's my pleasure to join this amazing organization.", "function": "表达加入荣幸", "alternative": "I'm thrilled to be part of this team. / It's an honor to join such a great company."}, {"original": "I have been devoted to this field after graduation.", "function": "说明专业投入", "alternative": "I've dedicated my career to this area. / This field has been my focus since graduation."}, {"original": "I'm fresh off the boat and trying to settle in.", "function": "表达新人状态", "alternative": "I'm still getting oriented. / I'm learning the ropes here."}, {"original": "Please feel free to hit me up for a coffee chat.", "function": "邀请同事交流", "alternative": "Don't hesitate to reach out. / I'd love to grab coffee and get to know everyone."}], "exercises": {"vocabChoice": [{"question": "\"easy-going\" 的意思是？", "options": ["容易走的", "随和的/好相处的", "简单的", "困难的"], "answer": 1}, {"question": "\"settle in\" 表示？", "options": ["坐下", "安顿下来/适应", "解决", "定居国外"], "answer": 1}], "fillBlank": [{"sentence": "I'm fresh off the ______ and still settling in.", "answer": "boat", "hint": "刚来的(习语)"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方职场新人入职时通常会做一个简短的自我介绍(30秒-1分钟)，包括背景、角色、个人特点。'Fresh off the boat'是自嘲式幽默，适合缓和紧张气氛。", "interviewTip": "", "difficulty": "🟢入门"}, {"id": 45, "file": "45-熟悉团队", "title": "熟悉团队", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Now, let me just quickly introduce key team members from other teams, especially our C-suite, so you can get a bigger picture of our org chart. This is Peter, who is the CTO of our group. He has a large tech team under him, which is based in five countries around the world, each location has more than 60 engineers. And this is Alice, she is the ops director of our business line. Ops team’s work scope sometimes overlaps with CS team, and usually partners closely with tech team to better serve our customers.", "I assume you will have many things to catch up with them. For anything unclear, you can reach out to them in terms of ops and tech."], "dialogueZH": ["现在，我先简单介绍一下来自其他团队的关键成员，尤其是我们高管团队的成员，这样你能对我们的组织架构有更全面的了解。这位是 Peter，他是我们集团的首席技术官（CTO）。他的技术团队规模很大，分布在全球五个国家，每个地点都有六十多名工程师。 这位是 Alice，她是我们业务线的运营总监。运营团队的工作范围有时会与客服团队有所重叠，并且通常会与技术团队紧密合作，以更好地服务客户。", "我想你之后会有很多事情需要与他们对接。如果有任何不清楚的地方，关于运营或技术方面的内容，你都可以随时联系他们。"], "vocabulary": [{"en": "C-suite", "phonetic": "/siː swiːt/", "pos": "n.", "zh": "高管层(CEO/CFO/CTO等)", "source": "our C-suite"}, {"en": "org chart", "phonetic": "/ɔːrɡ tʃɑːrt/", "pos": "n.", "zh": "组织架构图", "source": "a bigger picture of our org chart"}, {"en": "CTO", "phonetic": "/siː tiː oʊ/", "pos": "n. abbr.", "zh": "首席技术官", "source": "the CTO of our group"}, {"en": "ops director", "phonetic": "/ɑːps dɪˈrek.tər/", "pos": "n.", "zh": "运营总监", "source": "the ops director of our business line"}, {"en": "overlap", "phonetic": "/ˌoʊ.vərˈlæp/", "pos": "v.", "zh": "重叠；交叉", "source": "work scope sometimes overlaps"}, {"en": "catch up with", "phonetic": "/kætʃ ʌp wɪð/", "pos": "v. phr.", "zh": "与...对接；赶上", "source": "many things to catch up with them"}, {"en": "reach out to", "phonetic": "/riːtʃ aʊt tə/", "pos": "v. phr.", "zh": "联系；接触", "source": "you can reach out to them"}], "grammar": [{"title": "Who引导的非限定性定语从句", "structure": "人名, who + 从句", "example": "This is Peter, who is the CTO of our group.", "explanation": "who在逗号后引导非限定定语从句，提供补充信息，使介绍更自然流畅。"}], "coreSentences": [{"original": "Let me quickly introduce key team members.", "function": "开始介绍团队", "alternative": "Let me give you a quick overview of the key players. / Here's a rundown of the team."}, {"original": "You can get a bigger picture of our org chart.", "function": "了解组织架构", "alternative": "This will give you a sense of how we're structured. / This helps you see the big picture."}, {"original": "Their work scope sometimes overlaps with CS team.", "function": "说明部门关系", "alternative": "There's some overlap between these teams. / They work closely with the CS team."}, {"original": "You can reach out to them for anything unclear.", "function": "鼓励沟通", "alternative": "Feel free to contact them with any questions. / They're your go-to for ops and tech queries."}], "exercises": {"vocabChoice": [{"question": "\"C-suite\" 指的是？", "options": ["C级套房", "高管层(CEO/CTO等)", "员工食堂", "普通办公室"], "answer": 1}, {"question": "\"org chart\" 是什么意思？", "options": ["组织结构图", "原图", "图表", "组织制度"], "answer": 0}], "fillBlank": [{"sentence": "You can ______ out to them if you have any questions.", "answer": "reach", "hint": "联系(与out搭配)"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方公司有专门的'onboarding buddy'制度——给新人配一位同事帮助熟悉团队。主动介绍组织架构是新经理的重要职责，帮助新人快速建立'mental map'。", "interviewTip": "", "difficulty": "🔵中级"}, {"id": 46, "file": "46-寻求帮助", "title": "寻求帮助", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Mary, may I trouble you to cross-check the data in this report for me? This is my first time and I don’t want to screw it up.", "Who are you sending this report to?", "The department head. He needs to report on this in the all-hands meeting this week.", "Okay, but I have an interview call coming soon, need to jump on to it in 10 minutes, I’ll review it once I’m done.", "No rush, the head needs that by end of tomorrow, so reviewing it by EOD should be fine.", "I found a few typos in the report, and underlined the adjustments, you can check it. Also, highly suggest you use the template to write the report next time, I can email it to you if you need.", "Big thanks, really helpful, you saved my day!"], "dialogueZH": ["Mary，我能麻烦你帮我核对一下这份报告里的数据吗？这是我第一次做，我不想搞砸。", "你要把这份报告发给谁？", "部门负责人。他这周需要在全员大会上汇报这个内容。", "好的，但我马上有一个面试电话，10 分钟后就要接入。我处理完之后会再看这份文件。", "不急，部门负责人要在明天结束前拿到，所以你今天下班前看一下就可以。", "我在报告里发现了几个错别字，并把需要调整的地方都划线标出来了，你可以看一下。另外，非常建议你下次写报告时使用模板，如果你需要，我可以发给你。", "太感谢了，真的帮大忙了！"], "vocabulary": [{"en": "trouble you", "phonetic": "/ˈtrʌb.əl juː/", "pos": "phr.", "zh": "麻烦你；打扰你", "source": "may I trouble you"}, {"en": "cross-check", "phonetic": "/krɔːs tʃek/", "pos": "v.", "zh": "交叉核对；核实", "source": "cross-check the data"}, {"en": "screw up", "phonetic": "/skruː ʌp/", "pos": "v. phr.", "zh": "搞砸；弄糟", "source": "don't want to screw it up"}, {"en": "department head", "phonetic": "/dɪˈpɑːrt.mənt hed/", "pos": "n.", "zh": "部门负责人", "source": "the department head"}, {"en": "all-hands meeting", "phonetic": "/ɔːl hændz ˈmiː.tɪŋ/", "pos": "n.", "zh": "全员大会", "source": "the all-hands meeting"}, {"en": "jump on to it", "phonetic": "/dʒʌmp ɑːn tə ɪt/", "pos": "phr.", "zh": "赶紧处理；马上投入", "source": "need to jump on to it"}, {"en": "EOD (End of Day)", "phonetic": "/iː oʊ diː/", "pos": "n. abbr.", "zh": "当天结束前；下班前", "source": "reviewing it by EOD"}, {"en": "typos", "phonetic": "/ˈtaɪ.poʊz/", "pos": "n.", "zh": "错别字；拼写错误", "source": "found a few typos"}, {"en": "template", "phonetic": "/ˈtem.plət/", "pos": "n.", "zh": "模板", "source": "use the template"}, {"en": "you saved my day", "phonetic": "/juː seɪvd maɪ deɪ/", "pos": "phr.", "zh": "你帮了我大忙", "source": "you saved my day"}], "grammar": [{"title": "May I trouble you to...? (礼貌请求)", "structure": "May I trouble you to + 动词原形?", "example": "May I trouble you to cross-check the data?", "explanation": "最礼貌的请求句型之一，比 Can you help me 正式得多，适合对同事的first request。"}], "coreSentences": [{"original": "May I trouble you to cross-check the data for me?", "function": "礼貌请求帮助", "alternative": "Could I ask you a favor? / Would you mind checking this for me?"}, {"original": "This is my first time and I don't want to screw it up.", "function": "说明求助原因", "alternative": "Since it's my first attempt, I want to make sure it's right."}, {"original": "Reviewing it by EOD should be fine.", "function": "确认截止时间", "alternative": "End of day works for me. / Before EOD would be great."}, {"original": "You saved my day!", "function": "表达感谢", "alternative": "You're a lifesaver! / I can't thank you enough!"}], "exercises": {"vocabChoice": [{"question": "\"EOD\" 指什么？", "options": ["每个开放日", "当天结束前/下班前", "月末", "年初"], "answer": 1}, {"question": "\"screw up\" 的意思是？", "options": ["拧螺丝", "搞砸/弄糟", "上紧", "开始"], "answer": 1}], "fillBlank": [{"sentence": "This is my first time and I don't want to ______ it up.", "answer": "screw", "hint": "搞砸"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方职场鼓励'ask for help'的文化——寻求帮助被视为聪明而非无能。关键在于：1)说明你已尝试过 2)说清楚你需要什么帮助 3)尊重对方时间。用EOD/EOB等时间缩写非常常见。", "interviewTip": "", "difficulty": "🟢入门"}, {"id": 47, "file": "47-主动协助", "title": "主动协助", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Hey, I learnt you were tasked with conducting competitor studies in the new market. I bet you have too much on your plate to juggle, right?", "Yeah, you bet. Also, we have a pretty tight schedule, so probably I need to burn the midnight oil to meet the deadline.", "Poor you, I know exactly what you’re going through as I took on similar work previously. Besides, I will finish my priorities next week, so I may have extra bandwidth to give a lending hand.", "Wow, that’s so kind of you, I owe you one!"], "dialogueZH": ["嘿，我听说你被安排去做新市场的竞品调研了。我猜你现在一定忙得不可开交，对吧？", "是啊，确实如此。而且我们的时间安排非常紧，可能我得熬夜加班才能赶上截止日期。", "真辛苦你了，我完全理解你的处境，因为我之前也做过类似的工作。另外，我下周能把自己的优先事项处理完，可能会有一些空余时间来帮你一把。", "哇，你太好了，真是欠你一个人情！"], "vocabulary": [{"en": "tasked with", "phonetic": "/tæskt wɪð/", "pos": "v. phr.", "zh": "被分配任务；被委派", "source": "you were tasked with"}, {"en": "competitor studies", "phonetic": "/kəmˈpet.ɪ.tər ˈstʌd.iz/", "pos": "n.", "zh": "竞品研究；对手分析", "source": "conducting competitor studies"}, {"en": "too much on your plate", "phonetic": "/tuː mʌtʃ ɑːn jər pleɪt/", "pos": "idiom", "zh": "手头事情太多；忙不过来", "source": "too much on your plate to juggle"}, {"en": "tight schedule", "phonetic": "/taɪt ˈskedʒ.uːl/", "pos": "n.", "zh": "紧凑的日程", "source": "a pretty tight schedule"}, {"en": "burn the midnight oil", "phonetic": "/bɜːrn ðə ˈmɪd.naɪt ɔɪl/", "pos": "idiom", "zh": "熬夜工作；开夜车", "source": "burn the midnight oil"}, {"en": "bandwidth", "phonetic": "/ˈbænd.wɪdθ/", "pos": "n.", "zh": "带宽；精力/时间余量", "source": "have extra bandwidth"}, {"en": "give a lending hand", "phonetic": "/ɡɪv ə ˈlen.dɪŋ hænd/", "pos": "idiom", "zh": "伸出援手；帮忙", "source": "give a lending hand"}, {"en": "I owe you one", "phonetic": "/aɪ oʊ juː wʌn/", "pos": "phr.", "zh": "我欠你一个人情", "source": "I owe you one"}], "grammar": [{"title": "I bet... (口语推断)", "structure": "I bet + 从句", "example": "I bet you have too much on your plate.", "explanation": "I bet = 我敢打赌/我猜，口语中表达同理心的常用句型，不是真的打赌。"}], "coreSentences": [{"original": "I bet you have too much on your plate to juggle.", "function": "表达同理", "alternative": "Sounds like you're swamped. / You must be overwhelmed."}, {"original": "I need to burn the midnight oil to meet the deadline.", "function": "表达赶工", "alternative": "I'll be working late to hit the deadline. / Looks like another all-nighter."}, {"original": "I may have extra bandwidth to give a lending hand.", "function": "主动提供帮助", "alternative": "I have some spare capacity to help out. / I can free up time to assist."}, {"original": "I owe you one!", "function": "表达感谢和回馈意愿", "alternative": "I'll make it up to you! / Next one's on me!"}], "exercises": {"vocabChoice": [{"question": "\"too much on your plate\" 表示？", "options": ["盘子太重", "事情太多/忙不过来", "菜太多", "吃不完"], "answer": 1}, {"question": "\"burn the midnight oil\" 意思是？", "options": ["烧油", "熬夜工作", "点灯", "浪费资源"], "answer": 1}], "fillBlank": [{"sentence": "I may have extra ______ to help you out.", "answer": "bandwidth", "hint": "精力/时间余量"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方职场中，主动提供帮助(proactive helping)是被高度赞赏的团队精神。但要注意：先确保自己的工作完成，再有'extra bandwidth'去帮别人，不要牺牲自己的交付。", "interviewTip": "", "difficulty": "🔵中级"}, {"id": 48, "file": "48-IT报修", "title": "IT报修", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Hey John, can you come over to help me with my laptop? I can’t figure out how to connect it with my projector. Technical issues just popped up from time to time. Sometimes it just crashed.", "Happy to assist. But can you give me one second, I have some urgent matters to handle at the moment. Obviously it is an issue with the system, you could just reboot and start over. I’ll share the manual with you first, you should be able to connect by following the instructions.", "Wow, that would be helpful too, highly appreciate it."], "dialogueZH": ["嘿 John，你能过来帮我看看我的笔记本吗？我搞不清楚怎么把它连接到投影仪。技术问题总是时不时冒出来，有时候它甚至直接崩溃。", "很乐意帮你。但你能给我一秒吗？我现在有些紧急的事情要处理。显然这是系统的问题，你可以先重启再试一次。我先把操作手册发给你，你按照说明应该就能连上。", "哇，那也太有帮助了，非常感谢！"], "vocabulary": [{"en": "figure out", "phonetic": "/ˈfɪɡ.jər aʊt/", "pos": "v. phr.", "zh": "弄明白；搞清楚", "source": "can't figure out how to connect"}, {"en": "projector", "phonetic": "/prəˈdʒek.tər/", "pos": "n.", "zh": "投影仪", "source": "connect it with my projector"}, {"en": "pop up", "phonetic": "/pɑːp ʌp/", "pos": "v. phr.", "zh": "突然出现", "source": "issues just popped up from time to time"}, {"en": "crash", "phonetic": "/kræʃ/", "pos": "v.", "zh": "崩溃；死机", "source": "it just crashed"}, {"en": "urgent matters", "phonetic": "/ˈɜːr.dʒənt ˈmæt.ərz/", "pos": "n. phr.", "zh": "紧急事务", "source": "some urgent matters to handle"}, {"en": "reboot", "phonetic": "/ˌriːˈbuːt/", "pos": "v.", "zh": "重启", "source": "you could just reboot"}, {"en": "manual", "phonetic": "/ˈmæn.ju.əl/", "pos": "n.", "zh": "手册；指南", "source": "share the manual"}], "grammar": [{"title": "Can you come over to help me with...?", "structure": "Can you come over to help me with + 名词?", "example": "Can you come over to help me with my laptop?", "explanation": "come over = 过来一下。would be helpful的含蓄表达让请求更礼貌。"}], "coreSentences": [{"original": "Can you come over to help me with my laptop?", "function": "请求现场帮助", "alternative": "Could you take a look at my laptop? / Mind helping me with a tech issue?"}, {"original": "I can't figure out how to connect it.", "function": "说明具体问题", "alternative": "I'm stuck trying to connect this. / I'm having trouble with the connection."}, {"original": "Happy to assist, but can you give me one second?", "function": "乐意帮忙但稍等", "alternative": "Sure, just give me a moment. / I'd be happy to — let me wrap up something first."}, {"original": "You could just reboot and start over.", "function": "建议重启", "alternative": "Try rebooting first. / A quick restart might fix it."}], "exercises": {"vocabChoice": [{"question": "\"figure out\" 的意思是？", "options": ["算出来", "弄明白/解决", "放弃", "画画"], "answer": 1}, {"question": "\"reboot\" 表示？", "options": ["重新启动", "启动", "开机", "关掉"], "answer": 0}], "fillBlank": [{"sentence": "Technical issues ______ up from time to time.", "answer": "pop", "hint": "突然出现"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方办公室有IT help desk，但同事间的小问题通常先自己看手册或重启解决。求助时先说明自己试过什么(what you've tried)是基本礼仪。", "interviewTip": "", "difficulty": "🟢入门"}, {"id": 49, "file": "49-寒暄-聊天气", "title": "寒暄-聊天气", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["What a lovely weather!", "Yeah, it’s quite rare to see blue skies, hope this can last for a while.", "Absolutely, we better make the use of this nice weather while it lasts. How about hanging around the neighborhood after lunch, maybe grab some coffee from a nearby store.", "I’ll pass this time, as I need to prepare for an ad hoc meeting.", "Well, bad timing.", "Thanks for asking though, I will join next time."], "dialogueZH": ["今天天气真好！", "是啊，难得看到蓝天，希望能持续一会儿。", "完全同意，我们得趁着好天气多出去走走。午饭后在附近逛逛怎么样？也可以顺便去附近的店买杯咖啡。", "这次我就不去了，我得准备一个临时会议。", "哎，真是赶得不巧。", "不过谢谢你邀请，下次我一定参加。"], "vocabulary": [{"en": "What a lovely weather!", "phonetic": "/wʌt ə ˈlʌv.li ˈweð.ər/", "pos": "excl.", "zh": "天气真好！", "source": "What a lovely weather!"}, {"en": "blue skies", "phonetic": "/bluː skaɪz/", "pos": "n. phr.", "zh": "蓝天", "source": "rare to see blue skies"}, {"en": "make the use of", "phonetic": "/meɪk ðə juːz əv/", "pos": "v. phr.", "zh": "利用；好好享受", "source": "make the use of this nice weather"}, {"en": "hang around", "phonetic": "/hæŋ əˈraʊnd/", "pos": "v. phr.", "zh": "闲逛；四处走走", "source": "hanging around the neighborhood"}, {"en": "grab some coffee", "phonetic": "/ɡræb sʌm ˈkɔː.fi/", "pos": "v. phr.", "zh": "买杯咖啡", "source": "grab some coffee"}, {"en": "ad hoc meeting", "phonetic": "/æd hɑːk ˈmiː.tɪŋ/", "pos": "n.", "zh": "临时会议", "source": "an ad hoc meeting"}, {"en": "bad timing", "phonetic": "/bæd ˈtaɪ.mɪŋ/", "pos": "phr.", "zh": "时机不好；不凑巧", "source": "bad timing"}, {"en": "I'll pass this time", "phonetic": "/aɪl pæs ðɪs taɪm/", "pos": "phr.", "zh": "这次我就不去了", "source": "I'll pass this time"}], "grammar": [{"title": "What a + 名词! (感叹句)", "structure": "What a/an + 形容词 + 名词!", "example": "What a lovely weather!", "explanation": "感叹句结构，比陈述句更有感染力。是small talk的经典开场白。"}], "coreSentences": [{"original": "What a lovely weather!", "function": "small talk 开场", "alternative": "Beautiful day, isn't it? / Can't believe how nice it is outside."}, {"original": "We better make the use of this nice weather while it lasts.", "function": "提议趁天气好做点什么", "alternative": "Let's enjoy it while we can. / Better take advantage of the sunshine."}, {"original": "How about hanging around the neighborhood after lunch?", "function": "邀请散步/咖啡", "alternative": "Fancy a walk after lunch? / Want to grab a coffee later?"}, {"original": "I'll pass this time, but thanks for asking.", "function": "礼貌拒绝+感谢", "alternative": "Not today, but I'd love to next time. / Rain check?"}], "exercises": {"vocabChoice": [{"question": "\"ad hoc\" 什么意思？", "options": ["广告", "临时的/即兴的", "正式的", "长期的"], "answer": 1}, {"question": "\"I'll pass\" 表示？", "options": ["我通过", "我不去了/略过", "我经过", "我要去"], "answer": 1}], "fillBlank": [{"sentence": "We better make the ______ of this nice weather.", "answer": "use", "hint": "利用"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "英国人尤其喜欢用天气开启闲聊(weather small talk)，这是最安全、最通用的社交开场白。在西方职场，small talk是建立同事关系的重要润滑剂。", "interviewTip": "", "difficulty": "🟢入门"}, {"id": 50, "file": "50-寒暄-聊周末", "title": "寒暄-聊周末", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Hey John, how are you doing, Good weekend?", "It was really nice, Thank you. I have been pulling all-nighters recently, so I just had a chill weekend, spent half day catching up on sleep and hung out for a meal with friends last night. How about you, What have you been up to this weekend?", "Much the same, I just worked out lately to beat the pressure, too many things to sort out in work."], "dialogueZH": ["嘿，John，最近怎么样？周末过得好吗？", "真的很棒，谢谢。我最近一直在熬夜加班，所以我度过了一个很放松的周末，花了半天时间补觉，昨晚还和朋友出去吃了顿饭。你呢？这个周末你都在忙什么？", "差不多吧，我最近去健身了，想缓解一下压力，工作里有太多事情要处理了。"], "vocabulary": [{"en": "Good weekend?", "phonetic": "/ɡʊd ˈwiːk.end/", "pos": "phr.", "zh": "周末好吗？", "source": "Good weekend?"}, {"en": "pull all-nighters", "phonetic": "/pʊl ɔːl ˈnaɪ.tərz/", "pos": "idiom", "zh": "熬夜；通宵(工作/学习)", "source": "pulling all-nighters recently"}, {"en": "chill weekend", "phonetic": "/tʃɪl ˈwiːk.end/", "pos": "n. phr.", "zh": "轻松的周末", "source": "a chill weekend"}, {"en": "catch up on sleep", "phonetic": "/kætʃ ʌp ɑːn sliːp/", "pos": "v. phr.", "zh": "补觉", "source": "catching up on sleep"}, {"en": "hang out", "phonetic": "/hæŋ aʊt/", "pos": "v. phr.", "zh": "出去玩；聚会", "source": "hung out for a meal"}, {"en": "work out", "phonetic": "/wɜːrk aʊt/", "pos": "v. phr.", "zh": "锻炼；健身", "source": "I just worked out lately"}, {"en": "beat the pressure", "phonetic": "/biːt ðə ˈpreʃ.ər/", "pos": "phr.", "zh": "缓解压力", "source": "to beat the pressure"}, {"en": "sort out", "phonetic": "/sɔːrt aʊt/", "pos": "v. phr.", "zh": "处理；理清", "source": "things to sort out in work"}], "grammar": [{"title": "How about you? (反问对方)", "structure": "陈述句。How about you?", "example": "How about you?", "explanation": "回答对方问题后反问，让对话持续，是社交对话的基本技巧。也可说 What about you?"}], "coreSentences": [{"original": "How are you doing? Good weekend?", "function": "周一问候", "alternative": "How was your weekend? / Did you have a nice weekend?"}, {"original": "I had a chill weekend, spent half day catching up on sleep.", "function": "描述周末", "alternative": "Pretty relaxing — mostly caught up on rest. / Low-key weekend, just recharged."}, {"original": "I just worked out lately to beat the pressure.", "function": "描述减压方式", "alternative": "I've been hitting the gym to de-stress. / Exercise has been my stress relief."}, {"original": "Too many things to sort out in work.", "function": "委婉表达工作忙", "alternative": "Work has been crazy lately. / There's a lot on my plate at work."}], "exercises": {"vocabChoice": [{"question": "\"pull all-nighters\" 意思是？", "options": ["拉夜灯", "熬夜/通宵", "晚上工作", "拉拽"], "answer": 1}, {"question": "\"sort out\" 表示？", "options": ["分类", "处理/理清", "出去", "排序"], "answer": 1}], "fillBlank": [{"sentence": "I spent half day catching up on ______.", "answer": "sleep", "hint": "补觉"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "周一早上同事之间聊周末是西方职场最自然的small talk。不需要详细描述——简短轻松的回答最好。如果对方显得特别忙，表达同理('sounds like you needed that break')会有加分。", "interviewTip": "", "difficulty": "🟢入门"}, {"id": 51, "file": "51-怼同事甩锅", "title": "怼同事甩锅", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Hey, John. I’m really upset with you. You sent that document to the client without double checking it.", "I’m sorry to hear that, Steve. But I don’t think it’s fair to hold me accountable for this. I couldn’t afford time to review it, and I thought the doc was fine.", "Well, it wasn’t. The client came back saying that there were a lot of inaccurate info and it wasn’t up to our company’s standards.", "I think there was miscommunication on both sides here. You should have told me that you wanted to review the document before sending it out.", "That’s not an excuse, John. You should have communicated with me better and let me know that you were struggling to get it done. We both know that it’s always been our procedure to cross check each other’s work.", "I’m sorry, Steve. I’ll take responsibility for my part in this, but I don’t think I’m the only one to be blamed.", "I’m not completely blaming you. But you need to understand that this mistake has compromised our company’s reputation. Moving forward, we need to ensure that we don’t let this happen again.", "Agreed. Let’s schedule regular check-ins on projects in the future."], "dialogueZH": ["嘿，John，我真的对你很不满。你把文件发给客户之前都没有仔细检查。", "很抱歉听到你这么说，Steve。但我觉得把这件事算在我头上不太公平。我当时没有时间检查，而且我以为文件没问题。", "但事实并非如此。客户反馈说里面有很多不准确的信息，而且不符合我们公司的标准。", "我觉得这是双方沟通不清造成的。你应该提前告诉我，你想在发出去之前再审阅一遍文件。", "这不是借口，John。你本应该更好地和我沟通，让我知道你在完成这件事时遇到了困难。我们都清楚，互相交叉检查工作一直是我们的流程。", "抱歉，Steve。我会为我这部分承担责任，但我不认为只有我一个人应该被责备。", "我并不是完全在怪你。但你需要明白，这次的错误已经影响了公司的声誉。接下来，我们必须确保不再让这种情况发生。", "同意。我们以后给项目安排定期的进度沟通吧。"], "vocabulary": [{"en": "upset with", "phonetic": "/ʌpˈset wɪð/", "pos": "adj. phr.", "zh": "对...生气/不满", "source": "really upset with you"}, {"en": "double check", "phonetic": "/ˈdʌb.əl tʃek/", "pos": "v. phr.", "zh": "仔细检查；复核", "source": "without double checking it"}, {"en": "hold accountable", "phonetic": "/hoʊld əˈkaʊn.tə.bəl/", "pos": "v. phr.", "zh": "问责；让...负责", "source": "hold me accountable for this"}, {"en": "inaccurate", "phonetic": "/ɪnˈæk.jər.ət/", "pos": "adj.", "zh": "不准确的", "source": "a lot of inaccurate info"}, {"en": "up to standards", "phonetic": "/ʌp tə ˈstæn.dərdz/", "pos": "phr.", "zh": "符合标准", "source": "up to our company's standards"}, {"en": "miscommunication", "phonetic": "/ˌmɪs.kəˌmjuː.nɪˈkeɪ.ʃən/", "pos": "n.", "zh": "沟通不畅；误解", "source": "miscommunication on both sides"}, {"en": "procedure", "phonetic": "/prəˈsiː.dʒər/", "pos": "n.", "zh": "流程；程序", "source": "it's always been our procedure"}, {"en": "compromise", "phonetic": "/ˈkɑːm.prə.maɪz/", "pos": "v.", "zh": "损害；连累（名誉等）", "source": "compromised our company's reputation"}, {"en": "moving forward", "phonetic": "/ˈmuː.vɪŋ ˈfɔːr.wərd/", "pos": "phr.", "zh": "今后；接下来", "source": "Moving forward, we need to ensure..."}, {"en": "take responsibility for", "phonetic": "/teɪk rɪˌspɑːn.səˈbɪl.ə.ti/", "pos": "v. phr.", "zh": "为...承担责任", "source": "take responsibility for my part"}], "grammar": [{"title": "You should have + 过去分词 (虚拟语气表后悔/责备)", "structure": "You should have + 过去分词", "example": "You should have told me that you wanted to review the document.", "explanation": "Should have done 表示\"本应该做(但没做)\"，在职场冲突对话中常用于责备或反思。"}], "coreSentences": [{"original": "I'm really upset with you.", "function": "表达不满(直接)", "alternative": "I need to talk to you about something that bothered me. / I have an issue I need to raise."}, {"original": "I don't think it's fair to hold me accountable for this.", "function": "反驳/辩解", "alternative": "I don't think I should take all the blame. / It's not entirely my responsibility."}, {"original": "There was miscommunication on both sides.", "function": "指出双方都有责任", "alternative": "We both dropped the ball on communication. / It's a shared failure."}, {"original": "This mistake has compromised our company's reputation.", "function": "说明后果严重性", "alternative": "This error has damaged our credibility. / The company's image took a hit."}], "exercises": {"vocabChoice": [{"question": "\"hold accountable\" 的意思是？", "options": ["持有账户", "问责/追究责任", "保留", "计算"], "answer": 1}, {"question": "\"miscommunication\" 指什么？", "options": ["正确沟通", "沟通不畅/误解", "单向沟通", "写信"], "answer": 1}], "fillBlank": [{"sentence": "This mistake has ______ our company's reputation.", "answer": "compromised", "hint": "损害"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方职场冲突处理强调'直接但不攻击'。可以说'I'm upset'表达情绪，但要聚焦在事件而非人身攻击。'Moving forward'是冲突对话中重要的转折词——把焦点从追究过去转向解决问题。", "interviewTip": "", "difficulty": "🔴进阶"}, {"id": 52, "file": "52-怼同事不尽责1", "title": "怼同事不尽责1", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Hey, John. I just want to check in with you over where you are now with this project. You’ve missed the deadline last week, and this would hinder the team from proceeding with next steps.", "No, I’m not trying to pass the buck here, but really, it wasn’t my fault. You know we had some unexpected technical issues, which denied my access to the database. If the tech guys had kept the system stable, I wouldn’t have dropped the ball this time.", "Look, I appointed you as the PIC since I trusted your expertise and competency in this area. But it’s a bit disappointing that I was informed of this delay at the last minute. I understand there were small technical glitches, but it doesn’t make any sense to essentially shift the blame to the tech team. You should have let me know upfront that your hands were tied up, so at least I have enough time to find someone else to help out, or ask the leadership to sort out the priorities beforehand. At the end of the day, I don’t want to eat into your bandwidth or have you feel overstretched."], "dialogueZH": ["嘿，John，我想了解一下你现在这个项目的进度。你上周错过了截止日期，这会影响团队推进下一步工作。", "不，我不是想推卸责任，但这真的不是我的错。你也知道我们遇到了一些突发的技术问题，导致我无法访问数据库。如果技术团队当时把系统稳定住，我这次也不会失误。", "听着，我之所以指派你作为负责人，是因为我信任你在这个领域的专业能力。但让我有点失望的是，我是在最后一刻才被告知这个延误。我理解确实有一些小的技术故障，但把责任推给技术团队并不合理。你本应该提前告诉我你这边分身乏术，这样我至少还能有时间找别人帮忙，或者请领导提前协调优先级。归根结底，我并不想占用你太多精力，也不希望你感到压力过大。"], "vocabulary": [{"en": "check in with", "phonetic": "/tʃek ɪn wɪð/", "pos": "v. phr.", "zh": "与...确认；了解情况", "source": "check in with you over"}, {"en": "miss the deadline", "phonetic": "/mɪs ðə ˈded.laɪn/", "pos": "v. phr.", "zh": "错过截止日期", "source": "missed the deadline last week"}, {"en": "hinder", "phonetic": "/ˈhɪn.dər/", "pos": "v.", "zh": "阻碍；妨碍", "source": "hinder the team from proceeding"}, {"en": "pass the buck", "phonetic": "/pæs ðə bʌk/", "pos": "idiom", "zh": "推卸责任", "source": "trying to pass the buck"}, {"en": "PIC (Person In Charge)", "phonetic": "/piː aɪ siː/", "pos": "n.", "zh": "负责人", "source": "appointed you as the PIC"}, {"en": "at the last minute", "phonetic": "/æt ðə læst ˈmɪn.ɪt/", "pos": "phr.", "zh": "在最后一刻", "source": "informed at the last minute"}, {"en": "escalation", "phonetic": "/ˌes.kəˈleɪ.ʃən/", "pos": "n.", "zh": "升级；上报", "source": "pulled in an escalation"}], "grammar": [{"title": "It's disappointing that... (表达失望)", "structure": "It's disappointing that + 从句", "example": "It's a bit disappointing that I was informed at the last minute.", "explanation": "用disappointing而非angry表达不满，语气更专业克制，是职场中高级的表达方式。"}], "coreSentences": [{"original": "I just want to check in with you over your progress.", "function": "了解进度(不指责)", "alternative": "Can we touch base on where things stand? / Let's sync up on your progress."}, {"original": "This would hinder the team from proceeding.", "function": "说明影响", "alternative": "This is holding up the rest of the team. / The delay is blocking others."}, {"original": "I'm not trying to pass the buck here.", "function": "声明不推卸责任", "alternative": "I'm not shirking responsibility. / I'm not pointing fingers."}, {"original": "I trusted your expertise and competency in this area.", "function": "表达信任+失望", "alternative": "I had confidence in you on this. / I counted on your skills here."}], "exercises": {"vocabChoice": [{"question": "\"pass the buck\" 意思是？", "options": ["传递钱币", "推卸责任", "给钱", "通过"], "answer": 1}, {"question": "\"PIC\" 是什么缩写？", "options": ["Picture", "Person In Charge", "People In Company", "Project In Control"], "answer": 1}], "fillBlank": [{"sentence": "Don't try to ______ the buck.", "answer": "pass", "hint": "推卸责任"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方管理者在问责时常用'I'm disappointed'而非'I'm angry'。前者体现专业克制，后者被视为情绪化。同时，好的管理者会区分'过程问题'和'态度问题'。", "interviewTip": "", "difficulty": "🔴进阶"}, {"id": 53, "file": "53-怼同事得寸进尺2", "title": "怼同事得寸进尺2", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Hey, Steve. You got one second? I’m struggling to figure this out myself. Can you just take care of it for me?", "Sure, I can help you understand it. But it’s important that you learn how to handle it by yourself this time.", "Can you just do it for me this once? I’m really swamped with other projects. You’re so good at this. I’ve seen you do it a hundred times.", "I appreciate your confidence in me, but it doesn’t make sense at all for me to keep making concessions. I’ve done all that I could possibly do to support, please understand I have my own priorities.", "Fine. I guess I’ll just have to figure it out myself.", "That’s the spirit, John. I’m happy to help whenever I can, but we also need to make sure that we are not overloading each other, and it’s important for you to take ownership of your own work.", "Yeah, I guess you’re right. Sorry for asking so much of you. We’ll ensure we are aligned on the division of responsibilities."], "dialogueZH": ["嘿，Steve，你有空吗？我自己搞不明白这个。你能帮我处理一下吗？", "当然，我可以帮你理解。但这次你自己学会处理很重要。", "你就这一次帮我做了吧？我现在真的被其他项目压得喘不过气。你做这个很在行，我看你做过上百次了。", "我很感谢你对我的信任，但让我一直不断让步并不合理。我已经尽我所能提供支持了，也请理解我也有自己的优先事项。", "好吧，那我只能自己想办法了。", "这就对了，John。我很乐意在我能帮的时候帮你，但我们也要确保彼此不会负担过重，而且你对自己的工作承担责任也很重要。", "嗯，你说得对。抱歉之前对你要求太多了。我们之后会确保在职责分工上保持一致。"], "vocabulary": [{"en": "struggle to figure out", "phonetic": "/ˈstrʌɡ.əl tə ˈfɪɡ.jər aʊt/", "pos": "v. phr.", "zh": "绞尽脑汁也想不明白", "source": "struggling to figure this out"}, {"en": "take care of", "phonetic": "/teɪk ker əv/", "pos": "v. phr.", "zh": "处理；负责", "source": "take care of it for me"}, {"en": "swamped", "phonetic": "/swɑːmpt/", "pos": "adj.", "zh": "忙得不可开交的", "source": "really swamped with other projects"}, {"en": "concessions", "phonetic": "/kənˈseʃ.ənz/", "pos": "n.", "zh": "让步", "source": "keep making concessions"}, {"en": "that's the spirit", "phonetic": "/ðæts ðə ˈspɪr.ɪt/", "pos": "phr.", "zh": "这就对了！就该这样", "source": "That's the spirit"}, {"en": "overload", "phonetic": "/ˌoʊ.vərˈloʊd/", "pos": "v.", "zh": "使超负荷；使负担过重", "source": "not overloading each other"}, {"en": "division of responsibilities", "phonetic": "/dɪˈvɪʒ.ən əv rɪˌspɑːn.səˈbɪl.ə.tiz/", "pos": "n. phr.", "zh": "职责分工", "source": "aligned on the division of responsibilities"}], "grammar": [{"title": "It doesn't make sense for me to...", "structure": "It doesn't make sense for me to + 动词原形", "example": "It doesn't make sense for me to keep making concessions.", "explanation": "比I can't/I won't更柔和但坚定，用逻辑而非情绪拒绝，体现职业成熟度。"}], "coreSentences": [{"original": "You got one second?", "function": "快速搭话", "alternative": "Got a minute? / Can I grab you for a sec?"}, {"original": "I'm really swamped with other projects.", "function": "表达忙不过来", "alternative": "I'm drowning in work right now. / I've got a lot on my plate."}, {"original": "It doesn't make sense for me to keep making concessions.", "function": "坚定拒绝", "alternative": "I can't keep doing this for you. / I've reached my limit on this."}, {"original": "That's the spirit!", "function": "鼓励对方", "alternative": "Now you're talking! / That's the attitude!"}, {"original": "We need to ensure we're aligned on the division of responsibilities.", "function": "明确分工", "alternative": "Let's clarify who does what. / We need to get on the same page about roles."}], "exercises": {"vocabChoice": [{"question": "\"swamped\" 的意思是？", "options": ["沼泽", "忙得不可开交", "轻松", "湿透"], "answer": 1}, {"question": "\"concession\" 表示？", "options": ["拒绝", "让步", "前进", "保守"], "answer": 1}], "fillBlank": [{"sentence": "That's the ______!", "answer": "spirit", "hint": "就该这样"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方职场中，学会说'no'是一项重要的职业能力。用'it doesn't make sense'而不是'I don't want to'来拒绝，把拒绝建立在逻辑而非情绪上，对方更容易接受。", "interviewTip": "", "difficulty": "🔴进阶"}, {"id": 54, "file": "54-怼同事不感恩", "title": "怼同事不感恩", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Hey John, can we talk this over? This is not the first time that it has happened, you always take my help for granted.", "What do you mean by that?", "We stayed up late last night to help you finish that project, but seriously, you didn’t show any gratitude or appreciation for our efforts. It would have been nice to at least get a thank you or acknowledgment from you.", "Sorry, I didn’t realize this. But I thought it was something that you had to do as a part of the team.", "It’s true we are one team, but still it’s important for us to have a mutual sense of respect in the workplace. After all, we’ve bent over backwards to save you from a major headache, and recognition or credit means a lot to me and our team.", "You’re right, Steve. Thanks for bringing this up to me. I will make sure to be more mindful of this from now on.", "No problem. I’m good for now. Have a good day."], "dialogueZH": ["嘿 John，我们能谈一下吗？这不是第一次发生了，你总是把我的帮助视为理所当然。", "你这是什么意思？", "昨晚我们熬夜帮你完成那个项目，但说真的，你对我们的努力没有表现出任何感谢或认可。至少说一句谢谢或者表示一下心意都会很好。", "抱歉，我之前没意识到。我以为这是你们作为团队成员本来就应该做的事。", "我们确实是一支团队，但在职场中保持彼此尊重同样重要。毕竟我们已经拼尽全力帮你避免一个大麻烦，而认可和肯定对我和团队来说都很重要。", "你说得对，Steve。谢谢你提出来。我之后会更加注意这件事。", "没问题。我这边暂时没事了，祝你今天过得愉快。"], "vocabulary": [{"en": "talk this over", "phonetic": "/tɔːk ðɪs ˈoʊ.vər/", "pos": "v. phr.", "zh": "好好谈谈", "source": "can we talk this over"}, {"en": "take for granted", "phonetic": "/teɪk fər ˈɡræn.tɪd/", "pos": "idiom", "zh": "视为理所当然", "source": "take my help for granted"}, {"en": "gratitude", "phonetic": "/ˈɡræt.ɪ.tuːd/", "pos": "n.", "zh": "感激之情", "source": "show any gratitude"}, {"en": "appreciation", "phonetic": "/əˌpriː.ʃiˈeɪ.ʃən/", "pos": "n.", "zh": "认可；感谢", "source": "appreciation for our efforts"}, {"en": "bend over backwards", "phonetic": "/bend ˈoʊ.vər ˈbæk.wərdz/", "pos": "idiom", "zh": "竭尽全力", "source": "bent over backwards to save you"}, {"en": "mutual respect", "phonetic": "/ˈmjuː.tʃu.əl rɪˈspekt/", "pos": "n. phr.", "zh": "相互尊重", "source": "mutual sense of respect"}, {"en": "mindful", "phonetic": "/ˈmaɪnd.fəl/", "pos": "adj.", "zh": "注意的；留心的", "source": "more mindful of this"}], "grammar": [{"title": "This is not the first time that...", "structure": "This is not the first time that + 现在完成时", "example": "This is not the first time that it has happened.", "explanation": "强调重复发生的问题，比you always更客观，用事实而非指责说话。"}], "coreSentences": [{"original": "Can we talk this over?", "function": "提出需要沟通", "alternative": "Can we have a word? / I'd like to discuss something with you."}, {"original": "You always take my help for granted.", "function": "指出问题", "alternative": "You never acknowledge my efforts. / It feels like you expect this, not appreciate it."}, {"original": "We've bent over backwards to help you.", "function": "强调付出", "alternative": "We went above and beyond for you. / We really pulled out all the stops."}, {"original": "I will make sure to be more mindful of this.", "function": "承诺改进", "alternative": "I'll pay more attention to this. / I'll be more conscious going forward."}], "exercises": {"vocabChoice": [{"question": "\"take for granted\" 表示？", "options": ["得到许可", "视为理所当然", "拿到补助", "接受"], "answer": 1}, {"question": "\"bend over backwards\" 是什么意思？", "options": ["向后弯腰", "竭尽全力", "拒绝帮忙", "轻松完成"], "answer": 1}], "fillBlank": [{"sentence": "It's important to have a ______ sense of respect in the workplace.", "answer": "mutual", "hint": "相互的"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方职场中，直接给出建设性反馈(constructive feedback)是正常的。关键是：1)用'I feel'而非'You always' 2)举具体例子 3)提供改进方向 4)以积极语气结束。", "interviewTip": "", "difficulty": "🔴进阶"}, {"id": 55, "file": "55-汇报工作卡点", "title": "汇报工作卡点", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["This project requires heavy involvement from ops team, but they are quite short-handed right now due to downsizing of last year. I’ve escalated this to the ops head, but still no one is available to support. When to recruit the staff is still up in the air, which I’m afraid will potentially affect the final delivery.", "I already heard of this, but no worries, let’s sort this out later on. Then what will be your next steps?"], "dialogueZH": ["这个项目需要运营团队大量参与，但他们现在因为去年的裁员而人手严重不足。我已经把情况上报给运营负责人了，但目前仍然没有人能来支持。何时招聘新员工还未确定，我担心这可能会影响最终交付。", "我已经听说这件事了，不过别担心，我们之后再一起解决。那么你接下来的计划是什么？"], "vocabulary": [{"en": "heavy involvement", "phonetic": "/ˈhev.i ɪnˈvɑːlv.mənt/", "pos": "n. phr.", "zh": "大量参与", "source": "requires heavy involvement"}, {"en": "short-handed", "phonetic": "/ʃɔːrt ˈhæn.dɪd/", "pos": "adj.", "zh": "人手不足的", "source": "quite short-handed right now"}, {"en": "downsizing", "phonetic": "/ˈdaʊn.saɪ.zɪŋ/", "pos": "n.", "zh": "裁员；缩减规模", "source": "due to downsizing of last year"}, {"en": "escalate", "phonetic": "/ˈes.kə.leɪt/", "pos": "v.", "zh": "升级上报", "source": "escalated this to the ops head"}, {"en": "approve headcount", "phonetic": "/əˈpruːv ˈhed.kaʊnt/", "pos": "v. phr.", "zh": "批准编制/人数", "source": "the hiring of new headcount hasn't been approved"}, {"en": "impact the final delivery", "phonetic": "/ˈɪm.pækt ðə ˈfaɪ.nəl dɪˈlɪv.ər.i/", "pos": "v. phr.", "zh": "影响最终交付", "source": "might impact the final delivery"}, {"en": "sort out", "phonetic": "/sɔːrt aʊt/", "pos": "v. phr.", "zh": "解决；处理", "source": "sort this out later"}], "grammar": [{"title": "I've escalated...but still no...", "structure": "I have + 过去分词 + but + 否定结果", "example": "I've escalated this to the ops head, but still no one is available.", "explanation": "展示你已采取了行动但问题仍未解决，这是汇报问题的标准结构——先说你做了什么，再说卡在哪里。"}], "coreSentences": [{"original": "This project requires heavy involvement from the ops team.", "function": "说明资源需求", "alternative": "We need significant ops support for this project."}, {"original": "They are quite short-handed due to downsizing.", "function": "解释客观原因", "alternative": "The team is understaffed after the recent cuts."}, {"original": "I've escalated this to the ops head.", "function": "说明已采取措施", "alternative": "I've raised this with leadership. / I've flagged this issue up."}, {"original": "This might impact the final delivery.", "function": "预警风险", "alternative": "There's a risk to the timeline. / Our delivery date could be affected."}], "exercises": {"vocabChoice": [{"question": "\"short-handed\" 表示？", "options": ["手短的", "人手不足的", "手受伤", "灵活的"], "answer": 1}, {"question": "\"downsizing\" 指什么？", "options": ["缩小尺寸", "裁员/缩减规模", "减少", "简化"], "answer": 1}], "fillBlank": [{"sentence": "I've ______ this issue to the department head.", "answer": "escalated", "hint": "升级上报"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方职场汇报问题时，先说你做了什么(ispeak first)，再问需要什么帮助。不要只抛问题不拿方案。'I've done X but Y is blocking me'是最佳格式。", "interviewTip": "", "difficulty": "🔵中级"}, {"id": 56, "file": "56-汇报工作进度", "title": "汇报工作进度", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["So Steve, how is the project progressing, any updates for this week?", "Yes, I’ve made some really good progress this week, completing two major tasks ahead of schedule. For starters, I’ve engaged with the business owner for the alignment of objectives, then I have completed the draft of project plan based on the communication.", "That’s great to hear, you’re always taking the initiative in your work, so things have been going quite smoothly, right?", "Not really, we did encounter one major roadblock."], "dialogueZH": ["Steve，这个项目目前进展如何？这周有什么更新吗？", "是的，这周我取得了非常不错的进展，提前完成了两个主要任务。首先，我已经和业务负责人沟通并对齐了项目目标，然后根据沟通内容完成了项目计划的初稿。", "太好了，你一向很主动，所以事情应该都挺顺利的，对吧？", "倒也不是，不过我们确实遇到了一项主要的阻碍 / 一个大难题。"], "vocabulary": [{"en": "progressing", "phonetic": "/prəˈɡres.ɪŋ/", "pos": "v.", "zh": "进展", "source": "how is the project progressing"}, {"en": "ahead of schedule", "phonetic": "/əˈhed əv ˈskedʒ.uːl/", "pos": "phr.", "zh": "提前于计划", "source": "completing tasks ahead of schedule"}, {"en": "for starters", "phonetic": "/fər ˈstɑːr.tərz/", "pos": "phr.", "zh": "首先；作为第一步", "source": "For starters, I've engaged..."}, {"en": "alignment of objectives", "phonetic": "/əˈlaɪn.mənt əv əbˈdʒek.tɪvz/", "pos": "n. phr.", "zh": "目标一致；目标对齐", "source": "alignment of objectives"}, {"en": "take the initiative", "phonetic": "/teɪk ðə ɪˈnɪʃ.ə.tɪv/", "pos": "v. phr.", "zh": "主动；率先行动", "source": "always taking the initiative"}, {"en": "roadblock", "phonetic": "/ˈroʊd.blɑːk/", "pos": "n.", "zh": "障碍；路障", "source": "one major roadblock"}], "grammar": [{"title": "Not really, we did encounter... (先扬后抑)", "structure": "肯定回答 + 转折 + 问题", "example": "That's great. Not really, we did encounter one major roadblock.", "explanation": "先肯定正面进展，再诚实提出遇到的障碍，是汇报工作中既展示成绩又及时求助的标准技巧。"}], "coreSentences": [{"original": "How is the project progressing? Any updates?", "function": "询问进度", "alternative": "Where are we at on this? / Any developments this week?"}, {"original": "I've made some really good progress, completing two major tasks ahead of schedule.", "function": "汇报成绩", "alternative": "Great progress — two key milestones done early."}, {"original": "You're always taking the initiative in your work.", "function": "表扬主动性", "alternative": "I appreciate your proactive approach. / You always stay ahead of things."}, {"original": "We did encounter one major roadblock.", "function": "诚实汇报障碍", "alternative": "There's been one significant hurdle. / We hit a snag, though."}], "exercises": {"vocabChoice": [{"question": "\"ahead of schedule\" 意思是？", "options": ["按计划", "提前于计划", "落后计划", "取消计划"], "answer": 1}, {"question": "\"roadblock\" 指什么？", "options": ["路标", "障碍/阻碍", "马路", "积木"], "answer": 1}], "fillBlank": [{"sentence": "We completed the task ______ of schedule.", "answer": "ahead", "hint": "提前"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方职场汇报推崇'亮点先行'——先说成绩(what went well)，再说问题(what didn't)。用ahead of schedule、good progress等正面词汇开头，建立积极基调。", "interviewTip": "", "difficulty": "🔵中级"}, {"id": 57, "file": "57-下一步工作安排", "title": "下一步工作安排", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Moving forward, I will finalize the project plan and submit it to the management for review by the end of next week. Meanwhile, I will invite stakeholders from XFN teams to kick off the project, as I found some miscommunication and information gap among different functions.", "Do you think this impacts the project a lot?", "I suppose not, it should be one minor issue, just some clarification should do. I will see to it, making sure everyone is on the same page.", "It’s good to see that you’re keeping the project on track. Keep up the good work and let me know if you need any assistance."], "dialogueZH": ["接下来，我会最终完善项目计划，并在下周末前提交给管理层审核。同时，我会邀请跨职能团队的相关干系人启动项目，因为我发现不同职能之间存在一些沟通不畅和信息差。", "你觉得这会对项目造成很大影响吗？", "我想不会，这应该只是个小问题，澄清一下就可以。我会处理好，确保所有人都保持一致理解。", "很高兴看到你让项目保持在正轨上。继续保持，有需要随时告诉我。"], "vocabulary": [{"en": "finalize", "phonetic": "/ˈfaɪ.nəl.aɪz/", "pos": "v.", "zh": "最终确定；定稿", "source": "finalize the project plan"}, {"en": "submit for review", "phonetic": "/səbˈmɪt fər rɪˈvjuː/", "pos": "v. phr.", "zh": "提交审核", "source": "submit it to the management for review"}, {"en": "XFN (cross-functional)", "phonetic": "/krɔːs ˈfʌŋk.ʃən.əl/", "pos": "adj. abbr.", "zh": "跨职能的", "source": "stakeholders from XFN teams"}, {"en": "on the same page", "phonetic": "/ɑːn ðə seɪm peɪdʒ/", "pos": "idiom", "zh": "共识一致", "source": "everyone is on the same page"}, {"en": "keep on track", "phonetic": "/kiːp ɑːn træk/", "pos": "v. phr.", "zh": "保持在正轨上", "source": "keeping the project on track"}, {"en": "keep up the good work", "phonetic": "/kiːp ʌp ðə ɡʊd wɜːrk/", "pos": "phr.", "zh": "继续保持好状态", "source": "Keep up the good work"}], "grammar": [{"title": "Moving forward, I will + V (未来计划)", "structure": "Moving forward, I will + 动词原形", "example": "Moving forward, I will finalize the project plan.", "explanation": "Moving forward = 接下来/今后，是汇报下一步工作最标准的过渡语，比Next更正式。"}], "coreSentences": [{"original": "Moving forward, I will finalize the project plan.", "function": "说明下一步", "alternative": "Next up, I'll lock down the plan. / My next step is to finalize."}, {"original": "I will submit it to management for review.", "function": "说明审批流程", "alternative": "I'll send it up for leadership approval."}, {"original": "I suppose it should be one minor issue.", "function": "评估风险大小", "alternative": "I think it's manageable. / It shouldn't be a major problem."}, {"original": "Keep up the good work and let me know if you need assistance.", "function": "鼓励+留门", "alternative": "Great job so far. My door's open if you need anything."}], "exercises": {"vocabChoice": [{"question": "\"finalize\" 的意思是？", "options": ["开始", "最终确定/定稿", "分析", "取消"], "answer": 1}, {"question": "\"XFN\" 指什么？", "options": ["外勤", "跨职能(cross-functional)", "外部", "新功能"], "answer": 1}], "fillBlank": [{"sentence": "Make sure everyone is on the same ______.", "answer": "page", "hint": "共识(习语)"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方职场中，每段汇报以'next steps'结尾是非常重要的习惯——告诉老板你接下来要做什么，让他们放心项目在推进中。Keep up the good work是最常用的鼓励语。", "interviewTip": "", "difficulty": "🔵中级"}, {"id": 58, "file": "58-请病假", "title": "请病假", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Hi boss, sorry for the sudden call. I’m afraid I’m feeling quite unwell today, and think I need to take a sick leave.", "What seems to be the issue?", "I feel I’m coming down with a bad flu. I have a headache, a sore throat, a runny nose and I’m feeling slightly feverish. I was hoping to take 2 days off to get over it.", "I’m sorry to hear that. How long do you think you will need to be off from work?", "I visited the doctor this morning who advised that I take a rest for two days, so I’m hoping to return to work on Thursday.", "Okay, remember to submit the leave application and also share the doctor’s note with HR for our records.", "Sure, I just applied for a 2‑day sick leave starting from tomorrow in our system, can you please spare one moment to approve it.", "Alright, I will process your leave request. Also please inform your team and make sure to delegate your work to someone while you’re away.", "Thank you for letting me know, I will be sure to do that.", "No worries, have some proper rest and get well soon."], "dialogueZH": ["老板您好，抱歉突然打电话。我今天感觉很不舒服，可能需要请个病假。", "哪里不舒服呢？", "我感觉自己得了重感冒。头疼、喉咙痛、流鼻涕，还有点发热。我希望能请两天假休息一下。", "很抱歉听到这个消息。你觉得需要休息多久才能回来上班？", "我今天早上去看了医生，医生建议我休息两天，所以我计划周四回到工作岗位。", "好的，记得提交请假申请，并把医生证明发给人力资源存档。", "好的，我已经在系统里申请了从明天开始的两天病假，能请你抽空审批一下吗。", "好的，我会处理你的请假申请。另外请通知你的团队，并确保把你的工作交接给别人。", "谢谢你告诉我，我会照办的。", "不客气，好好休息，早点康复。"], "vocabulary": [{"en": "sick leave", "phonetic": "/sɪk liːv/", "pos": "n.", "zh": "病假", "source": "take a sick leave"}, {"en": "come down with", "phonetic": "/kʌm daʊn wɪð/", "pos": "v. phr.", "zh": "染上(疾病)", "source": "coming down with a bad flu"}, {"en": "headache", "phonetic": "/ˈhed.eɪk/", "pos": "n.", "zh": "头痛", "source": "I have a headache"}, {"en": "sore throat", "phonetic": "/sɔːr θroʊt/", "pos": "n.", "zh": "喉咙痛", "source": "a sore throat"}, {"en": "runny nose", "phonetic": "/ˈrʌn.i noʊz/", "pos": "n.", "zh": "流鼻涕", "source": "a runny nose"}, {"en": "feverish", "phonetic": "/ˈfiː.vər.ɪʃ/", "pos": "adj.", "zh": "发烧的", "source": "feeling slightly feverish"}, {"en": "get over it", "phonetic": "/ɡet ˈoʊ.vər ɪt/", "pos": "v. phr.", "zh": "恢复；痊愈", "source": "take 2 days off to get over it"}, {"en": "advise", "phonetic": "/ədˈvaɪz/", "pos": "v.", "zh": "建议(医生用)", "source": "the doctor advised that I take a rest"}], "grammar": [{"title": "I'm afraid + 从句 (礼貌传达坏消息)", "structure": "I'm afraid + 从句", "example": "I'm afraid I'm feeling quite unwell today.", "explanation": "I'm afraid是最常用的委婉/表达遗憾的句型，请假、拒绝、传达坏消息时必备。"}], "coreSentences": [{"original": "I'm afraid I'm feeling quite unwell today.", "function": "请假开头", "alternative": "Unfortunately, I'm not feeling well. / I'm sorry, but I'm under the weather."}, {"original": "I think I need to take a sick leave.", "function": "正式请假", "alternative": "I need to take the day off. / I'll need to call in sick."}, {"original": "I feel I'm coming down with a bad flu.", "function": "描述症状", "alternative": "I think I caught the flu. / I'm showing flu-like symptoms."}, {"original": "The doctor advised that I take a rest for two days.", "function": "引用医生建议", "alternative": "The doctor recommended two days of rest. / Medical advice is to rest."}], "exercises": {"vocabChoice": [{"question": "\"come down with\" 表示？", "options": ["下去", "染上(疾病)", "下来", "打败"], "answer": 1}, {"question": "\"sick leave\" 指什么？", "options": ["离开", "病假", "请假出去", "生病离开"], "answer": 1}], "fillBlank": [{"sentence": "I'm afraid I'm ______ down with a bad cold.", "answer": "coming", "hint": "染上(与with搭配)"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方职场请病假通常不需要详细解释症状。简单说'not feeling well'或'need a sick day'即可。提供太多细节反而奇怪。医生建议(doctor's note)通常只有超过2-3天才需要。", "interviewTip": "", "difficulty": "🟢入门"}, {"id": 59, "file": "59-请年假", "title": "请年假", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Good morning, Sir. Can I take some annual leaves?", "Sure, what’s on your mind?", "I’ve been working around the clock last month closing that big deal, I’m glad it’s done now. Meanwhile, I have some annual leave balance which will expire at the end of the year, so I’m thinking about going on a short trip to unwind for a few days.", "Sounds reasonable, certainly it was a hard-won success. Can you please confirm how many days you have left?", "Ten days, till next Friday, plus the weekends.", "Well, just to let you know, you should ask half one month in advance, but it’s okay, you should have some time off to refresh yourself.", "Highly appreciate that. Please be assured I’ll keep an eye out for emails or calls periodically, and respond promptly if anything urgent comes up.", "Excellent. Take care and have a good time off."], "dialogueZH": ["早上好，主管。我想请几天年假。", "当然，可以说说你有什么安排吗。", "上个月我为了拿下那个大项目一直在连轴转，现在终于搞定了。同时我还有一些年假余额年底就要过期了，所以我想出去短途旅行放松几天。", "听起来很合理，那确实是来之不易的成果。你能确认一下你还剩多少天假吗？", "十天，到下周五，再加上周末。", "嗯，让你知道一下，你应该提前半个月申请，不过没关系，你确实应该休息一下放松放松。", "非常感谢。请放心，我会定期留意邮件或电话，如果有紧急情况我会及时回复。", "太好了。保重，祝你假期愉快。"], "vocabulary": [{"en": "annual leave", "phonetic": "/ˈæn.ju.əl liːv/", "pos": "n.", "zh": "年假", "source": "take some annual leaves"}, {"en": "around the clock", "phonetic": "/əˈraʊnd ðə klɑːk/", "pos": "idiom", "zh": "全天候；日夜不停", "source": "working around the clock"}, {"en": "close the deal", "phonetic": "/kloʊz ðə diːl/", "pos": "v. phr.", "zh": "完成交易", "source": "closing that big deal"}, {"en": "leave balance", "phonetic": "/liːv ˈbæl.əns/", "pos": "n.", "zh": "剩余假期", "source": "annual leave balance"}, {"en": "expire", "phonetic": "/ɪkˈspaɪər/", "pos": "v.", "zh": "到期；失效", "source": "will expire at the end of the year"}, {"en": "hard-won success", "phonetic": "/hɑːrd wʌn səkˈses/", "pos": "n. phr.", "zh": "来之不易的成功", "source": "a hard-won success"}], "grammar": [{"title": "I'm thinking about + V-ing (委婉提议)", "structure": "I'm thinking about + V-ing", "example": "I'm thinking about taking a week or so to recharge.", "explanation": "用I'm thinking about比I want to更委婉，适合对上级提出请示。"}], "coreSentences": [{"original": "Can I take some annual leaves?", "function": "请求年假", "alternative": "I'd like to request some annual leave. / Could I use my vacation days?"}, {"original": "I've been working around the clock last month.", "function": "说明休假理由(需要休息)", "alternative": "I've been putting in long hours. / It's been non-stop lately."}, {"original": "I have some leave balance which will expire.", "function": "说明客观原因", "alternative": "I still have unused vacation days. / My leave is about to expire."}, {"original": "Sounds reasonable.", "function": "批准/同意", "alternative": "That makes sense. / Fair enough."}], "exercises": {"vocabChoice": [{"question": "\"annual leave\" 是？", "options": ["年度放假", "年假", "每年离开", "年休"], "answer": 1}, {"question": "\"around the clock\" 表示？", "options": ["在钟旁边", "全天候/日夜不停", "按时", "绕圈"], "answer": 1}], "fillBlank": [{"sentence": "My leave ______ will expire at year end.", "answer": "balance", "hint": "余额"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方职场中，年假是权利(right)而非施舍(favor)。请假多用inform的语气而非ask permission。但礼貌的提前通知(通常提前2周以上)仍然是基本礼仪。", "interviewTip": "", "difficulty": "🟢入门"}, {"id": 60, "file": "60-提加薪", "title": "提加薪", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Good morning, Sir, thanks for taking the time to discuss my salary today.", "Yeah, just go ahead.", "Sure. First off, I have joined our team for 4 years till now. I really enjoy working here and highly appreciate your support during my stay here, and I have every intention of continuing growing my career here.", "Then, for the last 2 years, I have been extensively involved in company-wise initiatives, bringing in generous profits to the company. Despite the daunting challenges of last quarter, I’ve built a robust partnership with our clients and worked closely with them to maximize the profits. This is the satisfaction survey results, which speak for themselves.", "Finally, I looked at the market average for my title in the industry. Based on my competency, experience and contribution, I feel I deserve to get a pay rise of at least 15%. Does that sound fair to you?", "I see, but you know current economic downturn has impacted on the overall performance of our company, also I don’t want to start a brain drain. I’ll think it over and get back to you in 3 working days."], "dialogueZH": ["早上好，主管，感谢您抽时间和我讨论薪资。", "好的，请说吧。", "当然。首先，我加入团队到现在已经四年了。我非常喜欢在这里工作，也非常感激您这段时间对我的支持，而且我真心希望能继续在这里发展我的职业生涯。", "过去两年里，我深度参与了公司层面的各项项目，为公司带来了可观的利润。尽管上个季度面临巨大挑战，我仍然与客户建立了稳固的合作关系，并与他们紧密合作以最大化收益。这是满意度调查的结果，本身就说明了一切。", "最后，我也参考了行业内与我职位相当的市场平均薪资。基于我的能力、经验和贡献，我认为我至少应该获得 15% 的加薪。你觉得这样合理吗？", "我明白，不过你也知道当前的经济下行影响了公司的整体表现，而且我也不希望因此引发人才流失。我会仔细考虑，并在三个工作日内回复你。"], "vocabulary": [{"en": "take the time to", "phonetic": "/teɪk ðə taɪm tə/", "pos": "phr.", "zh": "抽出时间", "source": "thanks for taking the time"}, {"en": "have every intention of", "phonetic": "/hæv ˈev.ri ɪnˈten.ʃən əv/", "pos": "phr.", "zh": "完全有意向", "source": "have every intention of continuing"}, {"en": "generous profits", "phonetic": "/ˈdʒen.ər.əs ˈprɑːf.ɪts/", "pos": "n. phr.", "zh": "可观利润", "source": "bringing in generous profits"}, {"en": "daunting challenges", "phonetic": "/ˈdɔːn.tɪŋ ˈtʃæl.ɪndʒ.ɪz/", "pos": "n. phr.", "zh": "巨大的挑战", "source": "despite the daunting challenges"}, {"en": "robust pipeline", "phonetic": "/roʊˈbʌst ˈpaɪp.laɪn/", "pos": "n. phr.", "zh": "稳健的业务管线", "source": "built a robust pipeline"}, {"en": "market average", "phonetic": "/ˈmɑːr.kɪt ˈæv.ər.ɪdʒ/", "pos": "n.", "zh": "市场平均水平", "source": "the market average for my title"}, {"en": "pay rise", "phonetic": "/peɪ raɪz/", "pos": "n.", "zh": "加薪", "source": "get a pay rise of at least 15%"}, {"en": "Does that sound fair?", "phonetic": "/dʌz ðæt saʊnd fer/", "pos": "phr.", "zh": "这合理吗？", "source": "Does that sound fair to you?"}], "grammar": [{"title": "I feel I deserve + to V (自信陈述)", "structure": "I feel I deserve + to + 动词原形", "example": "Based on my contribution, I feel I deserve to get a pay rise.", "explanation": "deserve = 值得/应得。加薪谈判中最核心的动词。不要用I want（太弱），要用I deserve/I have earned（以事实为依据）。"}], "coreSentences": [{"original": "Thanks for taking the time to discuss my salary today.", "function": "加薪开场白", "alternative": "I appreciate you making time for this conversation."}, {"original": "I have every intention of continuing growing my career here.", "function": "表达忠诚", "alternative": "I'm committed to growing with this company."}, {"original": "I've been extensively involved in company-wide initiatives.", "function": "陈述贡献", "alternative": "I've contributed significantly to key company projects."}, {"original": "Based on my contribution, I feel I deserve a pay rise.", "function": "提出加薪请求", "alternative": "Given my track record, I believe a raise is warranted."}], "exercises": {"vocabChoice": [{"question": "\"daunting\" 的意思是？", "options": ["简单的", "巨大的/令人生畏的", "有趣的", "吓人的"], "answer": 1}, {"question": "\"pay rise\" 表示？", "options": ["涨工资/加薪", "加班费", "年终奖", "工资单"], "answer": 0}], "fillBlank": [{"sentence": "Based on my contribution, I feel I ______ a pay rise.", "answer": "deserve", "hint": "值得/应得"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方加薪谈判三步法：1)表达对公司的忠诚和感激 2)列事实(贡献、市场数据) 3)提出具体数字并询问对方意见。准备市场数据是关键——证明你值这个价，而不是你觉得你值。", "interviewTip": "", "difficulty": "🔴进阶"}, {"id": 61, "file": "61-内部转岗", "title": "内部转岗", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Hi, Steve, we haven’t done 1‑on‑1 for quite a while, is everything okay?", "Thanks for asking, but not really. I feel I have lost some motivation in work especially for the last couple of weeks.", "Can you be more specific?", "Sure, when I joined our company, I was very proactive and enterprising, but now seems I am losing interest in what I do here. So I want to bring this up to see if any changes can be made.", "Okay, I am also aware of this, so what's on your mind?", "Personally I was hoping to take on new responsibilities. While I am capable of finishing operational things behind the scenes, I've also found I am best suited to engaging with people, so I was wondering if it is possible for me to make an internal transfer.", "All right, I see your point, but let me talk with people manager to see if there are any other new roles suitable for you.", "Really! I highly appreciate it, boss. If possible, I'm really happy to start out with anything, even with very basics.", "No worries, it's only my job to make my team members feel fulfilled, after all it's related to your career growth. I will get back to you after speaking with people manager."], "dialogueZH": ["嗨，Steve，我们已经很久没有做 1 对 1 了，一切都还好吗？", "谢谢你的关心，但其实不太好。我感觉自己最近几周在工作上有些失去动力。", "你能具体说说吗？", "当然。刚加入公司的时候，我非常主动、有进取心，但现在似乎对自己的工作逐渐失去兴趣。所以我想提出来看看是否能做出一些改变。", "好的，我也知道这一点，那么你有什么想法？", "就我个人而言，我希望能承担新的职责。虽然我有能力在幕后完成运营方面的工作，但我也发现我最适合与人打交道，所以我想知道我是否有可能进行内部调动。", "好吧，我明白你的意思，但让我和人事经理谈谈，看看有没有其他适合你的新职位。", "真的吗！我非常感激，老板。如果可能的话，我很乐意从任何事情做起，哪怕是基础的工作。", "别担心，让团队成员感到充实本来就是我的工作，毕竟这关系到你的职业发展。我和人事经理谈完后会再联系你。"], "vocabulary": [{"en": "1-on-1", "phonetic": "/wʌn ɑːn wʌn/", "pos": "n.", "zh": "一对一会议", "source": "we haven't done 1-on-1 for quite a while"}, {"en": "lost motivation", "phonetic": "/lɔːst ˌmoʊ.tɪˈveɪ.ʃən/", "pos": "v. phr.", "zh": "失去动力", "source": "lost some motivation in work"}, {"en": "proactive", "phonetic": "/proʊˈæk.tɪv/", "pos": "adj.", "zh": "积极主动的", "source": "very proactive and enterprising"}, {"en": "enterprising", "phonetic": "/ˈen.tər.praɪ.zɪŋ/", "pos": "adj.", "zh": "有进取心的", "source": "proactive and enterprising"}, {"en": "bring this up", "phonetic": "/brɪŋ ðɪs ʌp/", "pos": "v. phr.", "zh": "提出这件事", "source": "want to bring this up"}, {"en": "lose interest", "phonetic": "/luːz ˈɪn.trəst/", "pos": "v. phr.", "zh": "失去兴趣", "source": "losing interest in what I do"}], "grammar": [{"title": "Not really (否定回答+解释)", "structure": "肯定问句？Not really, + 解释", "example": "Is everything okay? Not really, I feel I have lost some motivation.", "explanation": "Not really是委婉的否定回答，比No婉转。在1-on-1中向老板表达不满时的高级表达方式。"}], "coreSentences": [{"original": "We haven't done 1-on-1 for quite a while.", "function": "开启面谈", "alternative": "It's been a while since our last catch-up."}, {"original": "I feel I have lost some motivation in work.", "function": "表达职业倦怠", "alternative": "I've been feeling a bit disengaged lately."}, {"original": "I want to bring this up to see if any changes can be made.", "function": "提议改变", "alternative": "I'd like to explore ways to shake things up."}, {"original": "Can you be more specific?", "function": "请求细化", "alternative": "Tell me more. / What exactly do you mean?"}], "exercises": {"vocabChoice": [{"question": "\"1-on-1\" 是什么？", "options": ["比赛", "一对一会议", "单挑", "单打"], "answer": 1}, {"question": "\"bring this up\" 表示？", "options": ["拿上来", "提出/提及这件事", "抚养", "上升"], "answer": 1}], "fillBlank": [{"sentence": "I've lost some ______ in work lately.", "answer": "motivation", "hint": "动力/积极性"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方职场中，1-on-1是管理者和下属最重要的沟通渠道。'lost motivation'不是坏事——诚实地谈论它是成熟的标志。好老板会帮你找到重新激发动力的方法，而非批评。", "interviewTip": "", "difficulty": "🔴进阶"}, {"id": 62, "file": "62-抱怨工作量大", "title": "抱怨工作量大", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Steve. I'm wondering if you could support the our top-priority project as well. You know our team has been under-resourced and short-staffed. So if you would like to join I'm certain you will be tremendously helpful.", "Sure, I'd love to be part of this, and it's indeed a great opportunity to gain some experience. but the thing is I've got too much on my plate, and almost burnt out from my current workload, so I'm afraid it's pretty difficult for me to take on extra work.", "Okay, I see. Let's see whether there is a way you join this project without making you feel overstretched.", "How about we having a 1-on-1 meeting to run through my priorities at hand, so you can either help re-prioritize my tasks or just take something off my plate.", "Okay, that would be great. Let's see how to move things around."], "dialogueZH": ["史蒂夫。我想知道你是否也能支持一下我们的最高优先级项目。你知道我们的团队一直人手不足且资源匮乏。所以如果你愿意加入，我确信你会非常有帮助。", "当然，我很乐意参与其中，这确实是一个获得一些经验的好机会。但问题是，我手头上的事情太多了，而且因为目前的工作量几乎已经筋疲力尽了，所以我恐怕很难再承担额外的工作。", "好的，我明白了。让我们看看有没有办法让你加入这个项目，同时又不会让你感到压力过大。", "我们开个一对一的会议，梳理一下我手头的优先事项，这样你可以帮我重新安排任务的优先级，或者直接帮我分担一些工作。", "好的，那太好了。让我们看看怎么调整一下。"], "vocabulary": [{"en": "top-priority", "phonetic": "/tɑːp praɪˈɔːr.ə.ti/", "pos": "adj.", "zh": "最高优先级的", "source": "our top-priority project"}, {"en": "under-resourced", "phonetic": "/ˌʌn.dər rɪˈsɔːrst/", "pos": "adj.", "zh": "资源不足的", "source": "our team has been under-resourced"}, {"en": "short-staffed", "phonetic": "/ʃɔːrt stæft/", "pos": "adj.", "zh": "人手不足的", "source": "short-staffed"}, {"en": "burnt out", "phonetic": "/bɜːrnt aʊt/", "pos": "adj. phr.", "zh": "筋疲力尽的；倦怠的", "source": "almost burnt out from my current workload"}, {"en": "overstretched", "phonetic": "/ˌoʊ.vərˈstretʃt/", "pos": "adj.", "zh": "负担过重的", "source": "without making you feel overstretched"}, {"en": "re-prioritize", "phonetic": "/riː praɪˈɔːr.ɪ.taɪz/", "pos": "v.", "zh": "重新排优先级", "source": "help re-prioritize my tasks"}, {"en": "take off my plate", "phonetic": "/teɪk ɔːf maɪ pleɪt/", "pos": "phr.", "zh": "减轻负担", "source": "take something off my plate"}], "grammar": [{"title": "I'd love to be part of this, but...", "structure": "I'd love to + V + but + 原因", "example": "I'd love to be part of this, but the thing is I've got too much on my plate.", "explanation": "先表达兴趣，再说困难。'the thing is'是口语中常用的过渡，引导真实原因。"}], "coreSentences": [{"original": "Our team has been under-resourced and short-staffed.", "function": "说明资源紧张", "alternative": "We're stretched thin right now. / The team is running on empty."}, {"original": "I'm almost burnt out from my current workload.", "function": "表达过劳", "alternative": "I'm close to burnout. / My workload is unsustainable."}, {"original": "Could you help re-prioritize my tasks or take something off my plate?", "function": "请求帮助", "alternative": "Can we adjust my priorities? / Could something be delegated?"}, {"original": "Let's see how to move things around.", "function": "同意调整", "alternative": "Let's figure out a way to balance things. / We'll reshuffle priorities."}], "exercises": {"vocabChoice": [{"question": "\"burnt out\" 表示？", "options": ["烧毁", "筋疲力尽/倦怠", "被开除", "燃烧"], "answer": 1}, {"question": "\"take off my plate\" 意思是？", "options": ["从盘子里拿走", "减轻负担/分走工作", "上菜", "撤盘子"], "answer": 1}], "fillBlank": [{"sentence": "I'm almost burnt ______ from my current workload.", "answer": "out", "hint": "精疲力尽(固定搭配)"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方职场越来越重视'burnout'问题。公开说'I'm burnt out'不再是禁忌——反而被视为需要立即关注的信号。好的管理者会主动帮员工re-prioritize而非逼他们硬撑。", "interviewTip": "", "difficulty": "🔵中级"}, {"id": 63, "file": "63-抱怨不尽责", "title": "抱怨不尽责", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Hi boss, can I have a word with you please? I just want to talk to you quickly about our new customer service specialist.", "Sure, what's up?", "In a nutshell, I've got a few concerns about him, and I don't think he's a right fit for our company.", "Okay, what made you say that? I thought you were pleased with his overall performance.", "Yeah, his attitude is great, but he's a bit unreliable. Take last Tuesday for instance, it was the 2nd time he stood us up for clients' meeting. Also he really doesn't have the basic work ethic, I'm constantly catching him on Weibo when he should be talking to clients. Speaking personally, he isn't pulling his weight at all and has made mistakes that impacts our business.", "Okay, I will look into this straight away and see if I can sort this out, thanks for bringing this to my attention."], "dialogueZH": ["嗨，老板，我能和你谈谈吗？我想快速跟你聊聊我们新来的客户服务专员。", "当然，怎么了？", "简而言之，我对他有一些顾虑，我觉得他不太适合我们公司。", "好吧，是什么让你这么说的？我以为你对他的整体表现挺满意的。", "是的，他的态度很好，但他有点不可靠。拿上周二为例，那是他第二次在客户会议中放我们鸽子。而且他真的缺乏基本的职业道德，我经常发现他在应该和客户沟通的时候刷微博。就我个人而言，他根本没有尽到自己的职责，而且犯了一些影响我们业务的错误。", "好的，我会立刻着手调查这件事，看看能不能解决，谢谢你把这个情况告诉我。"], "vocabulary": [{"en": "have a word with", "phonetic": "/hæv ə wɜːrd wɪð/", "pos": "phr.", "zh": "和...谈谈", "source": "can I have a word with you"}, {"en": "in a nutshell", "phonetic": "/ɪn ə ˈnʌt.ʃel/", "pos": "phr.", "zh": "简而言之", "source": "In a nutshell"}, {"en": "concerns about", "phonetic": "/kənˈsɜːrnz əˌbaʊt/", "pos": "n. phr.", "zh": "对...的担忧", "source": "concerns about him"}, {"en": "right fit", "phonetic": "/raɪt fɪt/", "pos": "n. phr.", "zh": "合适的人选", "source": "a right fit for our company"}, {"en": "unreliable", "phonetic": "/ˌʌn.rɪˈlaɪ.ə.bəl/", "pos": "adj.", "zh": "不可靠的", "source": "a bit unreliable"}, {"en": "stood us up", "phonetic": "/stʊd ʌs ʌp/", "pos": "v. phr.", "zh": "放我们鸽子", "source": "he stood us up"}, {"en": "work ethic", "phonetic": "/wɜːrk ˈeθ.ɪk/", "pos": "n.", "zh": "职业操守；工作态度", "source": "doesn't have the basic work ethic"}], "grammar": [{"title": "In a nutshell (概括)", "structure": "In a nutshell, + 总结句", "example": "In a nutshell, I've got a few concerns about him.", "explanation": "In a nutshell = 简而言之/一句话概括。用于引出核心观点，是职场沟通中最常用的开场白之一。"}], "coreSentences": [{"original": "Can I have a word with you please?", "function": "请求私下谈话", "alternative": "Got a moment to talk? / Can we chat briefly?"}, {"original": "In a nutshell, I've got a few concerns about him.", "function": "概括担忧", "alternative": "Long story short, there are some issues. / To put it simply, I'm worried about X."}, {"original": "I don't think he's a right fit for our company.", "function": "表达不适合", "alternative": "I'm not sure he's the best match. / He may not be suited for this role."}, {"original": "He stood us up for the clients' meeting.", "function": "举例(缺席)", "alternative": "He was a no-show for the client meeting. / He missed the meeting without notice."}], "exercises": {"vocabChoice": [{"question": "\"in a nutshell\" 表示？", "options": ["在坚果里", "简而言之/一句话概括", "详细说明", "小声说"], "answer": 1}, {"question": "\"stood us up\" 意思是？", "options": ["站起来", "放鸽子/爽约", "站立", "支持我们"], "answer": 1}], "fillBlank": [{"sentence": "I need to have a ______ with you about Peter.", "answer": "word", "hint": "谈谈(短语)"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "向老板投诉同事时，用具体例子(如'twice he stood us up')而非笼统评价('he's bad')。先说对方优点(attitude is great)，再说问题，显示你客观公正。", "interviewTip": "", "difficulty": "🔴进阶"}, {"id": 64, "file": "64-抱怨不分主次", "title": "抱怨不分主次", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["So Steve, what's the matter?", "Just one thing about Peter. I personally adore him and don't hold anything personal against him, he is responsible and has a great eye for details. But sometimes he got caught up in trivial things at the expense of team objectives.", "For example, the evening before our 11/11 campaign, all of us need to stand by to cope with any possible online issues and keep the system stable, but he just spent the time on other irrelevant matters. The campaign was the company-wise initiative which required all parties' efforts.", "It would have been better to get a helping hand from him. I think he needs to get his priorities straight in certain circumstances, could you please raise this up with him?"], "dialogueZH": ["那么，史蒂夫，怎么了？", "关于彼得只有一件事。我个人很喜欢他，对他没有任何个人偏见，他很有责任感，而且对细节有很好的把控力。但有时候他会陷入琐碎的事情中，从而牺牲了团队的目标。", "例如，在我们双11活动的前一天晚上，我们所有人都需要待命，以应对任何可能的在线问题并保持系统稳定，但他却把时间花在了其他无关紧要的事情上。这次活动是全公司的举措，需要各方的努力。", "如果能得到他的帮助就好了。我认为他在某些情况下需要理清优先级，你能和他谈谈这个问题吗？"], "vocabulary": [{"en": "adore", "phonetic": "/əˈdɔːr/", "pos": "v.", "zh": "欣赏；喜欢", "source": "personally adore him"}, {"en": "hold against", "phonetic": "/hoʊld əˈɡenst/", "pos": "v. phr.", "zh": "对...有意见", "source": "don't hold anything personal against him"}, {"en": "great eye for details", "phonetic": "/ɡreɪt aɪ fər ˈdiː.teɪlz/", "pos": "phr.", "zh": "注重细节", "source": "has a great eye for details"}, {"en": "caught up in", "phonetic": "/kɔːt ʌp ɪn/", "pos": "v. phr.", "zh": "陷入；忙于", "source": "got caught up in trivial things"}, {"en": "trivial", "phonetic": "/ˈtrɪv.i.əl/", "pos": "adj.", "zh": "琐碎的；不重要的", "source": "trivial things at the cost of big pictures"}, {"en": "campaign", "phonetic": "/kæmˈpeɪn/", "pos": "n.", "zh": "营销活动", "source": "our 11/11 campaign"}, {"en": "get priorities straight", "phonetic": "/ɡet praɪˈɔːr.ə.tiz streɪt/", "pos": "phr.", "zh": "分清主次", "source": "get his priorities straight"}], "grammar": [{"title": "It would have been better to + V (虚拟语气表遗憾)", "structure": "It would have been better to + 动词原形", "example": "It would have been better to get a helping hand from him.", "explanation": "Would have been better = 本来可以更好。不直接指责，而是说'如果...就更好了'，比批评更委婉、更高级。"}], "coreSentences": [{"original": "I personally adore him and don't hold anything against him.", "function": "先肯定再批评", "alternative": "I like him personally. / Nothing personal against him, but..."}, {"original": "He gets caught up in trivial things at the cost of big pictures.", "function": "描述问题", "alternative": "He focuses on small details and misses the big picture."}, {"original": "He needs to get his priorities straight.", "function": "提出建议", "alternative": "He should learn to prioritize better. / He needs better time management."}], "exercises": {"vocabChoice": [{"question": "\"trivial\" 的意思是？", "options": ["重要的", "琐碎的/不重要的", "巨大的", "有趣的"], "answer": 1}, {"question": "\"get priorities straight\" 表示？", "options": ["排队", "分清主次/厘清轻重缓急", "整理", "搞直线"], "answer": 1}], "fillBlank": [{"sentence": "He needs to get his ______ straight.", "answer": "priorities", "hint": "优先级"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "给同事负面反馈时，'positive-negative-positive'三明治法是经典技巧。先真心夸赞(responsible, good eye for details)，再指出问题(priorities)，最后给建设性建议。", "interviewTip": "", "difficulty": "🔴进阶"}, {"id": 65, "file": "65-空降领导", "title": "空降领导", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Good morning, sir, thanks for taking the time to have a quick chat.", "Hi, Steve. Thanks for setting this up.", "Right, how are you finding things since you joined?", "So far so good, just tried my best to fit in here. and you? tell me a bit about yourself.", "Okay, I have joined here for 3 years and currently in charge of general management. Prior to this, I was in Lenovo Group, taking on similar work in the sales BU. Also I read you joined here from ByteDance, which experience I admire the most, we're all excited to have you on board!", "Thanks, but honestly I still have too much to catch up.", "If you need any assistance from me, even if to show you around or meet some people, please do let me know.", "Sure, thanks.", "Also I was wondering if we need to set up a regular communication, so I could provide updates on my projects and seek direction or advice from your end.", "Sounds great, let's do that."], "dialogueZH": ["早上好，先生，谢谢您抽出时间跟我简单聊聊。", "嗨，史蒂夫。谢谢你安排这次谈话。", "好的，自从你加入以来，感觉怎么样？", "目前为止还不错，我一直在尽力适应这里。你呢？给我介绍一下你自己吧。", "好的，我在这里已经工作了3年，目前负责综合管理。在此之前，我在联想集团工作，在销售业务部门从事类似的工作。另外我看到你是从字节跳动加入这里的，这段经历我非常欣赏，我们都很高兴能有你加入！", "谢谢，但老实说，我还有很多东西要学习。", "如果你需要我提供任何帮助，哪怕是带你四处转转或认识一些人，请随时告诉我。", "好的，谢谢。", "另外我想知道我们是否需要建立定期的沟通机制，这样我可以向你汇报我的项目进展，并向你寻求指导或建议。", "听起来不错，就这么办吧。"], "vocabulary": [{"en": "set this up", "phonetic": "/set ðɪs ʌp/", "pos": "v. phr.", "zh": "安排这次见面；发起", "source": "Thanks for setting this up"}, {"en": "find things", "phonetic": "/faɪnd θɪŋz/", "pos": "phr.", "zh": "感受；适应", "source": "how are you finding things since you joined"}, {"en": "so far so good", "phonetic": "/soʊ fɑːr soʊ ɡʊd/", "pos": "phr.", "zh": "目前一切顺利", "source": "So far so good"}, {"en": "fit in", "phonetic": "/fɪt ɪn/", "pos": "v. phr.", "zh": "融入", "source": "tried my best to fit in here"}, {"en": "in charge of", "phonetic": "/ɪn tʃɑːrdʒ əv/", "pos": "phr.", "zh": "负责", "source": "currently in charge of general management"}, {"en": "BU (Business Unit)", "phonetic": "/biː juː/", "pos": "n. abbr.", "zh": "事业部", "source": "in the sales BU"}, {"en": "break the ice", "phonetic": "/breɪk ðə aɪs/", "pos": "idiom", "zh": "打破沉默；活跃气氛", "source": "break the ice"}, {"en": "look forward to", "phonetic": "/lʊk ˈfɔːr.wərd tə/", "pos": "v. phr.", "zh": "期待", "source": "looking forward to working with you"}], "grammar": [{"title": "How are you finding...? (感受询问)", "structure": "How are you finding + 名词/动名词?", "example": "How are you finding things since you joined?", "explanation": "How are you finding = 你觉得...怎么样？是比 How do you feel about 更地道的英式表达，适合1-on-1中询问新人的适应情况。"}], "coreSentences": [{"original": "How are you finding things since you joined?", "function": "问新人感受", "alternative": "How are you settling in? / What's your first impression?"}, {"original": "So far so good, just tried my best to fit in.", "function": "回应适应情况", "alternative": "Pretty good so far. / Still adjusting, but going well."}, {"original": "Prior to this, I was in Lenovo Group.", "function": "介绍上一段经历", "alternative": "Before this role, I worked at... / My previous position was at..."}, {"original": "I'm looking forward to working with you.", "function": "表达合作期待", "alternative": "Excited to collaborate with you. / Can't wait to work together."}], "exercises": {"vocabChoice": [{"question": "\"so far so good\" 表示？", "options": ["很远很好", "目前为止一切顺利", "一点都不好", "又快又好"], "answer": 1}, {"question": "\"fit in\" 什么意思？", "options": ["适应/融入", "健身", "安装", "进来"], "answer": 0}], "fillBlank": [{"sentence": "______ to this, I worked at Lenovo for 3 years.", "answer": "Prior", "hint": "在...之前"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "与新领导(尤其是空降的)建立关系时，主动安排1-on-1展示你的主动性和职业素养。'break the ice'的小技巧：聊对方的背景、聊聊共同话题，不只是工作。", "interviewTip": "", "difficulty": "🔴进阶"}, {"id": 66, "file": "66-绩效沟通1", "title": "绩效沟通1", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Okay, I have joined here for 3 years and currently in charge of general management. Prior to this, I was in Lenovo Group, taking on similar work in the sales BU. Also I read you joined here from ByteDance, which experience I admire the most, we're all excited to have you on board!", "Thanks, but honestly I still have too much to catch up.", "If you need any assistance from me, even if to show you around or meet some people, please do let me know.", "Sure, thanks.", "Also I was wondering if we need to set up a regular communication, so I could provide updates on my projects and seek direction or advice from your end.", "Sounds great, let's do that.", "yes, go ahead please. I also want to get a clearer picture of myself.", "Sure thing, from your peer review by partnering teams, I found similar feedback on your room for improvement, showing that your way to communicate sometimes is a bit too aggressive. I need to remind you of that.", "well, that's fair and constructive criticism. I will note that, thanks for pointing this out."], "dialogueZH": ["好的，我在这里已经工作了3年，目前负责综合管理。在此之前，我在联想集团工作，在销售业务部门从事类似的工作。另外我看到你是从字节跳动加入这里的，这段经历我非常欣赏，我们都很高兴能有你加入！", "谢谢，但老实说，我还有很多东西要学习。", "如果你需要我提供任何帮助，哪怕是带你四处转转或认识一些人，请随时告诉我。", "好的，谢谢。", "另外我想知道我们是否需要建立定期的沟通机制，这样我可以向你汇报我的项目进展，并向你寻求指导或建议。", "听起来不错，就这么办吧。", "是的，请继续说。我也想更清楚地了解自己。", "当然，从合作团队对你的同行评审中，我发现关于你改进空间的反馈是类似的，指出你有时的沟通方式有点过于咄咄逼人。我需要提醒你这一点。", "嗯，这是公平且具有建设性的批评。我会记下这一点，谢谢你指出来。"], "vocabulary": [{"en": "in charge of", "phonetic": "/ɪn tʃɑːrdʒ əv/", "pos": "phr.", "zh": "负责", "source": "in charge of general management"}, {"en": "catch up", "phonetic": "/kætʃ ʌp/", "pos": "v. phr.", "zh": "追赶进度；补上", "source": "too much to catch up"}, {"en": "show around", "phonetic": "/ʃoʊ əˈraʊnd/", "pos": "v. phr.", "zh": "带...四处看看", "source": "show you around"}, {"en": "struggling with", "phonetic": "/ˈstrʌɡ.lɪŋ wɪð/", "pos": "v. phr.", "zh": "在...方面挣扎", "source": "struggling with the expectations"}, {"en": "constructive feedback", "phonetic": "/kənˈstrʌk.tɪv ˈfiːd.bæk/", "pos": "n. phr.", "zh": "建设性反馈", "source": "some constructive feedback"}, {"en": "turn things around", "phonetic": "/tɜːrn θɪŋz əˈraʊnd/", "pos": "v. phr.", "zh": "扭转局面", "source": "turn things around"}, {"en": "performance improvement plan", "phonetic": "/pərˈfɔːr.məns ɪmˈpruːv.mənt plæn/", "pos": "n. phr.", "zh": "绩效改进计划", "source": "performance improvement plan"}], "grammar": [{"title": "I wasn't particularly happy with... (委婉批评)", "structure": "I wasn't particularly happy with + 名词/动名词", "example": "I wasn't particularly happy with your way of interacting.", "explanation": "not particularly happy = 不太满意。比 I'm angry/disappointed 更克制、更职业。用过去时wasn't暗示过去的特定行为。"}], "coreSentences": [{"original": "Let me just get straight to the point.", "function": "直接切入正题", "alternative": "I'll cut to the chase. / Let me be direct."}, {"original": "I wasn't particularly happy with your way of interacting.", "function": "委婉批评", "alternative": "I had some concerns about how you interacted. / Your communication style could use adjustment."}, {"original": "I was just trying to correct the wrong views.", "function": "辩解", "alternative": "I was only trying to set things right. / My intention was to clarify."}, {"original": "Let's see how we can turn things around.", "function": "给出改进方向", "alternative": "Let's work on improving this. / Here's how we can fix this."}], "exercises": {"vocabChoice": [{"question": "\"constructive feedback\" 的意思是？", "options": ["建设性反馈", "破坏性批评", "正面表扬", "中立评论"], "answer": 0}, {"question": "\"turn things around\" 表示？", "options": ["转身", "扭转局面/改善状况", "翻过来", "调头"], "answer": 1}], "fillBlank": [{"sentence": "Let me get straight to the ______.", "answer": "point", "hint": "要点/正题"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方绩效沟通的核心是'constructive feedback'——既指出问题，又提供改进路径。PIP(Performance Improvement Plan)是正式的改进计划，通常持续30-90天。", "interviewTip": "", "difficulty": "🔵中级"}, {"id": 67, "file": "67-纠正下属", "title": "纠正下属", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["John. Can I have a word with you, please?", "Sure.", "All right, let me just get straight to the point. I wasn't particularly happy with your way of interacting with other teammates. You were being rather argumentative and always talking over others during meetings. I must remind you that wasn't too nice to be aggressive in workplaces.", "Well, I think I was just trying correct the wrong views.", "Okay. I appreciate your passion about work, but it's also important to hear out others' perspectives respectfully before rebutting. We need to pool the wisdom from the entire team, your behavior really brings down team morale.", "But I don't see what the issue is, I'm still doing my job properly, aren't I?", "Look, I expect more from you, at least you need to be more receptive to others' ideas. If I don't see your serious improvements in the next one month, I'm afraid I have to let you go, this is the final warning."], "dialogueZH": ["约翰。我能跟你谈两句吗？", "当然。", "好吧，那我就直说了。我对你的团队互动方式不太满意。你在会议中总是好争辩，而且经常打断别人说话。我必须提醒你，在工作场所表现得咄咄逼人是不太合适的。", "嗯，我觉得我只是想纠正那些错误的观点。", "好吧。我欣赏你对工作的热情，但在反驳之前，尊重地倾听他人的观点也很重要。我们需要汇集整个团队的智慧，你的行为确实会打击团队士气。", "但我看不出有什么问题，我还在正常工作，不是吗？", "听着，我对你的期望更高。至少你需要更乐于接受别人的想法。如果我在接下来的一个月里看不到你认真的改进，恐怕我不得不让你离开，这是最后的警告。"], "vocabulary": [{"en": "get straight to the point", "phonetic": "/ɡet streɪt tə ðə pɔɪnt/", "pos": "idiom", "zh": "直入正题", "source": "let me get straight to the point"}, {"en": "argumentative", "phonetic": "/ˌɑːr.ɡjəˈmen.tə.tɪv/", "pos": "adj.", "zh": "爱争辩的；好争论的", "source": "rather argumentative"}, {"en": "talk down to", "phonetic": "/tɔːk daʊn tə/", "pos": "v. phr.", "zh": "以居高临下的态度说话", "source": "always talking down to them"}, {"en": "professionalism", "phonetic": "/prəˈfeʃ.ən.əl.ɪz.əm/", "pos": "n.", "zh": "专业素养", "source": "maintained professionalism"}, {"en": "tone of voice", "phonetic": "/toʊn əv vɔɪs/", "pos": "n. phr.", "zh": "说话语气", "source": "your tone of voice"}, {"en": "constructive", "phonetic": "/kənˈstrʌk.tɪv/", "pos": "adj.", "zh": "建设性的", "source": "a more constructive way"}, {"en": "take this on board", "phonetic": "/teɪk ðɪs ɑːn bɔːrd/", "pos": "v. phr.", "zh": "接受并考虑", "source": "hope you can take this on board"}], "grammar": [{"title": "If you could + V (委婉请求)", "structure": "If you could + 动词原形, 效果", "example": "If you could just be more patient, we could avoid these issues.", "explanation": "用if条件句比直接命令(be more patient)礼貌得多。是纠正下属行为的标准句型。"}], "coreSentences": [{"original": "Can I have a word with you, please?", "function": "约谈开头", "alternative": "Could I speak with you privately? / Do you have a moment?"}, {"original": "You were being rather argumentative.", "function": "指出具体问题行为", "alternative": "You came across as combative. / Your tone was confrontational."}, {"original": "We need to maintain professionalism at all times.", "function": "重申标准", "alternative": "Let's keep things professional. / Professional conduct is expected."}, {"original": "I hope you can take this on board.", "function": "期望对方接受", "alternative": "I hope this resonates with you. / Please take this feedback seriously."}], "exercises": {"vocabChoice": [{"question": "\"argumentative\" 的意思是？", "options": ["有道理的", "爱争辩的/好争论的", "安静的", "辩论的"], "answer": 1}, {"question": "\"take this on board\" 表示？", "options": ["放上船", "接受并考虑(建议)", "上火车", "忽略"], "answer": 1}], "fillBlank": [{"sentence": "Let me get straight to the ______.", "answer": "point", "hint": "要点"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方管理者纠正下属时，聚焦行为(behavior)而非人格(personality)。不说you are rude，说your tone felt dismissive——前者攻击人格，后者描述感受。", "interviewTip": "", "difficulty": "🔴进阶"}, {"id": 68, "file": "68-询问意向", "title": "询问意向", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Hi, Steve. I'm John from the product team. I learn the project team is doing market research in Japan market, which our product team is also engaged in. I was just wondering if both teams could sync up a bit, just in case either side reinvents the wheel. Also both ends could leverage each other's strengths to make things easier. What do you think?", "Sounds fantastic. Let's find a common slot this afternoon for a catch-up. I'll invite parties from my end, could you please help engage with your team as well?", "No problem, I'm available all this afternoon, let me also check others' availabilities."], "dialogueZH": ["嗨，史蒂夫。我是产品团队的约翰。我听说项目团队正在日本市场做市场调研，我们产品团队也正在做这个。我想知道两个团队是否可以同步一下信息，以免双方重复造轮子。另外，双方也可以利用彼此的优势让事情变得更简单。你觉得怎么样？", "听起来很棒。那我们今天下午找个共同的时间碰个头吧。我会邀请我这边的人，你能帮忙协调一下你们团队吗？", "没问题，我今天下午都有空，我也去确认一下其他人的时间。"], "vocabulary": [{"en": "market research", "phonetic": "/ˈmɑːr.kɪt ˈriː.sɜːrtʃ/", "pos": "n.", "zh": "市场调研", "source": "doing market research in Japan market"}, {"en": "engaged in", "phonetic": "/ɪnˈɡeɪdʒd ɪn/", "pos": "adj. phr.", "zh": "参与；从事", "source": "our product team is also engaged in"}, {"en": "wonder if", "phonetic": "/ˈwʌn.dər ɪf/", "pos": "phr.", "zh": "不知是否...（委婉提议）", "source": "I was just wondering if both teams could collaborate"}, {"en": "common slot", "phonetic": "/ˈkɑː.mən slɑːt/", "pos": "n. phr.", "zh": "共同的时间", "source": "find a common slot"}, {"en": "catch-up", "phonetic": "/ˈkætʃ.ʌp/", "pos": "n.", "zh": "碰头会", "source": "for a catch-up"}, {"en": "availabilities", "phonetic": "/əˌveɪ.ləˈbɪl.ə.tiz/", "pos": "n. pl.", "zh": "空闲时间", "source": "check others' availabilities"}], "grammar": [{"title": "I was just wondering if... (最委婉的提议)", "structure": "I was just wondering if + 主语 + could/would", "example": "I was just wondering if both teams could collaborate.", "explanation": "I was wondering if是最委婉的提议句型，比Can we...更礼貌，适合初步接触和试探合作意向。"}], "coreSentences": [{"original": "I was just wondering if both teams could collaborate.", "function": "委婉提议合作", "alternative": "I was thinking maybe we could work together on this. / Any interest in teaming up?"}, {"original": "Sounds fantastic.", "function": "积极回应提议", "alternative": "That sounds great. / I love that idea."}, {"original": "Let's find a common slot this afternoon.", "function": "约定时间", "alternative": "Let's sync up this afternoon. / Can we schedule a call?"}, {"original": "Let me also check others' availabilities.", "function": "确认其他人时间", "alternative": "I'll check with the rest of the team. / Let me see who else is free."}], "exercises": {"vocabChoice": [{"question": "\"I was wondering if\" 用来？", "options": ["直接命令", "委婉提议/询问", "表达愤怒", "报告信息"], "answer": 1}, {"question": "\"common slot\" 指？", "options": ["公共车位", "共同空闲时间", "常用插槽", "公共场所"], "answer": 1}], "fillBlank": [{"sentence": "I was just ______ if we could collaborate.", "answer": "wondering", "hint": "想知道(委婉)"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "跨团队合作的初步沟通用I was wondering if展示了高情商。不强推自己的议程，而是'好奇是否可以合作'。西方跨部门合作尤其注重这种柔性的开场白。", "interviewTip": "", "difficulty": "🔵中级"}, {"id": 69, "file": "69-会前寒暄", "title": "会前寒暄", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["You'd better take a good rest before diving back into your work, business trips are quite exhausting.", "you bet, thanks.", "Did you get a chance to do any sightseeing during your trip?", "Not really, I just wandered around the neighborhood and bought some souvenirs. I see everyone has logged on, shall we save our chit chat until after the meeting?", "For sure, we can catch up more afterwards, let's get it going."], "dialogueZH": ["在重新投入工作之前，你最好好好休息一下，出差是很累人的。", "当然，谢谢。", "你出差期间有机会去观光吗？", "没有，我只是在附近转了转，买了些纪念品。我看大家都上线了，我们把闲聊留到会后再聊好吗？", "当然可以，会后我们可以多聊聊，开始吧。"], "vocabulary": [{"en": "dive back into", "phonetic": "/daɪv bæk ˈɪn.tə/", "pos": "v. phr.", "zh": "重新投入", "source": "diving back into your work"}, {"en": "business trip", "phonetic": "/ˈbɪz.nɪs trɪp/", "pos": "n.", "zh": "出差", "source": "business trips are quite exhausting"}, {"en": "exhausting", "phonetic": "/ɪɡˈzɔː.stɪŋ/", "pos": "adj.", "zh": "令人疲惫的", "source": "quite exhausting"}, {"en": "sightseeing", "phonetic": "/ˈsaɪtˌsiː.ɪŋ/", "pos": "n.", "zh": "观光", "source": "do any sightseeing"}, {"en": "wander around", "phonetic": "/ˈwɑːn.dər əˈraʊnd/", "pos": "v. phr.", "zh": "四处逛逛", "source": "wandered around the neighborhood"}, {"en": "souvenirs", "phonetic": "/ˌsuː.vəˈnɪrz/", "pos": "n.", "zh": "纪念品", "source": "bought some souvenirs"}, {"en": "chit chat", "phonetic": "/tʃɪt tʃæt/", "pos": "n.", "zh": "闲聊", "source": "save our chit chat until after the meeting"}], "grammar": [{"title": "Shall we + V? (提议)", "structure": "Shall we + 动词原形?", "example": "Shall we save our chit chat until after the meeting?", "explanation": "Shall we = 要不要...？英式委婉提议，比Let's更尊重对方，比Should we更地道。"}], "coreSentences": [{"original": "You'd better take a good rest before diving back into work.", "function": "表达关心", "alternative": "Make sure to recharge before you jump back in."}, {"original": "Business trips are quite exhausting.", "function": "表示理解", "alternative": "Travel can really wear you out. / Work trips take a lot out of you."}, {"original": "Did you get a chance to do any sightseeing?", "function": "开启轻松话题", "alternative": "Did you manage to see the city at all? / Any time for sightseeing?"}, {"original": "Shall we save our chit chat until after the meeting?", "function": "正式进入会议", "alternative": "Let's get down to business. We can catch up later."}], "exercises": {"vocabChoice": [{"question": "\"exhausting\" 的意思是？", "options": ["令人兴奋的", "令人疲惫的", "有趣的", "快速的"], "answer": 1}, {"question": "\"chit chat\" 指什么？", "options": ["聊天记录", "闲聊/寒暄", "正式谈话", "笑话"], "answer": 1}], "fillBlank": [{"sentence": "Shall we save our ______ chat until after the meeting?", "answer": "chit", "hint": "闲聊(固定搭配)"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方会议通常以2-3分钟的small talk开始(天气、周末、出差)。但好的会议主持人知道何时自然过渡到正题——'save our chit chat until after the meeting'是最得体的过渡语。", "interviewTip": "", "difficulty": "🟢入门"}, {"id": 70, "file": "70-开启会议", "title": "开启会议", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Hi, everyone. this is our first XFN sync-up meeting before we take a deep dive into the discussion. I'd like to brief everyone on the background information. As we all know that the upper management has set Japan market as top priority for this year, both teams have been working on feasibility study. If all is good, project team may quickly kick things off.", "With this in mind, I just set up this call to align on the progress and goals, so both ends can collaborate more efficiently. Okay, how about going clockwise around the screen to hear the comments respectively. John, would u mind making a start?"], "dialogueZH": ["大家好。这是我们第一次在深入讨论之前进行的跨职能同步会议。我想向大家简要介绍一下背景信息。众所周知，高层管理团队已将日本市场列为今年的首要任务，两个团队都在进行可行性研究。如果一切顺利，项目团队可能会迅速启动。", "考虑到这一点，我安排了这次会议，目的是对齐进度和目标，以便双方能更高效地协作。好吧，我们按屏幕上的顺序顺时针轮流发言怎么样？约翰，你介意先开始吗？"], "vocabulary": [{"en": "sync-up", "phonetic": "/sɪŋk ʌp/", "pos": "n.", "zh": "同步会议", "source": "XFN sync-up meeting"}, {"en": "take a deep dive", "phonetic": "/teɪk ə diːp daɪv/", "pos": "v. phr.", "zh": "深入探讨", "source": "before we take a deep dive"}, {"en": "brief on", "phonetic": "/briːf ɑːn/", "pos": "v. phr.", "zh": "简要介绍", "source": "brief everyone on the background"}, {"en": "set up this call", "phonetic": "/set ʌp ðɪs kɔːl/", "pos": "v. phr.", "zh": "组织这次会议", "source": "set up this call"}, {"en": "align on", "phonetic": "/əˈlaɪn ɑːn/", "pos": "v. phr.", "zh": "就...达成一致", "source": "align on the progress and goals"}, {"en": "go clockwise", "phonetic": "/ɡoʊ ˈklɑːk.waɪz/", "pos": "v. phr.", "zh": "顺时针轮流", "source": "going clockwise around the screen"}], "grammar": [{"title": "With this in mind, ... (基于此)", "structure": "With this in mind, + 主句", "example": "With this in mind, I set up this call to align on progress.", "explanation": "With this in mind = 鉴于以上。作为会议总结/过渡语，承接上文背景说明，引出本次会议目的。"}], "coreSentences": [{"original": "I'd like to brief everyone on the background information.", "function": "介绍背景", "alternative": "Let me give a quick context overview. / Here's some background for everyone."}, {"original": "I set up this call to align on progress and goals.", "function": "说明会议目的", "alternative": "The purpose of this call is to sync up. / We're here to get aligned."}, {"original": "How about going clockwise around the screen to hear from each team?", "function": "开始轮流发言", "alternative": "Let's go round the table. / Let's hear from each team in turn."}], "exercises": {"vocabChoice": [{"question": "\"take a deep dive\" 表示？", "options": ["潜水", "深入探讨/深入研究", "快速浏览", "跳过"], "answer": 1}, {"question": "\"align on\" 的意思是？", "options": ["对齐", "就...达成一致/对齐", "排列", "直线"], "answer": 1}], "fillBlank": [{"sentence": "I'd like to ______ everyone on the background.", "answer": "brief", "hint": "简要介绍"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "好的会议主持人会在开头3点讲清楚：1)会议背景(why we're here) 2)会议目标(what we want to achieve) 3)流程(how we'll run this)。这叫'ABC opening'。", "interviewTip": "", "difficulty": "🔵中级"}, {"id": 71, "file": "71-观点阐述", "title": "观点阐述", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Sure, product team actually has kick started the research for a while, and we reckon JP is blue sea market. For one thing, we've consulted with the legal consultant, learning our business is compliant. Meanwhile, our rival company hasn't entered this market yet. So personally I believe it's now or never for us, just wondering if project team think alike. Steve, what's your take on this?"], "dialogueZH": ["当然，产品团队实际上已经启动研究有一段时间了，我们认为日本市场是一个蓝海市场。一方面，我们咨询了法律顾问，了解到我们的业务是合规的。与此同时，我们的竞争对手还没有进入这个市场。所以，我个人认为对我们来说这是机不可失，失不再来，只是想知道项目团队是否也有同样的看法。史蒂夫，你对此怎么看？"], "vocabulary": [{"en": "kick start", "phonetic": "/kɪk stɑːrt/", "pos": "v.", "zh": "启动", "source": "kick started the research"}, {"en": "reckon", "phonetic": "/ˈrek.ən/", "pos": "v.", "zh": "认为；估计", "source": "we reckon"}, {"en": "blue sea market", "phonetic": "/bluː siː ˈmɑːr.kɪt/", "pos": "n. phr.", "zh": "蓝海市场", "source": "JP is blue sea market"}, {"en": "legal consultant", "phonetic": "/ˈliː.ɡəl kənˈsʌl.tənt/", "pos": "n.", "zh": "法律顾问", "source": "consulted with the legal consultant"}, {"en": "ground work", "phonetic": "/ɡraʊnd wɜːrk/", "pos": "n.", "zh": "基础工作", "source": "done some ground work"}], "grammar": [{"title": "For one thing... (列举论点)", "structure": "For one thing, ... For another, ...", "example": "For one thing, we've consulted with the legal consultant.", "explanation": "For one thing... (For another...) 是列举论点的标准表达，比Firstly/Secondly更口语化。"}], "coreSentences": [{"original": "We've kick started the research for a while.", "function": "说明已开始工作", "alternative": "We've been working on this for some time now."}, {"original": "We reckon JP is a blue sea market.", "function": "表达判断", "alternative": "We believe Japan represents a huge opportunity."}, {"original": "We've consulted with the legal consultant.", "function": "说明已做专业咨询", "alternative": "We've sought legal advice on this. / Our legal team has reviewed this."}], "exercises": {"vocabChoice": [{"question": "\"blue sea market\" 表示？", "options": ["蓝色海洋", "蓝海市场（未开发市场）", "蓝色大海", "蓝色经济"], "answer": 1}, {"question": "\"reckon\" 的意思是？", "options": ["计算", "认为/估计", "忽略", "拒绝"], "answer": 1}], "fillBlank": [{"sentence": "We've done some ______ work before the meeting.", "answer": "ground", "hint": "基础(工作)"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方会议中，提出观点前先铺垫你做了哪些research/consultation——'evidence before opinion'是说服力的基础。简单一句'we've consulted with legal'就能大幅增强可信度。", "interviewTip": "", "difficulty": "🔵中级"}, {"id": 72, "file": "72-澄清观点", "title": "澄清观点", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Yes, I understand the urgency, but I would say we can't base our decision solely on a gut feeling, we need to have data to back it up. Apart from that, some industrial reports indicate the market is still unripe for our new product. So if we choose to release now, it may take long time for local people to be fully receptive to our product.", "Sorry, what do you mean by \"unripe\", can you please clarify?", "All right, let me just rephrase. I mean local people still tend to have their old-fashioned ways, or to put it simply, more time is needed for them to get accustomed to the new ways."], "dialogueZH": ["是的，我理解这种紧迫感，但我想说我们不能仅仅凭直觉来做决定，我们需要有数据来支持。除此之外，一些行业报告显示，市场对我们新产品来说还不成熟。所以如果我们选择现在发布，当地人可能需要很长时间才能完全接受我们的产品。", "抱歉，“unripe”是什么意思？你能解释一下吗？", "好吧，我换个说法。我的意思是当地人仍然倾向于保持他们旧有的习惯，或者简单地说，他们需要更多时间来适应新的方式。"], "vocabulary": [{"en": "gut feeling", "phonetic": "/ɡʌt ˈfiː.lɪŋ/", "pos": "n. phr.", "zh": "直觉；本能感觉", "source": "base solely on a gut feeling"}, {"en": "back it up", "phonetic": "/bæk ɪt ʌp/", "pos": "v. phr.", "zh": "支持；佐证", "source": "need data to back it up"}, {"en": "unripe", "phonetic": "/ʌnˈraɪp/", "pos": "adj.", "zh": "不成熟的；时机未到的", "source": "the market seems unripe"}, {"en": "clarify", "phonetic": "/ˈkler.ɪ.faɪ/", "pos": "v.", "zh": "澄清；说明白", "source": "can you please clarify"}, {"en": "rephrase", "phonetic": "/ˌriːˈfreɪz/", "pos": "v.", "zh": "换个说法", "source": "let me just rephrase"}, {"en": "old-fashioned", "phonetic": "/oʊld ˈfæʃ.ənd/", "pos": "adj.", "zh": "守旧的；老式的", "source": "their old-fashioned ways"}, {"en": "get accustomed to", "phonetic": "/ɡet əˈkʌs.təmd tə/", "pos": "v. phr.", "zh": "适应；习惯", "source": "get accustomed to the new way"}], "grammar": [{"title": "I would say we can't... (谨慎表达对立观点)", "structure": "I would say + 从句", "example": "I would say we can't base our decision solely on a gut feeling.", "explanation": "I would say = 我想说的是/我认为。比I think更柔和，加上can't委婉表达反对而不强硬。"}], "coreSentences": [{"original": "We can't base our decision solely on a gut feeling.", "function": "质疑证据不足", "alternative": "We need more than intuition to go on. / Let's base this on data, not assumptions."}, {"original": "Sorry, what do you mean by \"unripe\"? Can you clarify?", "function": "要求澄清术语", "alternative": "Could you unpack that? / What exactly do you mean by that?"}, {"original": "Let me just rephrase.", "function": "准备换个说法", "alternative": "Let me put it another way. / Allow me to clarify."}, {"original": "More time is needed for them to get accustomed to the new way.", "function": "解释推论", "alternative": "The market needs more time to adapt. / There's a learning curve for local users."}], "exercises": {"vocabChoice": [{"question": "\"gut feeling\" 指什么？", "options": ["肚子不舒服", "直觉/本能感觉", "科学研究", "数据支持"], "answer": 1}, {"question": "\"back it up\" 的意思是？", "options": ["备份", "支持/佐证", "后退", "回来"], "answer": 1}], "fillBlank": [{"sentence": "Let me just ______ that.", "answer": "rephrase", "hint": "换个说法"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方会议文化中，'I don't understand'是完全可以说的。要求澄清(sorry, what do you mean by...)被视为认真参与的表现，而非无知。rephrase是沟通中非常必要的技巧。", "interviewTip": "", "difficulty": "🔵中级"}, {"id": 73, "file": "73-赞成和异议", "title": "赞成和异议", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Yes, I would echo that. Sometimes, it's quite hard for people to break out of their old habits. We have to factor in the risk of launching prematurely. We don't want to waste resources and damage our brand reputation if the product fails.", "Sorry to chimp in, but I see it differently. Despite the formidable challenges, we should push it out now, as long as our product could offer convenience or accommodate the needs of their lives. The longer we wait, the less of an impact it will have when we finally release. It's just a matter of time and well worth our efforts."], "dialogueZH": ["是的，我同意这一点。有时候，人们很难改掉旧习惯。我们必须考虑到过早推出产品的风险。如果产品失败，我们不想浪费资源并损害我们的品牌声誉。", "抱歉插一句嘴，但我看法不同。尽管面临巨大的挑战，只要我们的产品能提供便利或满足他们的生活需求，我们就应该现在就推出。我们等得越久，最终发布时产生的影响就越小。这只是时间问题，而且值得我们付出努力。"], "vocabulary": [{"en": "echo", "phonetic": "/ˈek.oʊ/", "pos": "v.", "zh": "附和；赞同", "source": "I would echo that"}, {"en": "break out of", "phonetic": "/breɪk aʊt əv/", "pos": "v. phr.", "zh": "打破；摆脱", "source": "break out of their old habits"}, {"en": "factor in", "phonetic": "/ˈfæk.tər ɪn/", "pos": "v. phr.", "zh": "考虑到；把...考虑进去", "source": "factor in the risk"}, {"en": "launching prematurely", "phonetic": "/ˈlɔːn.tʃɪŋ ˌpriː.məˈtʃʊr.li/", "pos": "n. phr.", "zh": "过早发布", "source": "risk of launching prematurely"}, {"en": "chime in", "phonetic": "/tʃaɪm ɪn/", "pos": "v. phr.", "zh": "插话；插一句", "source": "Sorry to chime in"}, {"en": "formidable", "phonetic": "/ˈfɔːr.mɪ.də.bəl/", "pos": "adj.", "zh": "巨大的；令人敬畏的", "source": "formidable challenges"}, {"en": "push out", "phonetic": "/pʊʃ aʊt/", "pos": "v. phr.", "zh": "推出（产品等）", "source": "we should push it out now"}, {"en": "accommodate the needs", "phonetic": "/əˈkɑː.mə.deɪt ðə niːdz/", "pos": "v. phr.", "zh": "满足需求", "source": "accommodate the needs of users"}], "grammar": [{"title": "Sorry to chime in, but I see it differently.", "structure": "Sorry to chime in, but + 相反观点", "example": "Sorry to chime in, but I see it differently.", "explanation": "Chime in = 插话。先道歉再表达不同意见，是非常礼貌的异议表达方式，适合职场会议。"}], "coreSentences": [{"original": "I would echo that.", "function": "赞同对方", "alternative": "I agree completely. / My thoughts exactly."}, {"original": "We have to factor in the risk of launching prematurely.", "function": "提出风险考量", "alternative": "We need to consider the downside of rushing. / The risks of going too fast can't be ignored."}, {"original": "Sorry to chime in, but I see it differently.", "function": "礼貌表达异议", "alternative": "I'd like to offer a different perspective. / I respectfully disagree."}, {"original": "As long as our product could accommodate the needs of users.", "function": "说明条件", "alternative": "Provided we meet user needs. / As long as we deliver value to customers."}], "exercises": {"vocabChoice": [{"question": "\"echo\" 在会议中的意思是？", "options": ["回音", "赞同/附和", "反对", "打断"], "answer": 1}, {"question": "\"chime in\" 表示？", "options": ["插话/加入讨论", "唱和声", "沉默", "离开"], "answer": 0}], "fillBlank": [{"sentence": "Sorry to ______ in, but I see it differently.", "answer": "chime", "hint": "插话(口语)"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方会议鼓励不同意见的碰撞。'I see it differently'是完全正常且受欢迎的表达。关键是用数据说话(back it up with data)而非纯情绪。factor in是会议中非常重要的动词短语。", "interviewTip": "", "difficulty": "🔴进阶"}, {"id": 74, "file": "74-冲突管理", "title": "冲突管理", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["All right, since everyone has had their say now, let's have quick recap of our discussion. Everyone's comments are valuable and insightful, but Japan is a must-win market and ranks high in our strategy. I would suggest we gather more feedback from our target audience, and consolidate all research findings for management to make the ultimate decision. At the end of the day, we need to take it cautiously when venturing into a new market.", "As we are running out of time, shall we leave it here then?", "Okay, great, thank you everyone, Bye."], "dialogueZH": ["好吧，既然大家都已经发表了自己的意见，让我们快速回顾一下我们的讨论。大家的评论都很有价值且富有洞察力，但日本是一个必须赢下的市场，在我们的战略中排名很高。我建议我们从目标受众那里收集更多反馈，并汇总所有研究结果，供管理层做出最终决定。毕竟，当我们进入一个新市场时，我们需要谨慎行事。", "由于时间不多了，我们就先到这里吧？", "好的，太棒了，谢谢大家，再见。"], "vocabulary": [{"en": "had their say", "phonetic": "/hæd ðer seɪ/", "pos": "phr.", "zh": "发表完意见", "source": "everyone has had their say"}, {"en": "recap", "phonetic": "/ˈriː.kæp/", "pos": "n./v.", "zh": "总结；回顾", "source": "have a quick recap"}, {"en": "insightful", "phonetic": "/ˈɪn.saɪt.fəl/", "pos": "adj.", "zh": "有见地的；深刻的", "source": "valuable and insightful"}, {"en": "must-win market", "phonetic": "/mʌst wɪn ˈmɑːr.kɪt/", "pos": "n. phr.", "zh": "必须赢下的市场", "source": "a must-win market"}, {"en": "top the list", "phonetic": "/tɑːp ðə lɪst/", "pos": "v. phr.", "zh": "排在首位的", "source": "tops the list of our priorities"}, {"en": "running out of time", "phonetic": "/ˈrʌn.ɪŋ aʊt əv taɪm/", "pos": "phr.", "zh": "时间不够了", "source": "running out of time"}], "grammar": [{"title": "Since everyone has had their say... (会议过渡语)", "structure": "Since everyone has had their say, + 总结/决策", "example": "Since everyone has had their say now, let's have a quick recap.", "explanation": "have one's say = 发表意见。是会议主持人在各方发表完意见后，引导进入总结/决策阶段的标准用语。"}], "coreSentences": [{"original": "Since everyone has had their say, let's have a quick recap.", "function": "会议总结过渡", "alternative": "Now that we've heard from everyone, let me summarize."}, {"original": "Everyone's comments are valuable and insightful.", "function": "肯定各方贡献", "alternative": "All good points. / Thanks for the thoughtful input, everyone."}, {"original": "Japan is a must-win market that tops the list of our priorities.", "function": "重申战略重要性", "alternative": "Japan is our number one priority. / This market is critical for us."}, {"original": "As we are running out of time, shall we leave it here then?", "function": "因时间结束会议", "alternative": "We're out of time — let's wrap up. / Shall we table this for now?"}], "exercises": {"vocabChoice": [{"question": "\"had one's say\" 表示？", "options": ["说完了", "发表了意见", "有话要说", "说不了"], "answer": 1}, {"question": "\"must-win\" 的意思是？", "options": ["必须赢的", "可能输的", "必须赢下的/关键的", "要胜利的"], "answer": 2}], "fillBlank": [{"sentence": "Let's have a quick ______ of the discussion.", "answer": "recap", "hint": "总结/回顾"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "会议主持人最重要的能力之一是公平总结(neutral recap)——让每个人觉得被听到，然后引导团队到决策点。先用'everyone's comments are valuable'肯定参与，再lead到下一步。", "interviewTip": "", "difficulty": "🔴进阶"}, {"id": 75, "file": "75-同步进度", "title": "同步进度", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["All right, Since everyone is here, let's kick start project status meeting for this week. As usual, each team will take turns to update the progress. John, would you mind taking the lead?", "Sure, in terms of progress, there are 2 key updates from my side", "First, we have released new pop-up features in our product, and target to get approved by the app stores by the end of this week.", "Second, we have finished 50% of competitor studies for the new market.", "and some to dos: we will constantly monitor the conversion rates of transactions on our platform, and proceed with the feasibility of new marketing tactics, which is expected to finish early next week."], "dialogueZH": ["好吧，既然大家都在，那我们就开始本周的项目状态会议吧。和往常一样，每个团队将轮流汇报进度。约翰，你介意先开始吗？", "当然，就进度而言，我这边有两个关键更新。", "首先，我们已经在产品中发布了新的弹窗功能，并计划在本周末前获得应用商店的批准。", "其次，我们已经完成了针对新市场的50%竞争对手研究。", "还有一些待办事项：我们将持续监控平台上交易的转化率，并推进新营销策略的可行性研究，预计下周初完成。"], "vocabulary": [{"en": "kick start", "phonetic": "/kɪk stɑːrt/", "pos": "v.", "zh": "开始", "source": "kick start project status meeting"}, {"en": "take turns", "phonetic": "/teɪk tɜːrnz/", "pos": "v. phr.", "zh": "轮流", "source": "each team will take turns"}, {"en": "update the progress", "phonetic": "/ʌpˈdeɪt ðə ˈprɑː.ɡres/", "pos": "v. phr.", "zh": "更新进展", "source": "update the progress"}, {"en": "pop-up features", "phonetic": "/pɑːp ʌp ˈfiː.tʃərz/", "pos": "n. phr.", "zh": "弹窗功能", "source": "new pop-up features"}, {"en": "competitor studies", "phonetic": "/kəmˈpet.ɪ.tər ˈstʌd.iz/", "pos": "n. phr.", "zh": "竞品研究", "source": "competitor studies for the new market"}, {"en": "on track", "phonetic": "/ɑːn træk/", "pos": "phr.", "zh": "按计划进行", "source": "on track"}], "grammar": [{"title": "Would you mind + V-ing? (礼貌请求)", "structure": "Would you mind + V-ing?", "example": "John, would you mind taking the lead?", "explanation": "Would you mind doing比Can you do更礼貌。回答时No (= I don't mind = 我可以)，注意中西文化差异。"}], "coreSentences": [{"original": "Let's kick start the project status meeting for this week.", "function": "开启例会", "alternative": "Let's get this weekly sync started."}, {"original": "Each team will take turns to update the progress.", "function": "说明议程", "alternative": "Let's go around and hear from each team."}, {"original": "John, would you mind taking the lead?", "function": "礼貌指定发言人", "alternative": "John, could you start us off? / John, do you want to go first?"}, {"original": "We have released new features and target to get approved by end of week.", "function": "汇报具体进度", "alternative": "The new features are out; we're aiming for approval by Friday."}], "exercises": {"vocabChoice": [{"question": "\"take turns\" 的意思是？", "options": ["转角", "轮流", "依次", "转弯"], "answer": 1}, {"question": "\"on track\" 表示？", "options": ["在轨道上", "按计划进行/在正轨上", "脱轨", "追踪"], "answer": 1}], "fillBlank": [{"sentence": "Would you ______ taking the lead, John?", "answer": "mind", "hint": "介意(礼貌请求)"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方stand-up meeting通常每人不超过2分钟，聚焦三点：done (完成了什么), doing (正在做什么), blockers (遇到什么阻碍)。简洁、高频、聚焦。", "interviewTip": "", "difficulty": "🔵中级"}, {"id": 76, "file": "76-风险点与卡点", "title": "风险点与卡点", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["All right, any risks or blockers?", "Yes, we did encounter a bottleneck with the integration of the new vendor. As OTP feature on our APP is unstable in ID market, CS team received a lot of queries last month, we're concerned that this issue may impact on new users' registration. To mitigate the impacts, product team has reallocated some resources from other tasks to cope with this, and sought another vendor for a switchover, now it's pending on their internal approval, which has been quite slow. We have requested to change their POC with our side, so as to facilitate the process and resume our business operation."], "dialogueZH": ["好吧，有什么风险或阻碍吗？", "是的，我们在新供应商的整合过程中遇到了瓶颈。由于我们的APP在印尼市场的OTP功能不稳定，客服团队上个月收到了大量咨询，我们担心这个问题会影响新用户的注册。为了减轻影响，产品团队已经从其他任务中重新分配了一些资源来处理这个问题，并寻找了另一家供应商进行切换，现在正在等待他们的内部批准，这个过程相当缓慢。我们已经请求更换他们的对接人，以便促进流程并恢复我们的业务运营。"], "vocabulary": [{"en": "blockers", "phonetic": "/ˈblɑː.kərz/", "pos": "n.", "zh": "阻碍因素；卡点", "source": "any risks or blockers"}, {"en": "bottleneck", "phonetic": "/ˈbɑː.təl.nek/", "pos": "n.", "zh": "瓶颈", "source": "a bottleneck with the integration"}, {"en": "vendor", "phonetic": "/ˈven.dər/", "pos": "n.", "zh": "供应商", "source": "the new vendor"}, {"en": "OTP (One-Time Password)", "phonetic": "/oʊ tiː piː/", "pos": "n. abbr.", "zh": "一次性密码", "source": "OTP feature on our APP"}, {"en": "queries", "phonetic": "/ˈkwɪr.iz/", "pos": "n.", "zh": "咨询；投诉", "source": "received a lot of queries"}, {"en": "fix the bug", "phonetic": "/fɪks ðə bʌɡ/", "pos": "v. phr.", "zh": "修复漏洞", "source": "collaborating to fix the bug"}], "grammar": [{"title": "We're currently + V-ing (汇报进行中)", "structure": "We're currently/actively + V-ing", "example": "We're currently collaborating with engineers to fix the bug.", "explanation": "进行时态强调工作正在进行中，是进度汇报最常用的时态。currently比now更正式。"}], "coreSentences": [{"original": "Any risks or blockers?", "function": "询问阻碍", "alternative": "What's holding us up? / Any roadblocks to report?"}, {"original": "We encountered a bottleneck with the vendor integration.", "function": "汇报阻塞点", "alternative": "We hit a snag with the vendor. / There's a bottleneck in the integration."}, {"original": "CS team received a lot of queries last month.", "function": "说明问题规模", "alternative": "Customer service has been flooded with complaints."}, {"original": "We're collaborating with engineers to fix the bug.", "function": "说明应对措施", "alternative": "We're working with the tech team on a fix."}], "exercises": {"vocabChoice": [{"question": "\"bottleneck\" 在这里指？", "options": ["瓶颈/阻碍点", "瓶子", "瓶盖", "瓶颈路"], "answer": 0}, {"question": "\"vendor\" 表示？", "options": ["买家", "供应商", "销售", "员工"], "answer": 1}], "fillBlank": [{"sentence": "We encountered a ______ with the system integration.", "answer": "bottleneck", "hint": "瓶颈"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方项目会议中，'risks and blockers'是必问环节。主动汇报blockers不丢人——隐藏问题直到最后一天才是大忌。透明度(transparency)是西方职场最看重的品质之一。", "interviewTip": "", "difficulty": "🔵中级"}, {"id": 77, "file": "77-解决方案", "title": "解决方案", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["That's a smart move. let's chase and get the feedback by end of tomorrow. Meanwhile, highly suggest we prepare an workaround solution in parallel, as we are running a very tight timeline.", "Sorry, I just wandered off for a second. Can you say that again?", "I was saying we need to draw up a tentative plan while waiting for the response. After all it's vital to make a seamless transition in our system.", "I see. Thanks for the valuable input. Just leave it to me. I'll do that after this call."], "dialogueZH": ["这是个明智的举措。让我们去跟进一下，争取在明天结束前拿到反馈。同时，我强烈建议我们并行准备一个临时解决方案，因为我们的进度非常紧张。", "抱歉，我刚才走神了一下。你能再说一遍吗？", "我说的是，我们需要在等待回复的同时制定一个暂定计划。毕竟，在我们的系统中实现无缝过渡至关重要。", "我明白了。谢谢你的宝贵意见。交给我吧。我挂了电话后就去做。"], "vocabulary": [{"en": "smart move", "phonetic": "/smɑːrt muːv/", "pos": "n. phr.", "zh": "明智之举", "source": "That's a smart move"}, {"en": "chase", "phonetic": "/tʃeɪs/", "pos": "v.", "zh": "追；催促", "source": "let's chase and get the feedback"}, {"en": "workaround", "phonetic": "/ˈwɜːrk.ə.raʊnd/", "pos": "n.", "zh": "变通方案；替代方案", "source": "a workaround solution"}, {"en": "in parallel", "phonetic": "/ɪn ˈper.ə.lel/", "pos": "adv. phr.", "zh": "并行地；同时进行", "source": "prepare a workaround in parallel"}, {"en": "wander off", "phonetic": "/ˈwɑːn.dər ɔːf/", "pos": "v. phr.", "zh": "走神", "source": "I just wandered off for a second"}, {"en": "tentative plan", "phonetic": "/ˈten.tə.tɪv plæn/", "pos": "n. phr.", "zh": "暂定方案", "source": "a tentative plan"}, {"en": "seamless transition", "phonetic": "/ˈsiːm.ləs trænˈzɪʃ.ən/", "pos": "n. phr.", "zh": "无缝过渡", "source": "a seamless transition"}], "grammar": [{"title": "I was saying we need to... (重复要点)", "structure": "I was saying + 从句", "example": "I was saying we need to draw up a tentative plan.", "explanation": "当对方走神后重复时用过去进行时I was saying，比重复整句更自然简洁。"}], "coreSentences": [{"original": "That's a smart move.", "function": "肯定对方方案", "alternative": "Good thinking. / That's the right approach."}, {"original": "Let's prepare a workaround solution in parallel.", "function": "提议双轨并行", "alternative": "Let's have a Plan B ready. / We should work on a backup in parallel."}, {"original": "Sorry, I just wandered off for a second.", "function": "诚实地承认走神", "alternative": "I zoned out for a moment. / Could you repeat that?"}, {"original": "Just leave it to me.", "function": "主动承担", "alternative": "I'll take care of it. / I've got this."}], "exercises": {"vocabChoice": [{"question": "\"workaround\" 的意思是？", "options": ["工作环境", "变通方案/替代方案", "围绕工作", "放弃"], "answer": 1}, {"question": "\"in parallel\" 表示？", "options": ["平行线", "并行/同时进行", "一条线", "单独"], "answer": 1}], "fillBlank": [{"sentence": "Let's prepare a workaround solution in ______.", "answer": "parallel", "hint": "并行/同时"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方项目管理有'Plan B思维'——在等待反馈时不干等，而是并行准备备用方案。workaround是产品/技术领域最高频的词之一，意为'虽然不完美但能用的临时方案'。", "interviewTip": "", "difficulty": "🔵中级"}, {"id": 78, "file": "78-会前约时间", "title": "会前约时间", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Hi, everyone. Since we have kicked things off, project team is inviting relevant stakeholders to have a regular sync-up. We target to have the first call for 10-11 am tomorrow, does this time slot work?", "Sorry, is it possible to reschedule? I have a clash as i need to attend another meeting.", "What about putting it off till 11-12am?"], "dialogueZH": ["大家好。既然我们已经启动了项目，项目团队正在邀请相关利益相关者进行定期的同步会议。我们计划明天上午10点到11点进行第一次通话，这个时间段可以吗？", "抱歉，可以重新安排时间吗？我有冲突，因为我需要参加另一个会议。", "推迟到上午11点到12点怎么样？"], "vocabulary": [{"en": "kick things off", "phonetic": "/kɪk θɪŋz ɔːf/", "pos": "v. phr.", "zh": "启动；开始", "source": "we have kicked things off"}, {"en": "regular sync-up", "phonetic": "/ˈreɡ.jə.lər sɪŋk ʌp/", "pos": "n. phr.", "zh": "定期同步会", "source": "a regular sync-up"}, {"en": "does that work for everyone", "phonetic": "/dʌz ðæt wɜːrk fər ˈev.ri.wʌn/", "pos": "phr.", "zh": "大家方便吗？", "source": "does that work for everyone"}, {"en": "reschedule", "phonetic": "/ˌriːˈskedʒ.uːl/", "pos": "v.", "zh": "重新安排时间", "source": "possible to reschedule"}, {"en": "clash", "phonetic": "/klæʃ/", "pos": "n.", "zh": "时间冲突", "source": "I have a clash"}, {"en": "put off", "phonetic": "/pʊt ɔːf/", "pos": "v. phr.", "zh": "推迟", "source": "putting it off till 11-12"}], "grammar": [{"title": "Does that work for everyone? (确认时间方便)", "structure": "Does that work for + 人?", "example": "Does that work for everyone?", "explanation": "比Is that OK更地道。还可以用Does that suit you? / Would that be convenient?"}], "coreSentences": [{"original": "We target to have the call for 10-11 am tomorrow.", "function": "提议会议时间", "alternative": "We're aiming for 10-11 tomorrow. / How about tomorrow 10-11?"}, {"original": "Does that work for everyone?", "function": "确认大家方便", "alternative": "Would that suit everyone? / Is everyone available then?"}, {"original": "Is it possible to reschedule?", "function": "请求改时间", "alternative": "Could we do a different time? / Any chance we could move it?"}, {"original": "I have a clash as I need to attend another meeting.", "function": "说明时间冲突", "alternative": "That conflicts with another meeting. / I'm double-booked at that time."}], "exercises": {"vocabChoice": [{"question": "\"clash\" 在会议语境是？", "options": ["冲突/时间重叠", "打架", "声音", "分类"], "answer": 0}, {"question": "\"reschedule\" 表示？", "options": ["取消", "重新安排时间", "开始", "结束"], "answer": 1}], "fillBlank": [{"sentence": "I have a ______ with another meeting at that time.", "answer": "clash", "hint": "时间冲突"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方职场中用shared calendar(共享日历)是基本操作。约时间先看对方日历空闲，减少'clash'。'Does that work for everyone'是确认会议时间最常用的短语。", "interviewTip": "", "difficulty": "🟢入门"}, {"id": 79, "file": "79-参会确认", "title": "参会确认", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Do we have everyone here?", "John hasn't dropped off from his call yet, which has ran overtime. I've buzzed him, he should be joining in a few minutes.", "Not an issue, let's just wait a bit as he is a mandatory attendee. All right, looks like we are all online now, so let's get rolling."], "dialogueZH": ["大家都到齐了吗？", "约翰还没结束他的电话会议，那个会议超时了。我已经提醒他了，他应该几分钟后就会加入。", "没问题，我们稍微等一下，因为他是必须参加的人员。好了，看起来现在大家都在线了，那我们开始吧。"], "vocabulary": [{"en": "Do we have everyone here?", "phonetic": "/duː wiː hæv ˈev.ri.wʌn hɪr/", "pos": "phr.", "zh": "大家都到了吗？", "source": "Do we have everyone here"}, {"en": "drop off", "phonetic": "/drɑːp ɔːf/", "pos": "v. phr.", "zh": "离开/掉线(会议)", "source": "hasn't dropped off from his call"}, {"en": "ran overtime", "phonetic": "/ræn ˈoʊ.vər.taɪm/", "pos": "v. phr.", "zh": "超时了", "source": "which has ran overtime"}, {"en": "buzz", "phonetic": "/bʌz/", "pos": "v.", "zh": "(消息)联系；呼叫", "source": "I've buzzed him"}, {"en": "mandatory attendee", "phonetic": "/ˈmæn.də.tɔːr.i əˌtenˈdiː/", "pos": "n. phr.", "zh": "必须参加的人", "source": "a mandatory attendee"}, {"en": "get rolling", "phonetic": "/ɡet ˈroʊ.lɪŋ/", "pos": "v. phr.", "zh": "开始", "source": "let's get rolling"}], "grammar": [{"title": "Looks like we are all online now (确认到场)", "structure": "Looks like + 从句", "example": "Looks like we are all online now, so let's get rolling.", "explanation": "Looks like = 看来/看起来，口语中用于基于观察做判断，比It seems更随意自然。"}], "coreSentences": [{"original": "Do we have everyone here?", "function": "确认出席", "alternative": "Is everyone on? / Are we all here?"}, {"original": "John's call has run overtime.", "function": "解释某人迟到", "alternative": "John's running late — his previous call went over."}, {"original": "I've buzzed him, he should be joining soon.", "function": "说明已联系", "alternative": "I pinged him. He'll join us shortly."}, {"original": "Looks like we are all online now, so let's get rolling.", "function": "正式开始会议", "alternative": "Everyone's here — let's dive in. / Now that we're all here, let's start."}], "exercises": {"vocabChoice": [{"question": "\"ran overtime\" 表示？", "options": ["跑步", "超时了", "准时", "提前结束"], "answer": 1}, {"question": "\"buzz\" 在这里的意思是？", "options": ["嗡嗡声", "发消息/联系", "打电话", "邮件"], "answer": 1}], "fillBlank": [{"sentence": "His last call ______ overtime.", "answer": "ran", "hint": "超时了"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方会议开场的头2分钟通常用来等迟到的人。用'I've buzzed him'而非'He's late'给人留面子。等关键人物(mandatory attendee)时稍微等一下是正常的礼仪。", "interviewTip": "", "difficulty": "🟢入门"}, {"id": 80, "file": "80-议程介绍", "title": "议程介绍", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Thanks everyone for taking time to attend this call. As we know the management has re-pivoted our strategy to the new market. The project has got off the ground for a while, so we set up this recurring meeting, ensuring everyone is aligned on the status and any possible risks.", "Before we start this call, here are the agenda items and some ground rules: we will have representatives from each team to speak for 20 mins separately, and a Q&A session at the end if time permits. To make things easier, I will go around the screen and invite each team to update separately. Please be mindful of the time restraint."], "dialogueZH": ["谢谢大家抽出时间参加这次会议。正如我们所知，管理层已经将我们的战略重新调整到了新市场。项目已经启动了一段时间，所以我们设立了这个定期会议，以确保每个人都能了解项目状态和任何潜在风险。", "在我们开始之前，这里有一些议程项目和基本规则：我们将让每个团队的代表分别发言20分钟，如果时间允许，最后会有一个问答环节。为了方便起见，我会按顺序邀请每个团队分别进行更新。请大家注意时间限制。"], "vocabulary": [{"en": "re-pivot", "phonetic": "/riː ˈpɪv.ət/", "pos": "v.", "zh": "重新调整方向/重心", "source": "the management has re-pivoted our strategy"}, {"en": "got off the ground", "phonetic": "/ɡɑːt ɔːf ðə ɡraʊnd/", "pos": "idiom", "zh": "启动；走上正轨", "source": "the project has got off the ground"}, {"en": "agenda items", "phonetic": "/əˈdʒen.də ˈaɪ.təmz/", "pos": "n. phr.", "zh": "议程事项", "source": "the agenda items"}, {"en": "ground rules", "phonetic": "/ɡraʊnd ruːlz/", "pos": "n. phr.", "zh": "基本规则", "source": "some ground rules"}, {"en": "representatives", "phonetic": "/ˌrep.rɪˈzen.tə.tɪvz/", "pos": "n.", "zh": "代表", "source": "representatives from each team"}, {"en": "Q&A session", "phonetic": "/kjuː ænd eɪ ˈseʃ.ən/", "pos": "n.", "zh": "问答环节", "source": "a Q&A session at the end"}], "grammar": [{"title": "Before we start, here are... (事先说明)", "structure": "Before we + 动词原形, here are + 复数名词", "example": "Before we start this call, here are the agenda items and some ground rules.", "explanation": "在会议开始前先公布agenda和rules是高效会议主持的标准动作。设定预期可以让会议更聚焦。"}], "coreSentences": [{"original": "Thanks everyone for taking time to attend this call.", "function": "感谢参会", "alternative": "Appreciate everyone making time for this."}, {"original": "The project has got off the ground for a while.", "function": "说明项目已启动", "alternative": "The project is already underway. / We've been working on this for some time."}, {"original": "Here are the agenda items and some ground rules.", "function": "公布议程规则", "alternative": "Let me outline the agenda and meeting norms. / Here's what we'll cover and how we'll run this."}, {"original": "We'll have a Q&A session at the end.", "function": "说明问答安排", "alternative": "We'll save questions for the end. / There will be time for Q&A after each presentation."}], "exercises": {"vocabChoice": [{"question": "\"re-pivot\" 表示？", "options": ["旋转", "重新调整方向/重心", "反复", "改变"], "answer": 1}, {"question": "\"got off the ground\" 意思是？", "options": ["降落", "启动/走上正轨", "起飞", "摔倒"], "answer": 1}], "fillBlank": [{"sentence": "Here are the ______ items and some ground rules.", "answer": "agenda", "hint": "议程"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方会议文化非常看重'agenda'和'ground rules'。好的主持人在开头花1分钟说明会议流程，能大幅提升效率。'Q&A at the end'是最常见的安排，避免中途被打断。", "interviewTip": "", "difficulty": "🔵中级"}, {"id": 81, "file": "81-鼓励发言", "title": "鼓励发言", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Who would like to take the floor and share your thoughts? John, I saw your hands raised in the chatbox, you wanna take the lead?", "Yeah, thanks Steve. Just to let you know, I need to jump out in 30 mins for an urgent call, as I know we were booked for 1 hour.", "No problem, we'll catch you up afterwards.", "Okay, thanks. let me just share my screen. All right, hopefully everyone can see my screen."], "dialogueZH": ["谁想发言并分享一下你的想法？约翰，我看到你在聊天框里举手了，你想先来吗？", "是的，谢谢史蒂夫。只是想让你知道一下，我需要在30分钟后离开去参加一个紧急电话会议，因为我知道我们预订了1个小时的时间。", "没问题，之后我们会把内容同步给你的。", "好的，谢谢。让我先共享一下屏幕。好了，希望每个人都能看到我的屏幕。"], "vocabulary": [{"en": "take the floor", "phonetic": "/teɪk ðə flɔːr/", "pos": "idiom", "zh": "发言", "source": "take the floor and share your thoughts"}, {"en": "hands raised", "phonetic": "/hændz reɪzd/", "pos": "n. phr.", "zh": "举手", "source": "hands raised in the chatbox"}, {"en": "take the lead", "phonetic": "/teɪk ðə liːd/", "pos": "v. phr.", "zh": "带头；先发言", "source": "you wanna take the lead"}, {"en": "jump out", "phonetic": "/dʒʌmp aʊt/", "pos": "v. phr.", "zh": "中途离开（会议）", "source": "need to jump out in 30 mins"}, {"en": "catch you up", "phonetic": "/kætʃ juː ʌp/", "pos": "v. phr.", "zh": "帮你补上；同步给你", "source": "we'll catch you up afterwards"}, {"en": "booked for", "phonetic": "/bʊkt fər/", "pos": "v. phr.", "zh": "预定（时长）", "source": "we were booked for 1 hour"}], "grammar": [{"title": "Who would like to take the floor? (邀请发言)", "structure": "Who would like to + 动词原形?", "example": "Who would like to take the floor and share your thoughts?", "explanation": "Take the floor = 发言。最正式的会议邀请发言用语，比who wants to speak更正式专业。"}], "coreSentences": [{"original": "Who would like to take the floor?", "function": "邀请发言", "alternative": "Who'd like to kick us off? / Anyone want to start?"}, {"original": "John, I saw your hands raised in the chatbox.", "function": "点名发言", "alternative": "John, I see you have a comment. / John, you wanted to say something?"}, {"original": "I need to jump out in 30 mins for an urgent call.", "function": "提前离席", "alternative": "I'll need to drop off in 30 minutes. / I have to leave early for another call."}, {"original": "We'll catch you up afterwards.", "function": "承诺同步信息", "alternative": "We'll fill you in later. / I'll send you a recap."}], "exercises": {"vocabChoice": [{"question": "\"take the floor\" 表示？", "options": ["拿地板", "发言/讲话", "打扫", "进攻"], "answer": 1}, {"question": "\"catch up\" 在这里的意思是？", "options": ["抓住", "追赶/补上信息", "接住", "追上"], "answer": 1}], "fillBlank": [{"sentence": "Who would like to ______ the floor first?", "answer": "take", "hint": "发言(习语)"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方线上会议用'举手'功能或chatbox表示想发言。主持人主动邀请举手的人是好的会议主持习惯。'jump out'/'drop off'是线上会议中途离开的地道表达。", "interviewTip": "", "difficulty": "🟢入门"}, {"id": 82, "file": "82-状况管理", "title": "状况管理", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Hello John, we are losing you, are you on mute?", "Sorry, I just turned on my mic. How about now?", "Yes, but your voice is a bit low.", "Sorry, please bear with me for a second, let me connect to my earphone. Better now?", "Yeah, a bit better, but there was a terrible lag, and your screen was frozen for a while.", "Sorry, One second, let me switch to my mobile data. Is it better?", "Sure, much better, now we can hear you quite clearly", "Okay, so sorry for the disruption, my Wifi just broke down. Let me just repeat."], "dialogueZH": ["你好，约翰，我们听不清你说话了，你是不是静音了？", "抱歉，我刚打开麦克风。现在怎么样？", "是的，但你的声音有点小。", "抱歉，请稍等一下，我连一下耳机。现在好点了吗？", "是的，稍微好一点了，但延迟非常严重，而且你的屏幕卡住了一会儿。", "抱歉，等一下，我切换到移动数据。现在好点了吗？", "当然，好多了，现在我们能听得很清楚了。", "好的，非常抱歉造成干扰，我的Wi-Fi刚刚断了。让我重复一下。"], "vocabulary": [{"en": "losing you", "phonetic": "/ˈluː.zɪŋ juː/", "pos": "phr.", "zh": "听不到你/你的信号断断续续", "source": "we are losing you"}, {"en": "on mute", "phonetic": "/ɑːn mjuːt/", "pos": "phr.", "zh": "静音状态", "source": "are you on mute"}, {"en": "turn on my mic", "phonetic": "/tɜːrn ɑːn maɪ maɪk/", "pos": "v. phr.", "zh": "打开麦克风", "source": "I just turned on my mic"}, {"en": "voice is low", "phonetic": "/vɔɪs ɪz loʊ/", "pos": "phr.", "zh": "声音太小", "source": "your voice is a bit low"}, {"en": "freeze", "phonetic": "/friːz/", "pos": "v.", "zh": "画面/声音卡住了", "source": "freeze"}, {"en": "technical glitch", "phonetic": "/ˈtek.nɪ.kəl ɡlɪtʃ/", "pos": "n. phr.", "zh": "技术故障", "source": "technical glitch"}], "grammar": [{"title": "Are you on mute? (会议技术问题)", "structure": "Are you + 状态?", "example": "Are you on mute?", "explanation": "线上会议最高频的一句话。on mute = 静音状态。还可以说You're muted. / Can you unmute yourself?"}], "coreSentences": [{"original": "We are losing you, are you on mute?", "function": "提醒对方没声音", "alternative": "You're breaking up. Are you muted? / Your audio is cutting out."}, {"original": "Sorry, I just turned on my mic. How about now?", "function": "解除静音后确认", "alternative": "Can you hear me now? / Is that better?"}, {"original": "Your voice is a bit low.", "function": "反馈音量", "alternative": "Could you speak up a bit? / We're having trouble hearing you."}], "exercises": {"vocabChoice": [{"question": "\"on mute\" 表示？", "options": ["无声的", "静音状态", "很大的声音", "低音"], "answer": 1}, {"question": "\"losing you\" 在会议中指？", "options": ["失去你", "听不到你的声音/信号差", "迷路", "丢失"], "answer": 1}], "fillBlank": [{"sentence": "Are you on ______? We can't hear you.", "answer": "mute", "hint": "静音"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "\"You're on mute\"是远程办公时代最经典的一句话。线上会议中处理技术问题要简洁——快速提醒、快速修复、快速回到正题，不要花太多时间在技术调试上。", "interviewTip": "", "difficulty": "🟢入门"}, {"id": 83, "file": "83-时间把控", "title": "时间把控", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Sorry to chimp in. John, seems we are totally get sidetracked. Why don't we put aside this for now for an offline discussion, or maybe at the end of the meeting, we can circle back to this.", "Thanks John for your wonderful presentation. also a kind reminder for the rest speakers, in the interest of time, please stay on track when presenting.", "Okay, I think we are done with the presentation. But I'm afraid we need to skip the Q&A session as the presentations ran overtime. Before turning to the next session, are there anything else we need to bring up?"], "dialogueZH": ["抱歉打断一下。约翰，看来我们完全跑题了。为什么不先把这个问题放一边，稍后再私下讨论，或者也许在会议结束时我们再回到这个话题。", "谢谢约翰精彩的演示。也顺便提醒一下其他发言人，为了节省时间，请在演示时保持主题。", "好的，我想演示部分已经结束了。但恐怕我们需要跳过问答环节，因为演示超时了。在进入下一个环节之前，还有其他需要提出的事情吗？"], "vocabulary": [{"en": "get sidetracked", "phonetic": "/ɡet ˈsaɪd.trækt/", "pos": "v. phr.", "zh": "跑题；偏离主题", "source": "totally get sidetracked"}, {"en": "put aside", "phonetic": "/pʊt əˈsaɪd/", "pos": "v. phr.", "zh": "放到一边", "source": "put aside this for now"}, {"en": "offline discussion", "phonetic": "/ˌɔːfˈlaɪn dɪˈskʌʃ.ən/", "pos": "n. phr.", "zh": "会下讨论", "source": "an offline discussion"}, {"en": "circle back", "phonetic": "/ˈsɜːr.kəl bæk/", "pos": "v. phr.", "zh": "回过头来再谈", "source": "circle back to this topic"}, {"en": "in the interest of time", "phonetic": "/ɪn ðə ˈɪn.trəst əv taɪm/", "pos": "phr.", "zh": "为节省时间起见", "source": "in the interest of time"}, {"en": "stay on track", "phonetic": "/steɪ ɑːn træk/", "pos": "v. phr.", "zh": "保持主题；不跑题", "source": "stay on track when presenting"}], "grammar": [{"title": "Why don't we put aside this for an offline discussion?", "structure": "Why don't we + 动词原形?", "example": "Why don't we put aside this for an offline discussion?", "explanation": "Why don't we 用于委婉提议，是最不具攻击性的会议控场方式，把跑题话题'放一放'而非直接打断。"}], "coreSentences": [{"original": "We are totally getting sidetracked.", "function": "指出跑题", "alternative": "We're going off-track here. / This is a tangent."}, {"original": "Why don't we put this aside for an offline discussion?", "function": "提议会下讨论", "alternative": "Let's take this offline. / Can we park this for now?"}, {"original": "In the interest of time, please stay on track.", "function": "提醒时间", "alternative": "To keep us on schedule, let's stay focused. / We're running short on time."}, {"original": "We can circle back to this topic at the end.", "function": "承诺回头讨论", "alternative": "We'll come back to this if time permits. / Let's revisit this later."}], "exercises": {"vocabChoice": [{"question": "\"get sidetracked\" 表示？", "options": ["偏离轨道", "跑题/偏离主题", "被跟踪", "走小路"], "answer": 1}, {"question": "\"offline discussion\" 指？", "options": ["线下讨论", "会下讨论/会后讨论", "离线", "断网"], "answer": 1}], "fillBlank": [{"sentence": "Let's put this ______ for an offline discussion.", "answer": "aside", "hint": "放到一边"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "会议时间把控是主持人的核心职责。'let's take this offline'是最高频的控场语——不否定讨论的价值，但把不适合当下的话题安全地移到会后。circle back是美式商务英语核心动词短语。", "interviewTip": "", "difficulty": "🔵中级"}, {"id": 84, "file": "84-会议收尾", "title": "会议收尾", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Okay then. Let's put it to the vote by a show of hands. For those agreeable to the proposal, please give a thumbs-up in the chatbox. All right, seems we have quite different point of views. Then just my 2 cents here, I recommend we collect all the findings for reference of the management. At the end of the day, we need to take a prudent approach before entering an uncharted territory.", "Okay, I guess that pretty much wraps up today's meeting. Any questions or ideas from the floor?", "Nope, I'm all good."], "dialogueZH": ["好吧。那我们举手表决一下。对于同意该提案的人，请在聊天框里点个赞。好的，看来我们有相当不同的观点。那么我简单说两句，我建议我们收集所有的发现供管理层参考。归根结底，在进入未知领域之前，我们需要采取谨慎的态度。", "好的，我想今天的会议差不多就到这里了。大家还有什么问题或想法吗？", "没有，我很好。"], "vocabulary": [{"en": "put to the vote", "phonetic": "/pʊt tə ðə voʊt/", "pos": "v. phr.", "zh": "付诸表决", "source": "put it to the vote"}, {"en": "show of hands", "phonetic": "/ʃoʊ əv hændz/", "pos": "n. phr.", "zh": "举手表决", "source": "by a show of hands"}, {"en": "thumbs-up", "phonetic": "/θʌmz ʌp/", "pos": "n.", "zh": "点赞；同意", "source": "give a thumbs-up in the chatbox"}, {"en": "wrap up", "phonetic": "/ræp ʌp/", "pos": "v. phr.", "zh": "结束；收尾", "source": "wraps up today's meeting"}, {"en": "from the floor", "phonetic": "/frəm ðə flɔːr/", "pos": "phr.", "zh": "从参会者中", "source": "questions from the floor"}, {"en": "agreeable", "phonetic": "/əˈɡriː.ə.bəl/", "pos": "adj.", "zh": "同意的", "source": "agreeable to the proposal"}], "grammar": [{"title": "I guess that pretty much wraps up... (会议收尾)", "structure": "I guess that pretty much wraps up + 名词", "example": "I guess that pretty much wraps up today's meeting.", "explanation": "Wrap up = 结束/收尾。pretty much = 差不多。最自然的会议收尾语，比That's all更地道。"}], "coreSentences": [{"original": "Let's put it to the vote by a show of hands.", "function": "提议表决", "alternative": "Let's vote on this. / Can we take a quick vote?"}, {"original": "Please give a thumbs-up in the chatbox.", "function": "线上会议表决", "alternative": "Thumbs up if you agree. / Please react with 👍."}, {"original": "I guess that pretty much wraps up today's meeting.", "function": "结束会议", "alternative": "That covers everything for today. / I think we're done here."}, {"original": "Any questions or ideas from the floor?", "function": "最后征集意见", "alternative": "Anything else before we close? / Last chance for comments?"}], "exercises": {"vocabChoice": [{"question": "\"wrap up\" 表示？", "options": ["包裹", "结束/收尾", "覆盖", "开始"], "answer": 1}, {"question": "\"show of hands\" 指什么？", "options": ["展示手", "举手表决", "做手工", "握手"], "answer": 1}], "fillBlank": [{"sentence": "That pretty much ______ up today's meeting.", "answer": "wraps", "hint": "结束/收尾"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方线上会议中，chatbox的👍是最高效的非语言投票方式。'from the floor'源自线下会议'从听众席'，现在泛指所有参会者。wrap up是最核心的收尾动词短语。", "interviewTip": "", "difficulty": "🔵中级"}, {"id": 85, "file": "85-结束会议", "title": "结束会议", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Fantastic! If anyone has any further questions, please private message me anytime. I'll circulate our meeting minutes and to-dos after this meeting.", "Sorry, hold on, we still didn't cover the budget yet.", "You are right. But before that, we need to get a rough idea of what's feasible. Maybe we could stay on this call while letting others crack on with their projects.", "Sounds great.", "All right, thank you all again for taking time out of your busy schedule for this call, especially at such short notice. Let's call it a day here, the rest of you are free to drop off now, thanks."], "dialogueZH": ["太棒了！如果大家还有任何进一步的问题，请随时私信我。会议结束后我会把会议纪要和待办事项发给大家。", "抱歉，等一下，我们还没讨论预算呢。", "你说得对。但在那之前，我们需要先大致了解一下什么是可行的。也许我们可以继续留在这个电话会议里，让其他人先去忙他们的项目。", "听起来不错。", "好的，再次感谢大家抽出宝贵的时间参加这次会议，特别是在这么短的通知时间内。我们就先到这里吧，其他人现在可以退出了，谢谢。"], "vocabulary": [{"en": "circulate", "phonetic": "/ˈsɜːr.kjə.leɪt/", "pos": "v.", "zh": "分发；传阅", "source": "circulate our meeting minutes"}, {"en": "meeting minutes", "phonetic": "/ˈmiː.tɪŋ ˈmɪn.ɪts/", "pos": "n.", "zh": "会议纪要", "source": "our meeting minutes"}, {"en": "to-dos", "phonetic": "/tə duːz/", "pos": "n.", "zh": "待办事项", "source": "meeting minutes and to-dos"}, {"en": "hold on", "phonetic": "/hoʊld ɑːn/", "pos": "phr.", "zh": "等一下", "source": "hold on"}, {"en": "cover", "phonetic": "/ˈkʌv.ər/", "pos": "v.", "zh": "覆盖；讨论到", "source": "we still didn't cover the budget"}, {"en": "rough idea", "phonetic": "/rʌf aɪˈdiː.ə/", "pos": "n. phr.", "zh": "大致了解", "source": "get a rough idea"}, {"en": "crack on", "phonetic": "/kræk ɑːn/", "pos": "v. phr.", "zh": "继续干(自己的活)", "source": "let others crack on with their projects"}], "grammar": [{"title": "Before that, we need to... (补充要点)", "structure": "Before that, 主句", "example": "Before that, we need to get a rough idea of what's feasible.", "explanation": "当有人指出遗漏议题时，Before that用来重新排序——先解决前置问题再继续。"}], "coreSentences": [{"original": "If anyone has further questions, please private message me.", "function": "会后跟进渠道", "alternative": "Feel free to ping me with any follow-up questions."}, {"original": "I'll circulate the meeting minutes and to-dos after this meeting.", "function": "承诺分发纪要", "alternative": "I'll send out the notes and action items. / Minutes will be in your inbox shortly."}, {"original": "Wait, we still didn't cover the budget.", "function": "指出遗漏议题", "alternative": "Hold on — we missed the budget discussion. / One more thing: the budget."}, {"original": "Let's stay on this call while letting others crack on.", "function": "部分离会", "alternative": "Let's keep those who need to stay, and release the rest."}], "exercises": {"vocabChoice": [{"question": "\"circulate\" 在这里的意思是？", "options": ["循环", "分发/传阅(文件)", "包围", "流通"], "answer": 1}, {"question": "\"crack on\" 表示？", "options": ["打碎", "继续做/接着干", "开裂", "开始"], "answer": 1}], "fillBlank": [{"sentence": "I'll ______ the meeting minutes after this call.", "answer": "circulate", "hint": "分发/传阅"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "会后发会议纪要和to-dos是西方职场必须做的动作。'circulate minutes'意味着发给所有参会者+相关但未参会的人。没有minutes的会议等于没开。", "interviewTip": "", "difficulty": "🟢入门"}, {"id": 86, "file": "86-会议开启", "title": "会议开启", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Thanks, everyone, for showing up for the post-mortem meeting. I will be leading this meeting.", "Before we get started, let me just take a moment to remind everyone of the purpose of this meeting. We are here to reflect on the past few weeks, identify areas where we can make improvements and develop a plan to address the issues.", "Our new product was launched, and overall the project was a success, as it was delivered as scheduled, and met business team's expectation. A big shoutout to the team for your efforts once again. But for the issues we encountered, let's find some areas to improve on and get the lessons to learn."], "dialogueZH": ["谢谢大家参加这次复盘会议。我将主持这次会议。", "在开始之前，让我花一点时间提醒大家这次会议的目的。我们在这里回顾过去几周的情况，找出可以改进的地方，并制定解决问题的计划。", "我们的新产品已经发布，总体而言项目是成功的，因为它按时交付，并且达到了业务团队的预期。再次向团队的努力表示感谢。但对于我们遇到的问题，让我们找出一些需要改进的地方，并吸取教训。"], "vocabulary": [{"en": "post-mortem", "phonetic": "/poʊst ˈmɔːr.təm/", "pos": "n./adj.", "zh": "复盘(原意验尸)", "source": "post-mortem meeting"}, {"en": "reflect on", "phonetic": "/rɪˈflekt ɑːn/", "pos": "v. phr.", "zh": "反思", "source": "reflect on the past few weeks"}, {"en": "identify areas", "phonetic": "/aɪˈden.tɪ.faɪ ˈer.i.əz/", "pos": "v. phr.", "zh": "找出方向/领域", "source": "identify areas where we can improve"}, {"en": "shoutout", "phonetic": "/ˈʃaʊt.aʊt/", "pos": "n.", "zh": "表扬；特别感谢", "source": "a big shoutout to the team"}, {"en": "went wrong", "phonetic": "/went rɔːŋ/", "pos": "v. phr.", "zh": "出了问题", "source": "something went wrong"}, {"en": "takeaway", "phonetic": "/ˈteɪk.ə.weɪ/", "pos": "n.", "zh": "收获；经验教训", "source": "identify some takeaways"}], "grammar": [{"title": "Before we get started, let me remind everyone...", "structure": "Before we get started, let me remind everyone of + 名词", "example": "Let me take a moment to remind everyone of the purpose of this meeting.", "explanation": "复盘会议的标准开场——先说明目的(反思+改进)，定调为学习而非追责(blame-free)。"}], "coreSentences": [{"original": "Thanks everyone for showing up for the post-mortem meeting.", "function": "复盘会议开场", "alternative": "Thanks for joining this retrospective. / Appreciate everyone being here for the review."}, {"original": "We are here to reflect and identify areas of improvement.", "function": "说明复盘目的", "alternative": "The goal today is to learn, not blame. / We're here to understand what worked and what didn't."}, {"original": "A big shoutout to the team for your efforts.", "function": "肯定团队", "alternative": "Huge thanks to everyone who contributed. / Great job, team!"}, {"original": "Overall the project was a success, but something went wrong.", "function": "先扬后抑", "alternative": "The launch went well, but there are lessons to learn. / We succeeded, and we can still improve."}], "exercises": {"vocabChoice": [{"question": "\"post-mortem\" 的意思是？", "options": ["验尸", "复盘/回顾", "死后", "预告"], "answer": 1}, {"question": "\"shoutout\" 表示？", "options": ["大喊", "表扬/特别感谢", "尖叫", "叫喊"], "answer": 1}], "fillBlank": [{"sentence": "A big ______ to the team for your efforts.", "answer": "shoutout", "hint": "表扬/感谢"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方面向项目的'post-mortem'/'retrospective'是标准流程。核心原则：blame-free(不追责)，聚焦流程改进而非个人错误。好的复盘以'what went well'开头建立积极基调。", "interviewTip": "", "difficulty": "🔵中级"}, {"id": 87, "file": "87-问题和代办", "title": "问题和代办", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["For example, halfway through the project, the business owner pointed out the product scope was not what he wanted, and it took much rework and back-and-forth communication to align the information for all sides. For this major issue, it was found that both product and business teams weren't on the same page even from the beginning. Going forward, we need to work out an SOP to prevent the recurrence of this issue.", "Based on our discussion over the issues, Here are 2 to-dos from this retro meeting.", "1 Product team to sort out the signoff procedure of business requirements.", "2 Business team to organize a meeting to syn up with relevant parties."], "dialogueZH": ["例如，在项目进行到一半时，业务负责人指出产品范围并不是他想要的，这导致了大量的返工和来回沟通，以协调各方的信息。对于这个主要问题，发现产品团队和业务团队从一开始就没能达成一致。展望未来，我们需要制定一个标准作业程序来防止此类问题再次发生。", "基于我们对这些问题的讨论，以下是本次复盘会议的两项待办事项。", "1. 产品团队整理业务需求的签署确认流程。", "2. 业务团队组织一次会议，与相关方进行同步。"], "vocabulary": [{"en": "point out", "phonetic": "/pɔɪnt aʊt/", "pos": "v. phr.", "zh": "指出", "source": "pointed out"}, {"en": "rework", "phonetic": "/ˌriːˈwɜːrk/", "pos": "n.", "zh": "返工", "source": "it took much rework"}, {"en": "back-and-forth", "phonetic": "/bæk ænd fɔːrθ/", "pos": "n./adj.", "zh": "来回反复", "source": "back-and-forth communication"}, {"en": "retro meeting", "phonetic": "/ˈret.roʊ ˈmiː.tɪŋ/", "pos": "n. phr.", "zh": "回顾会议", "source": "this retro meeting"}, {"en": "signoff procedure", "phonetic": "/ˈsaɪn.ɔːf prəˈsiː.dʒər/", "pos": "n. phr.", "zh": "签字确认流程", "source": "the signoff procedure"}, {"en": "to-dos", "phonetic": "/tə duːz/", "pos": "n.", "zh": "待办事项", "source": "2 to-dos from this retro meeting"}], "grammar": [{"title": "Based on our discussion, here are...", "structure": "Based on + 名词, here are + 复数名词", "example": "Based on our discussion over the issues, here are 2 to-dos.", "explanation": "复盘后形成action items的标准过渡语。基于讨论自然地引出行动清单。"}], "coreSentences": [{"original": "It took much rework and back-and-forth to align.", "function": "描述问题根因", "alternative": "There was a lot of unnecessary back-and-forth."}, {"original": "Based on our discussion, here are the to-dos.", "function": "引出行动项", "alternative": "Here's what we'll do going forward. / The key action items are..."}, {"original": "Product team to sort out the signoff procedure.", "function": "分配具体任务", "alternative": "Product team will own the signoff process. / Let's have product lead this initiative."}], "exercises": {"vocabChoice": [{"question": "\"rework\" 表示？", "options": ["新工作", "返工/重做", "辞职", "找工作"], "answer": 1}, {"question": "\"back-and-forth\" 指？", "options": ["来回", "反复沟通/来回拉锯", "前进后退", "跳舞"], "answer": 1}], "fillBlank": [{"sentence": "Based on our discussion, here are the ______ from this meeting.", "answer": "to-dos", "hint": "待办事项"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "复盘的最终产出是可执行的action items(不能只是'下次注意')。每个to-do要有明确owner和deadline。SOP(标准操作流程)是复盘最经典的长效输出。", "interviewTip": "", "difficulty": "🔵中级"}, {"id": 88, "file": "88-写道歉信", "title": "写道歉信", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Dear XX", "I am writing to extend our sincere apologies for the possible failure on our part in delivering the goods as scheduled this time.", "We truly appreciate your frustration and disappointment especially when you repeatedly stressed the importance of on-time delivery.", "In preparing the goods, our team have been very cautious all the time and bent over backwards to deliver them out ASAP. However, in investigating this bad case, we came to realize one certain worker hasn't updated your shipment address. This is a silly mistake on our end.", "Our team tried to offer the best service, and should have been more cautious in goods delivery especially for urgent orders but we failed this time, we're truly sorry.", "To remedy this undesirable outcome, we've raced against the clock to prepare and ship out additional batches to the right address, which should be able to arrive on schedule. Please rest assured we will bear all the additional costs incurred along the way. Second, we have terminated the employment of the careless worker who made this unbearable silly mistake. Finally, as an additional gesture of apology, we're offering 10% percent discount of service fees for this shipment. While it may not exactly make up for the inconvenience we caused, we hope it'll make amends in some way. Moving forwards, we will surely take extra care in double checking such vulnerable details. Again, please accept our sincere apologies for this headache.", "Please let us know if you have any further questions, we really look forward to delivering best service this time.", "Sincerely"], "dialogueZH": ["亲爱的XX：", "我写这封信是为了对我们这次未能按计划交付货物表示诚挚的歉意。", "我们非常理解您的沮丧和失望，特别是当您反复强调准时交货的重要性时。", "在准备货物的过程中，我们的团队一直非常谨慎，并竭尽全力尽快发货。然而，在调查这个糟糕的案例时，我们意识到某位工作人员没有更新您的收货地址。这是我们这边的一个愚蠢的错误。", "我们的团队试图提供最好的服务，对于紧急订单，本应在货物交付上更加谨慎，但这次我们失败了，我们真的非常抱歉。", "为了补救这一不理想的结果，我们争分夺秒地准备并发货了额外的批次到正确的地址，这些货物应该能够按时到达。请放心，我们将承担途中产生的所有额外费用。其次，我们已经解雇了犯下这个不可忍受的愚蠢错误的粗心员工。最后，作为额外的道歉姿态，我们将为本次发货提供10%的服务费折扣。虽然这可能无法完全弥补我们造成的不便，但我们希望这能在某种程度上弥补。展望未来，我们一定会在核对这些容易出错的细节时格外小心。再次为这次麻烦向您致以诚挚的歉意。", "如果您还有任何进一步的问题，请随时告知我们，我们非常期待这次能提供最好的服务。", "此致"], "vocabulary": [{"en": "extend sincere apologies", "phonetic": "/ɪkˈstend sɪnˈsɪr əˈpɑː.lə.dʒiz/", "pos": "v. phr.", "zh": "致以诚挚歉意", "source": "extend our sincere apologies"}, {"en": "failure on our part", "phonetic": "/ˈfeɪl.jər ɑːn aʊər pɑːrt/", "pos": "n. phr.", "zh": "我方失误", "source": "failure on our part"}, {"en": "deliver as scheduled", "phonetic": "/dɪˈlɪv.ər æz ˈskedʒ.uːld/", "pos": "v. phr.", "zh": "如期交付", "source": "delivering the goods as scheduled"}, {"en": "frustration", "phonetic": "/frʌˈstreɪ.ʃən/", "pos": "n.", "zh": "沮丧；失望", "source": "appreciate your frustration"}, {"en": "take immediate steps", "phonetic": "/teɪk ɪˈmiː.di.ət steps/", "pos": "v. phr.", "zh": "立即采取措施", "source": "took immediate steps"}, {"en": "prevent recurrence", "phonetic": "/prɪˈvent rɪˈkɜːr.əns/", "pos": "v. phr.", "zh": "防止再次发生", "source": "prevent recurrence"}, {"en": "bearing with us", "phonetic": "/ˈber.ɪŋ wɪð ʌs/", "pos": "v. phr.", "zh": "包容我们/耐心等待", "source": "thanks for bearing with us"}], "grammar": [{"title": "I am writing to extend our sincere apologies for...", "structure": "I am writing to extend our sincere apologies for + 名词/动名词", "example": "I am writing to extend our sincere apologies for the possible failure on our part.", "explanation": "商务道歉信的标准开头。extend apologies而非just say sorry，显示诚意。"}], "coreSentences": [{"original": "I am writing to extend our sincere apologies.", "function": "正式道歉开头", "alternative": "Please accept our sincere apologies. / We deeply regret the inconvenience."}, {"original": "We truly appreciate your frustration and disappointment.", "function": "共情客户", "alternative": "We understand how frustrating this must be. / Your disappointment is completely understandable."}, {"original": "We took immediate steps to prevent recurrence.", "function": "说明已采取措施", "alternative": "We've acted quickly to ensure this won't happen again."}, {"original": "Thank you for bearing with us.", "function": "感谢包容", "alternative": "We appreciate your patience. / Thank you for your understanding."}], "exercises": {"vocabChoice": [{"question": "\"extend apologies\" 表示？", "options": ["延长道歉", "致以歉意", "扩展", "道歉信"], "answer": 1}, {"question": "\"bearing with us\" 意思是？", "options": ["背我们", "包容我们/耐心等待", "和我们一起", "承担"], "answer": 1}], "fillBlank": [{"sentence": "I am writing to ______ our sincere apologies.", "answer": "extend", "hint": "致以/表达"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方商务道歉信三要素：1)真诚道歉(apologize, not justify) 2)说明发生了什么(transparency) 3)如何防止再犯(action, not empty promise)。不要用'if'——不要说if we caused inconvenience，承认we DID。", "interviewTip": "", "difficulty": "🟢入门"}, {"id": 89, "file": "89-写感谢信", "title": "写感谢信", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Dear team,", "Now we've reached the last mile of the project. I am writing to express our heartfelt gratitude for your all-hands efforts to roll out our latest product this year. Here is a big shout-out to everyone for your tireless efforts and dedication.", "It can be said that without the assistance and support of each and every one of you, we really could not have made this launch happen. I'd like to take my hat off for the wonderful work you've done and your unwavering commitment to excellence. And special HUGE thanks to the design team, for burning the midnight oil and sparing no efforts to devise the fancy appearance, even when they're already reaching the full capacity.", "Once again, thank you for all that you do, and I look forward to continuing our journey together.", "Sincerely"], "dialogueZH": ["亲爱的团队：", "现在我们已经到达了项目的最后一公里。我写这封信是为了表达我们对大家全力以赴推出今年最新产品的衷心感谢。在此向大家致以崇高的敬意，感谢你们不知疲倦的努力和奉献。", "可以说，如果没有你们每一个人的帮助和支持，我们真的无法完成这次发布。我要向你们所做的出色工作以及对卓越的坚定承诺致敬。特别要向设计团队致以巨大的感谢，感谢他们在已经达到满负荷运转的情况下，依然熬夜并竭尽全力设计出精美的外观。", "再次感谢大家所做的一切，我期待着与大家继续携手前行。", "此致"], "vocabulary": [{"en": "last mile", "phonetic": "/læst maɪl/", "pos": "n. phr.", "zh": "最后一公里；收尾阶段", "source": "reached the last mile of the project"}, {"en": "heartfelt gratitude", "phonetic": "/ˈhɑːrt.felt ˈɡræt.ɪ.tuːd/", "pos": "n. phr.", "zh": "衷心的感谢", "source": "heartfelt gratitude"}, {"en": "all-hands efforts", "phonetic": "/ɔːl hændz ˈef.ərts/", "pos": "n. phr.", "zh": "全员努力", "source": "your all-hands efforts"}, {"en": "roll out", "phonetic": "/roʊl aʊt/", "pos": "v. phr.", "zh": "推出；上线", "source": "roll out our latest product"}, {"en": "take my hat off", "phonetic": "/teɪk maɪ hæt ɔːf/", "pos": "idiom", "zh": "脱帽致敬", "source": "take my hat off for the wonderful team"}, {"en": "could not have made this happen without", "phonetic": "/kʊd nɑːt hæv meɪd ðɪs ˈhæp.ən wɪˈðaʊt/", "pos": "phr.", "zh": "没有...不可能做到", "source": "without the assistance of each and every one of you"}], "grammar": [{"title": "It can be said that without...we could not have...", "structure": "It can be said that without + 名词/人, 主句(虚拟)", "example": "It can be said that without your support, we really could not have made this launch happen.", "explanation": "虚拟语气的感谢——强调'没有你们就不可能'，是感谢信中情感最强烈的句式。"}], "coreSentences": [{"original": "I am writing to express our heartfelt gratitude.", "function": "正式感谢开头", "alternative": "Thank you from the bottom of my heart. / I can't thank you enough."}, {"original": "A big shoutout to the team for rolling out our latest product.", "function": "点名表扬", "alternative": "Major kudos to the team. / Huge thanks to everyone involved."}, {"original": "Without your support, we could not have made this happen.", "function": "强调集体贡献", "alternative": "This wouldn't have been possible without each of you."}, {"original": "I take my hat off for this wonderful team.", "function": "最高致敬", "alternative": "I'm in awe of what you've accomplished. / My deepest respect to the team."}], "exercises": {"vocabChoice": [{"question": "\"take my hat off\" 表示？", "options": ["脱帽子", "致敬/脱帽致敬", "礼貌", "告别"], "answer": 1}, {"question": "\"roll out\" 的意思是？", "options": ["滚出去", "推出/上线(产品)", "离开", "滚动"], "answer": 1}], "fillBlank": [{"sentence": "I am writing to express my ______ gratitude.", "answer": "heartfelt", "hint": "衷心的"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方职场感谢信有'public recognition'文化——抄送给团队+上级，让贡献被看见。感谢要具体(具体项目、具体贡献)，不要泛泛而谈。'take my hat off'是英式最高敬意的表达。", "interviewTip": "", "difficulty": "🟢入门"}, {"id": 90, "file": "90-写请假信1", "title": "写请假信1", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Dear XX,", "I am writing this email to formally request a sick leave from XX to XX as I am having a fever and very bad cough today, and the doctor has prescribed 3 days off work (medical certificate, please see attached). I apologize for any inconvenience that this may cause.", "I have delegated my pending work to XX, who will be covering my responsibilities during my absence. and I will remain available via phone or email if my assistance is required regarding any urgent matters.", "Please process my application at your earliest convenience and let me know if there is any additional documentation or paperwork required.", "Thank you for your understanding and support during this difficult time.", "Sincerely"], "dialogueZH": ["亲爱的XX：", "我写这封邮件是为了正式申请从XX日到XX日的病假，因为我今天发烧且咳嗽严重，医生已开具了3天的病假条（附上医疗证明）。对于由此可能造成的任何不便，我深表歉意。", "我已经将我手头待办的工作委托给了XX，他将在我不在期间负责我的职责。如果在紧急事务上需要我的协助，我仍可通过电话或电子邮件联系。", "请在方便时尽快处理我的申请，并告知我是否需要提供任何额外的文件或文书。", "感谢您在这个困难时期给予的理解和支持。", "此致"], "vocabulary": [{"en": "formally request", "phonetic": "/ˈfɔːr.mə.li rɪˈkwest/", "pos": "v. phr.", "zh": "正式申请", "source": "formally request a sick leave"}, {"en": "prescribe", "phonetic": "/prɪˈskraɪb/", "pos": "v.", "zh": "开(药/假条)", "source": "the doctor has prescribed 3 days off"}, {"en": "medical certificate", "phonetic": "/ˈmed.ɪ.kəl sərˈtɪf.ɪ.kət/", "pos": "n. phr.", "zh": "病假条/医疗证明", "source": "medical certificate attached"}, {"en": "delegate", "phonetic": "/ˈdel.ɪ.ɡeɪt/", "pos": "v.", "zh": "委派；交接", "source": "delegated my pending work to XX"}, {"en": "covering my responsibilities", "phonetic": "/ˈkʌv.ər.ɪŋ maɪ rɪˌspɑːn.səˈbɪl.ə.tiz/", "pos": "v. phr.", "zh": "代理我的职责", "source": "covering my responsibilities"}, {"en": "absence", "phonetic": "/ˈæb.səns/", "pos": "n.", "zh": "缺席；不在", "source": "during my absence"}], "grammar": [{"title": "I have delegated...who will be covering... (交接说明)", "structure": "I have delegated + 任务 + to + 人, + who will be covering + 职责", "example": "I have delegated my pending work to XX, who will be covering my responsibilities.", "explanation": "请假邮件的关键一步——说明工作已交接给谁，让领导放心。"}], "coreSentences": [{"original": "I am writing to formally request a sick leave from XX to XX.", "function": "正式请假", "alternative": "I'd like to request sick leave from...to..."}, {"original": "The doctor has prescribed 3 days off work (medical certificate attached).", "function": "附上医生证明", "alternative": "My doctor recommended 3 days of rest. The medical note is attached."}, {"original": "I have delegated my pending work to XX.", "function": "说明工作交接", "alternative": "XX will cover for me during my absence."}, {"original": "I will remain available via phone if my assistance is urgently required.", "function": "紧急联系渠道", "alternative": "I'm reachable by phone for anything urgent."}], "exercises": {"vocabChoice": [{"question": "\"delegate\" 表示？", "options": ["委托/交接(工作)", "删除", "代表", "延迟"], "answer": 0}, {"question": "\"prescribe\" 在这里的意思是？", "options": ["描述", "开(药/假条)", "处方", "规定"], "answer": 1}], "fillBlank": [{"sentence": "I have ______ my pending tasks to my colleague.", "answer": "delegated", "hint": "交接/委托"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方请假邮件三要素：1)时间(明确起止日期) 2)交接(delegate+cover) 3)联系渠道(紧急时怎么找你)。主动附上medical certificate体现专业度。", "interviewTip": "", "difficulty": "🟢入门"}, {"id": 91, "file": "91-写请假信2", "title": "写请假信2", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Dear XX,", "I would like to apply for a 3-day personal leave starting from next Mon because I have a close friend's wedding to attend.", "I have checked my schedules, we don't have urgent cases or significant deadlines during my time away, and I will be checking my email periodically to stay on top of any critical matters that may arise and require my immediate action.", "If you don't mind, could you please approve my PTO application at your earliest convenience. I really appreciate that.", "Sincerely"], "dialogueZH": ["亲爱的XX：", "我想申请从下周一（Mon）开始为期3天的个人事假，因为我需要参加一位密友的婚礼。", "我已经查看了我的日程安排，在我离开期间没有紧急案件或重要的截止日期。我会定期查看电子邮件，以便及时处理可能出现的任何需要我立即处理的关键事项。", "如果您不介意的话，能否请您在方便时尽快批准我的休假申请？我非常感激。", "此致"], "vocabulary": [{"en": "apply for", "phonetic": "/əˈplaɪ fər/", "pos": "v. phr.", "zh": "申请", "source": "apply for a 3-day personal leave"}, {"en": "personal leave", "phonetic": "/ˈpɜːr.sən.əl liːv/", "pos": "n.", "zh": "事假", "source": "a 3-day personal leave"}, {"en": "urgent cases", "phonetic": "/ˈɜːr.dʒənt ˈkeɪ.sɪz/", "pos": "n. phr.", "zh": "紧急事务", "source": "we don't have urgent cases"}, {"en": "stay on top of", "phonetic": "/steɪ ɑːn tɑːp əv/", "pos": "v. phr.", "zh": "跟进；掌握", "source": "stay on top of critical matters"}, {"en": "periodically", "phonetic": "/ˌpɪr.iˈɑː.dɪ.kəl.i/", "pos": "adv.", "zh": "定期地；时不时地", "source": "checking my email periodically"}, {"en": "smooth handover", "phonetic": "/smuːð ˈhænd.oʊ.vər/", "pos": "n. phr.", "zh": "顺利交接", "source": "ensure a smooth handover"}], "grammar": [{"title": "I have checked my schedules, we don't have...", "structure": "I have checked + 名词, + 结论", "example": "I have checked my schedules, we don't have urgent cases during my time away.", "explanation": "请假前主动check日历确认没有冲突，展示责任心。比直接请假让领导查更好。"}], "coreSentences": [{"original": "I would like to apply for a 3-day personal leave.", "function": "申请事假", "alternative": "I'd like to request 3 days of personal leave."}, {"original": "I have checked my schedules — there are no urgent deadlines.", "function": "说明已核查", "alternative": "I've made sure nothing critical falls during this period."}, {"original": "I will be checking my email periodically.", "function": "保持联系", "alternative": "I'll stay reachable if anything comes up."}], "exercises": {"vocabChoice": [{"question": "\"personal leave\" 指？", "options": ["年假", "事假", "病假", "公假"], "answer": 1}, {"question": "\"stay on top of\" 表示？", "options": ["在...之上", "跟进/掌握", "在上面", "超越"], "answer": 1}], "fillBlank": [{"sentence": "I have checked my ______ and there are no conflicts.", "answer": "schedules", "hint": "日程/时间安排"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "请事假比病假更需要提前申请(通常2周以上)。主动展示'我已经检查了日历'和'email periodically'，让manager感到放心——你是负责任的，不是在逃避工作。", "interviewTip": "", "difficulty": "🟢入门"}, {"id": 92, "file": "92-怼同事甩锅2", "title": "怼同事甩锅2", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Hi, XX", "Per discussed, we have reached a consensus over how the work scope would be allocated.", "However I am confused why I need to take on the task of doing market research. I'd be more than happy to go over the meeting minutes or other records of communication with you one by one. And I would kindly ask you to enlighten me if I missed out on anything.", "Let's sort this out together and kindly let me know your availabilities, thanks.", "Sincerely"], "dialogueZH": ["你好，XX：", "正如我们之前讨论的，我们在工作范围的分配上已经达成了共识。", "然而，我感到困惑的是，为什么我需要承担市场调研的任务。我很乐意与你逐条核对会议纪要或其他沟通记录。如果你觉得我遗漏了什么，请务必指正我。", "让我们一起解决这个问题，并请告知我你的时间安排，谢谢。", "此致"], "vocabulary": [{"en": "per discussed", "phonetic": "/pɜːr dɪˈskʌst/", "pos": "phr.", "zh": "根据之前的讨论(邮件用语)", "source": "Per discussed"}, {"en": "consensus", "phonetic": "/kənˈsen.səs/", "pos": "n.", "zh": "共识", "source": "reached a consensus"}, {"en": "allocated", "phonetic": "/ˈæl.ə.keɪ.tɪd/", "pos": "v.", "zh": "分配", "source": "how the work scope would be allocated"}, {"en": "go over", "phonetic": "/ɡoʊ ˈoʊ.vər/", "pos": "v. phr.", "zh": "过一遍；审查", "source": "go over the meeting minutes"}, {"en": "clarify the situation", "phonetic": "/ˈkler.ɪ.faɪ ðə ˌsɪtʃ.uˈeɪ.ʃən/", "pos": "v. phr.", "zh": "澄清情况", "source": "clarify the situation"}], "grammar": [{"title": "Per discussed, we have reached a consensus...", "structure": "Per + 过去分词, + 主句", "example": "Per discussed, we have reached a consensus over how the work scope would be allocated.", "explanation": "Per = 根据/依照。商务邮件最高频的介词。Per discussed/Per our conversation/Per the agreement。"}], "coreSentences": [{"original": "Per discussed, we have reached a consensus.", "function": "引用前文", "alternative": "As we agreed earlier. / Following up on our discussion."}, {"original": "I am confused why I need to take on this task.", "function": "表达困惑+质疑", "alternative": "I'm unclear on why this falls under my scope."}, {"original": "I'd be happy to go over the meeting minutes with you.", "function": "提议复查记录", "alternative": "Let's review the documentation together."}], "exercises": {"vocabChoice": [{"question": "\"per discussed\" 表示？", "options": ["每次讨论", "根据之前的讨论", "讨论中", "讨论后"], "answer": 1}, {"question": "\"consensus\" 意思是？", "options": ["争议", "共识/一致意见", "人口普查", "审查"], "answer": 1}], "fillBlank": [{"sentence": "______ discussed, we agreed on the division of tasks.", "answer": "Per", "hint": "根据/依照"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方职场中，用'per our discussion/agreement'优雅地提醒对方之前的承诺——用书面记录不伤感情地应对'甩锅'。书面沟通就是你的证据(paper trail)。", "interviewTip": "", "difficulty": "🔴进阶"}, {"id": 93, "file": "93-工作跟进催办", "title": "工作跟进催办", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Subject: Follow-up on Pending Tasks", "Dear XX,", "I hope this email finds you well. I am writing to follow up on the tasks that were assigned to you during our meeting last Weds. As we have agreed, timely completion of these tasks are critical to the success of the project.", "It has been 2 weeks since the assignment, and I was wondering if you could kindly provide an update on their progress. I understand that you have multiple responsibilities to handle, but it would be greatly appreciated if you could prioritize these tasks to ensure that we meet our deadlines."], "dialogueZH": ["主题：关于待办任务的跟进", "亲爱的XX：", "希望你一切顺利。我写这封邮件是为了跟进我们在上周三会议上分配给你的任务。正如我们所商定的，这些任务的及时完成对项目的成功至关重要。", "自从分配任务以来已经过去两周了，我想知道你是否可以提供一下它们的进度更新。我理解你有很多职责要处理，但如果你能优先处理这些任务以确保我们按时完成，我们将不胜感激。"], "vocabulary": [{"en": "follow up on", "phonetic": "/ˈfɑː.loʊ ʌp ɑːn/", "pos": "v. phr.", "zh": "跟进", "source": "follow up on pending tasks"}, {"en": "pending", "phonetic": "/ˈpen.dɪŋ/", "pos": "adj.", "zh": "待处理的", "source": "pending tasks"}, {"en": "assigned to", "phonetic": "/əˈsaɪnd tə/", "pos": "v. phr.", "zh": "分配给", "source": "assigned to you"}, {"en": "timely completion", "phonetic": "/ˈtaɪm.li kəmˈpliː.ʃən/", "pos": "n. phr.", "zh": "及时完成", "source": "timely completion of these tasks"}, {"en": "look into", "phonetic": "/lʊk ˈɪn.tə/", "pos": "v. phr.", "zh": "查看；调查", "source": "look into this matter"}, {"en": "at your earliest convenience", "phonetic": "/æt jər ˈɜːr.li.ɪst kənˈviː.ni.əns/", "pos": "phr.", "zh": "在你方便的最早时间", "source": "at your earliest convenience"}], "grammar": [{"title": "I am writing to follow up on...", "structure": "I am writing to follow up on + 名词", "example": "I am writing to follow up on the tasks that were assigned to you.", "explanation": "催办邮件的标准开头。Follow up on = 跟进。用I am writing而非I want，更正式礼貌。"}], "coreSentences": [{"original": "I am writing to follow up on the pending tasks.", "function": "催办开头", "alternative": "Just checking in on the outstanding items. / Any updates on the tasks?"}, {"original": "Timely completion of these tasks is critical to the project timeline.", "function": "说明重要性", "alternative": "These are time-sensitive. / We need these done to stay on schedule."}, {"original": "Could you please look into this matter at your earliest convenience?", "function": "礼貌催促", "alternative": "When you get a chance, could you prioritize this?"}], "exercises": {"vocabChoice": [{"question": "\"pending\" 表示？", "options": ["完成的", "待处理的/未完成的", "进行中", "取消的"], "answer": 1}, {"question": "\"at your earliest convenience\" 意思是？", "options": ["尽快不客气", "在你方便的最早时间", "马上立刻", "尽快"], "answer": 1}], "fillBlank": [{"sentence": "I am writing to ______ up on the pending tasks.", "answer": "follow", "hint": "跟进"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方职场催办讲究'polite persistence'——礼貌地坚持。从'just checking in'(温和提醒)到'urgent follow-up'(紧急催促)有梯度的表达。at your earliest convenience是最礼节性的催促。", "interviewTip": "", "difficulty": "🟢入门"}, {"id": 94, "file": "94-对接人变更", "title": "对接人变更", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Hi, XX", "Thanks for reaching out for this. Unfortunately I'm no longer in charge of this matter.", "I've taken up a new role with the team and currently focus on leadership coaching. For any queries on this matter, I'd like to refer you to XX from other team as he has replaced me as your POC. I've handed over all the materials to him so you are in good hands. Please find his business card in the attachment.", "It was real pleasure working with you for the last couple of weeks, you made my job easy and enjoyable. Please let me know if there is anything I can help out.", "Best regards"], "dialogueZH": ["你好，XX：", "感谢你为此事联系我。不幸的是，我不再负责此事了。", "我已在团队中担任了一个新角色，目前专注于领导力辅导。关于此事的任何疑问，我想将你转介给其他团队的XX，因为他已接替我成为你的对接人。我已经将所有材料移交给了他，所以你放心交给他处理即可。请在附件中找到他的名片。", "很高兴在过去几周与你共事，你让我的工作变得轻松愉快。如果有什么我能帮上忙的，请随时告诉我。", "此致"], "vocabulary": [{"en": "reach out", "phonetic": "/riːtʃ aʊt/", "pos": "v. phr.", "zh": "联系；主动接触", "source": "thanks for reaching out"}, {"en": "take up a new role", "phonetic": "/teɪk ʌp ə nuː roʊl/", "pos": "v. phr.", "zh": "担任新角色", "source": "taken up a new role"}, {"en": "leadership coaching", "phonetic": "/ˈliː.dər.ʃɪp ˈkoʊ.tʃɪŋ/", "pos": "n.", "zh": "领导力辅导", "source": "focus on leadership coaching"}, {"en": "refer you to", "phonetic": "/rɪˈfɜːr juː tə/", "pos": "v. phr.", "zh": "转介给；让你联系", "source": "refer you to XX"}, {"en": "replace", "phonetic": "/rɪˈpleɪs/", "pos": "v.", "zh": "替代；接替", "source": "he has replaced me as the contact"}, {"en": "keep in the loop", "phonetic": "/kiːp ɪn ðə luːp/", "pos": "v. phr.", "zh": "保持知情", "source": "keep relevant stakeholders in the loop"}], "grammar": [{"title": "I'd like to refer you to... (转介)", "structure": "I'd like to refer you to + 人名", "example": "I'd like to refer you to XX from the other team.", "explanation": "refer you to = 把你refer给...。对接人变更时最标准的转介表达，比'contact XX'更正式。"}], "coreSentences": [{"original": "Thanks for reaching out. Unfortunately I'm no longer in charge of this.", "function": "告知不再负责", "alternative": "I appreciate the message. This has been transitioned to someone else."}, {"original": "I've taken up a new role and currently focus on leadership coaching.", "function": "说明新方向", "alternative": "I've moved to a different position. / My focus has shifted."}, {"original": "I'd like to refer you to XX as he has replaced me.", "function": "转介新对接人", "alternative": "XX is now your point of contact. / Please reach out to XX going forward."}], "exercises": {"vocabChoice": [{"question": "\"refer you to\" 表示？", "options": ["推荐你", "转介给/让你联系", "引用", "参考"], "answer": 1}, {"question": "\"take up a role\" 意思是？", "options": ["放弃职位", "担任角色/接手职位", "带走", "抬头"], "answer": 1}], "fillBlank": [{"sentence": "I'd like to ______ you to my colleague who handles this now.", "answer": "refer", "hint": "转介"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方职场中交接(handover)和对接人变更(POC change)是常态。用'refer you to'转介+CC新对接人是标准做法。确保对方后续沟通的对象明确，不留空白。", "interviewTip": "", "difficulty": "🟢入门"}, {"id": 95, "file": "95-告知离职1", "title": "告知离职1", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Dear XX,", "Please accept this letter as a formal notification of my resignation as project manager in PMO department. Per our previous communication, my last day will be 14 days from today. It's a sincere pleasure working with you and the team. And I am grateful for your leadership and guidance during my stay here, which has helped a lot in growing my experience and career. I am wishing you and the team all the best.", "Yours faithfully"], "dialogueZH": ["亲爱的XX：", "请接受此信作为我辞去PMO部门项目经理职务的正式通知。根据我们之前的沟通，我的最后工作日将是今天起的14天后。与你和团队共事是一段真诚的愉快经历。我非常感谢在我任职期间你的领导和指导，这对我积累经验和职业发展帮助很大。祝你和团队一切顺利。", "此致"], "vocabulary": [{"en": "formal notification", "phonetic": "/ˈfɔːr.məl ˌnoʊ.tɪ.fɪˈkeɪ.ʃən/", "pos": "n. phr.", "zh": "正式通知", "source": "a formal notification of my resignation"}, {"en": "resignation", "phonetic": "/ˌrez.ɪɡˈneɪ.ʃən/", "pos": "n.", "zh": "辞职", "source": "notification of my resignation"}, {"en": "per our previous communication", "phonetic": "/pɜːr aʊər ˈpriː.vi.əs kəˌmjuː.nɪˈkeɪ.ʃən/", "pos": "phr.", "zh": "根据我们之前的沟通", "source": "Per our previous communication"}, {"en": "smooth transition", "phonetic": "/smuːð trænˈzɪʃ.ən/", "pos": "n. phr.", "zh": "平稳过渡", "source": "ensure a smooth transition"}, {"en": "handover", "phonetic": "/ˈhænd.oʊ.vər/", "pos": "n.", "zh": "交接", "source": "handover"}, {"en": "Yours faithfully", "phonetic": "/jʊrz ˈfeɪθ.fəl.i/", "pos": "phr.", "zh": "此致(正式信函结尾)", "source": "Yours faithfully"}], "grammar": [{"title": "Please accept this letter as a formal notification...", "structure": "Please accept this letter as + 名词短语", "example": "Please accept this letter as a formal notification of my resignation.", "explanation": "正式辞职信的标准开头。非常正式的告示语气，通常用于给HR的正式书面通知。"}], "coreSentences": [{"original": "Please accept this letter as a formal notification of my resignation.", "function": "正式辞职", "alternative": "I am writing to formally resign from my position."}, {"original": "Per our previous communication, my last day will be 14 days from today.", "function": "说明最后工作日", "alternative": "As discussed, my final day will be 2 weeks from now."}, {"original": "I will do everything I can to ensure a smooth transition.", "function": "承诺平稳交接", "alternative": "I'm committed to a seamless handover."}], "exercises": {"vocabChoice": [{"question": "\"resignation\" 意思是？", "options": ["辞职", "重新签约", "拒绝", "申请"], "answer": 0}, {"question": "\"smooth transition\" 表示？", "options": ["平稳过渡/顺利交接", "光滑过渡", "快速变化", "不顺"], "answer": 0}], "fillBlank": [{"sentence": "Please accept this letter as a formal ______ of my resignation.", "answer": "notification", "hint": "通知"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方职场辞职通常先口头通知manager(一对一),再发正式书面邮件给HR。Notice period通常是2周至1个月。辞职信要保持积极感恩，重点放在'交接'上而非'离开原因'。", "interviewTip": "", "difficulty": "🟢入门"}, {"id": 96, "file": "96-告知离职2", "title": "告知离职2", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Dear XX", "I'm writing this letter to let you know that I'll be leaving my position as the project manager, my last day will be 22nd of august, 14 days from today. It has been a great pleasure working with you on the projects and appreciate all your support along the way. Here I would also like to introduce my replacement X, who is a veteran with 10-year experience in this industry, so I assure you that you are in the best hands. As a close, I wish you and your company all the best and success in your business.", "Best regards"], "dialogueZH": ["亲爱的XX：", "我写这封信是想通知你，我将辞去项目经理的职位，我的最后工作日将是8月22日，也就是从今天起的14天后。很高兴能与你一起参与这些项目，也非常感谢你一路以来的支持。在这里，我也想向你介绍我的继任者X，他是一位拥有10年行业经验的资深人士，所以我向你保证，你将得到最好的照顾。最后，祝你和你的公司在业务上一切顺利，取得成功。", "此致"], "vocabulary": [{"en": "leave my position", "phonetic": "/liːv maɪ pəˈzɪʃ.ən/", "pos": "v. phr.", "zh": "离开我的岗位", "source": "leaving my position"}, {"en": "great pleasure", "phonetic": "/ɡreɪt ˈpleʒ.ər/", "pos": "n. phr.", "zh": "极大的荣幸", "source": "a great pleasure working here"}, {"en": "fond memories", "phonetic": "/fɑːnd ˈmem.ər.iz/", "pos": "n. phr.", "zh": "美好的回忆", "source": "fond memories"}, {"en": "cross paths", "phonetic": "/krɔːs pæθz/", "pos": "v. phr.", "zh": "再次相遇", "source": "cross paths again"}, {"en": "Best regards", "phonetic": "/best rɪˈɡɑːrdz/", "pos": "phr.", "zh": "此致敬礼(邮件结尾)", "source": "Best regards"}], "grammar": [{"title": "It has been a great pleasure working here.", "structure": "It has been a great pleasure + V-ing", "example": "It has been a great pleasure working alongside you.", "explanation": "离职感谢的经典表达。现在完成时has been + 动名词，表达从过去持续至今的愉快经历。"}], "coreSentences": [{"original": "I'll be leaving my position as the project manager.", "function": "告知离职(对团队)", "alternative": "I wanted to share that I'll be moving on from my role."}, {"original": "It has been a great pleasure working alongside you.", "function": "表达感谢", "alternative": "I've truly enjoyed working with you. / It's been an honor."}, {"original": "I hope our paths will cross again in the future.", "function": "保持联系", "alternative": "I hope we stay in touch. / Let's not be strangers."}], "exercises": {"vocabChoice": [{"question": "\"cross paths\" 意思是？", "options": ["过马路", "再次相遇/重逢", "交叉路口", "相交"], "answer": 1}, {"question": "\"Best regards\" 用于？", "options": ["开头", "邮件结尾/落款", "中间", "标题"], "answer": 1}], "fillBlank": [{"sentence": "It has been a great ______ working here.", "answer": "pleasure", "hint": "荣幸/愉快"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "离职邮件的语气应是warm and professional——温暖的回顾+专业的交接。'I hope our paths will cross again'是西方离职信最经典的结尾语，既情感真挚又不伤感过度。", "interviewTip": "", "difficulty": "🟢入门"}, {"id": 97, "file": "97-告知离职3", "title": "告知离职3", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Dear X,", "Welcome to the team! Attachment is the handover documents, including all the info helping you get up to speed on your projects. I also updated the status of the projects and highlighted the key points you need to be aware of. I have sent separate emails introducing you to key stakeholders both internally and at the client side, your line manager will be scheduling an onboarding meeting. Please feel free to reach out to me on XX @com for any queries, I'd be happy to help.", "Best regards"], "dialogueZH": ["亲爱的X：", "欢迎加入团队！附件是交接文件，包含了帮助你快速了解项目的全部信息。我也更新了项目状态，并突出了你需要留意的关键点。我已经分别发送了邮件，把你介绍给内部和客户方的关键利益相关者，你的直线经理会安排一次入职会议。如果有任何疑问，请随时通过XX@com联系我，我很乐意提供帮助。", "此致"], "vocabulary": [{"en": "handover documents", "phonetic": "/ˈhænd.oʊ.vər ˈdɑː.kjə.mənts/", "pos": "n. phr.", "zh": "交接文件", "source": "Attachment is the handover documents"}, {"en": "attachment", "phonetic": "/əˈtætʃ.mənt/", "pos": "n.", "zh": "附件", "source": "Attachment is"}, {"en": "get up to speed", "phonetic": "/ɡet ʌp tə spiːd/", "pos": "idiom", "zh": "快速熟悉", "source": "helping you get up to speed"}, {"en": "highlight", "phonetic": "/ˈhaɪ.laɪt/", "pos": "v.", "zh": "标出；强调", "source": "highlighted the flagged issues"}, {"en": "flagged issues", "phonetic": "/flæɡd ˈɪʃ.uːz/", "pos": "n. phr.", "zh": "已标记的问题", "source": "flagged issues"}, {"en": "ongoing projects", "phonetic": "/ˈɑːn.ɡoʊ.ɪŋ ˈprɑː.dʒekts/", "pos": "n. phr.", "zh": "正在进行的项目", "source": "updated the status of ongoing projects"}], "grammar": [{"title": "Attachment is + 名词 (附件是...)", "structure": "Attachment is + 名词", "example": "Attachment is the handover documents.", "explanation": "商务邮件的标准附件提示语。比'Please find attached...'更简洁现代。"}], "coreSentences": [{"original": "Attachment is the handover documents.", "function": "说明附件", "alternative": "Please find the handover file attached. / See attachment for details."}, {"original": "This includes all the info helping you get up to speed.", "function": "说明文档内容", "alternative": "Everything you need to ramp up is here. / It covers all the essentials."}, {"original": "I've highlighted the flagged issues for your attention.", "function": "提醒重点关注", "alternative": "Please pay special attention to the highlighted items."}], "exercises": {"vocabChoice": [{"question": "\"handover\" 指？", "options": ["递交", "交接", "移交", "转让"], "answer": 1}, {"question": "\"get up to speed\" 意思是？", "options": ["加速", "快速熟悉/跟上进度", "减速", "学习"], "answer": 1}], "fillBlank": [{"sentence": "______ is the handover documents.", "answer": "Attachment", "hint": "附件"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "离职交接文档是专业度的体现。好的交接文件包含：项目状态+关键联系+flagged issues+待办清单。用'get up to speed'这个习语既鼓励接任者又显得自然。", "interviewTip": "", "difficulty": "🟢入门"}, {"id": 98, "file": "98-告知离职4", "title": "告知离职4", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Dear all,", "I hope you are doing well. I just want to take a moment to let you know that I'll be leaving my position as the project manager here in PMO office and my last day in the office will be the end of this month (31st of Aug). It has been a great honor to have such wonderful working relationships like this, but all good things must come to end, and it's with mixed emotions for me to say goodbyes.", "While I am reluctant to let it go, I am also looking forward to what the future has in store. As a close, I am wishing you all the best moving forwards and thanks again for taking care of me and your support along the way.", "Best regards"], "dialogueZH": ["大家好：", "希望你们一切顺利。我想借此机会通知大家，我将辞去PMO办公室项目经理的职位，我在办公室的最后工作日将是本月底（8月31日）。能拥有如此美好的工作关系，我深感荣幸，但天下没有不散的筵席，与大家告别让我百感交集。", "虽然我依依不舍，但我也期待着未来会发生什么。最后，祝大家未来一切顺利，并再次感谢大家一直以来对我的照顾和支持。", "此致"], "vocabulary": [{"en": "take a moment", "phonetic": "/teɪk ə ˈmoʊ.mənt/", "pos": "v. phr.", "zh": "花一点时间", "source": "take a moment to let you know"}, {"en": "reluctant to let it go", "phonetic": "/rɪˈlʌk.tənt tə let ɪt ɡoʊ/", "pos": "phr.", "zh": "舍不得放手", "source": "reluctant to let it go"}, {"en": "what the future has in store", "phonetic": "/wʌt ðə ˈfjuː.tʃər hæz ɪn stɔːr/", "pos": "phr.", "zh": "未来会发生什么", "source": "what the future has in store"}, {"en": "as a close", "phonetic": "/æz ə kloʊz/", "pos": "phr.", "zh": "作为结束语", "source": "As a close"}, {"en": "moving forwards", "phonetic": "/ˈmuː.vɪŋ ˈfɔːr.wərdz/", "pos": "phr.", "zh": "今后；未来", "source": "wishing you all the best moving forwards"}, {"en": "all the best", "phonetic": "/ɔːl ðə best/", "pos": "phr.", "zh": "一切顺利", "source": "wishing you all the best"}], "grammar": [{"title": "While I am reluctant...I am also looking forward to...", "structure": "While I am + adj., I am also + adj. + about", "example": "While I am reluctant to let it go, I am also looking forward to what the future has in store.", "explanation": "用While并列两种对立情感，展示复杂的真实感受。是离职信的'甜蜜苦涩'(bittersweet)表达。"}], "coreSentences": [{"original": "I just want to take a moment to let you know I'll be leaving.", "function": "温和告知全部门", "alternative": "I wanted to share some personal news — I'll be moving on."}, {"original": "While I am reluctant to let it go, I'm also looking forward.", "function": "表达不舍+期待", "alternative": "It's bittersweet to leave, but I'm excited for what's next."}, {"original": "I am wishing you all the best moving forwards.", "function": "祝福同事", "alternative": "I wish everyone continued success. / All the best to the team."}], "exercises": {"vocabChoice": [{"question": "\"reluctant\" 表示？", "options": ["渴望的", "不情愿的/舍不得的", "开心的", "激进的"], "answer": 1}, {"question": "\"all the best\" 用于？", "options": ["最好", "祝福/一切顺利", "最佳", "全部"], "answer": 1}], "fillBlank": [{"sentence": "I'm wishing you all the ______ moving forwards.", "answer": "best", "hint": "祝福语"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "发给全部门的告别邮件应包含：真诚的感谢 + 温暖的回忆 + 未来的祝福。不要提离职原因(尤其是负面原因)。'bittersweet'语调是最佳选择——不要太悲伤也不要太兴奋。", "interviewTip": "", "difficulty": "🟢入门"}, {"id": 99, "file": "99-离职完整版", "title": "离职完整版", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Hi Mark, I just wondered if you have 5 mins for me to talk about something.", "Of course, anytime. What's on your mind?", "I just wanted to let you know I'm planning on quitting my job next month.", "Oh, well obviously that was a surprise. I didn't see that coming, but what happened?", "I really enjoy my work here and you taught me a lot, but lately I've been doing a lot of self-reflections and realized that this is not a place for me to reach my full potential.", "Can you be more specific?", "You know I have been looking for a management position where I can drive my impact, but all the positions here are full. I really can't see potential in this role, so I think it is better for me to move on and progress my career.", "I'm sorry to hear that. But you've been a high-achiever in the team. anything I can do for me to help you stay?", "Actually my mind has made up but I'll be happy to stay on a bit longer if you like.", "Okay.. Well you know there is obviously going to be quite a lot of handover to do, so, why not we book a meeting to walk through the details.", "Yes, that's totally fine. And please be assured i will finish my assignments and prepare an thorough handover if my replacement has been found.", "I really appreciate that. I'll see you when I get back to office."], "dialogueZH": ["嗨，Mark，我想知道你是否有5分钟时间和我谈谈事情。", "当然，随时都可以。你有什么事想说？", "我只是想让你知道，我计划下个月辞职。", "哦，这确实是个意外。我没想到会这样，但发生了什么事？", "我真的很喜欢在这里的工作，你也教会了我很多，但最近我进行了一些自我反思，意识到这里并不是我发挥全部潜力的地方。", "你能说得更具体一点吗？", "你知道我一直在寻找一个能让我发挥影响力的管理职位，但这里所有的职位都满了。我真的看不到这个职位的发展潜力，所以我认为我最好离开，去推进我的职业生涯。", "听到这个消息我很遗憾。但你一直是团队里的高绩效员工。有什么我能做的来帮你留下来吗？", "其实我已经下定决心了，但如果你愿意的话，我很乐意多待一段时间。", "好的……嗯，你知道显然有很多交接工作要做，所以，我们为什么不安排一个会议来详细讨论一下呢？", "是的，那完全没问题。请放心，如果我的继任者已经找到，我会完成我的任务并准备一份详尽的交接材料。", "我真的很感激。等我回办公室时再见。"], "vocabulary": [{"en": "have 5 mins", "phonetic": "/hæv faɪv mɪnz/", "pos": "phr.", "zh": "有5分钟吗", "source": "if you have 5 mins for me"}, {"en": "what's on your mind", "phonetic": "/wʌts ɑːn jər maɪnd/", "pos": "phr.", "zh": "你在想什么/有什么事", "source": "What's on your mind"}, {"en": "planning on quitting", "phonetic": "/ˈplæn.ɪŋ ɑːn ˈkwɪt.ɪŋ/", "pos": "v. phr.", "zh": "打算辞职", "source": "planning on quitting my job"}, {"en": "high-achiever", "phonetic": "/haɪ əˈtʃiː.vər/", "pos": "n.", "zh": "高效能人士", "source": "you've been a high-achiever"}, {"en": "made up my mind", "phonetic": "/meɪd ʌp maɪ maɪnd/", "pos": "phr.", "zh": "我已经决定了", "source": "my mind has made up"}, {"en": "stay on a bit longer", "phonetic": "/steɪ ɑːn ə bɪt ˈlɔːŋ.ɡər/", "pos": "v. phr.", "zh": "多留一段时间", "source": "stay on a bit longer if you like"}, {"en": "handover", "phonetic": "/ˈhænd.oʊ.vər/", "pos": "n.", "zh": "交接", "source": "quite a lot of handover to do"}, {"en": "replacement", "phonetic": "/rɪˈpleɪs.mənt/", "pos": "n.", "zh": "接替者", "source": "if my replacement has been found"}, {"en": "walk through the details", "phonetic": "/wɔːk θruː ðə ˈdiː.teɪlz/", "pos": "v. phr.", "zh": "逐项过一遍细节", "source": "walk through the details"}], "grammar": [{"title": "I just wanted to let you know I'm planning on...", "structure": "I just wanted to let you know + 从句", "example": "I just wanted to let you know I'm planning on quitting my job.", "explanation": "用wanted(过去时)而非want(现在时)，让告知变得柔软、不具攻击性。是最温和的坏消息传达方式。"}], "coreSentences": [{"original": "I just wondered if you have 5 mins for me.", "function": "请求简短谈话", "alternative": "Got a few minutes to chat? / Could we talk briefly?"}, {"original": "I'm planning on quitting my job next month.", "function": "告知离职意向", "alternative": "I've decided to move on. / I wanted to give you a heads-up — I'm resigning."}, {"original": "My mind has made up.", "function": "表示决心已定", "alternative": "I've made my decision. / This is firm."}, {"original": "I'll be happy to stay on a bit longer to ensure a smooth handover.", "function": "表达善意+负责", "alternative": "I'm flexible on the end date to help with the transition."}], "exercises": {"vocabChoice": [{"question": "\"made up my mind\" 表示？", "options": ["下定决心/决定好了", "想不通", "头脑清醒", "迷惑"], "answer": 0}, {"question": "\"high-achiever\" 意思是？", "options": ["高个子", "高效能人士/表现优异者", "高层", "高压"], "answer": 1}], "fillBlank": [{"sentence": "I'll stay on a bit longer to ensure a smooth ______.", "answer": "handover", "hint": "交接"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "向老板当面提离职是最难的一步。用'I've made my decision'(而不是maybe/I'm thinking)表达确定。主动提出'smooth handover'展示职业素养。不要被counter-offer动摇(除非你真的想留)。", "interviewTip": "", "difficulty": "🔴进阶"}, {"id": 100, "file": "100-劝退下属", "title": "劝退下属", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Steve, come on in, have a seat. This is not going to be an easy conversation. The company has made some decisions which will impact on your employment.", "I don't want to beat around the bush, so I'm just gonna come out with it. Your performance outcome for this cycle is an F, not up to scratch.", "Okay, I expected this. I admit I'm not cut out for this role. I tried to make some improvements in the last 3 months, both in my work approach and my attitude, but seems I still didn't get there. So, I totally accept this outcome."], "dialogueZH": ["Steve，进来吧，请坐。这不会是一次轻松的谈话。公司已经做出了一些将影响你雇佣关系的决定。", "我不想拐弯抹角，所以我直说了。你这个考核周期的绩效结果是F，不合格。", "好吧，我预料到了。我承认我不适合这个职位。我在过去3个月里尝试在工作方法和态度上做了一些改进，但看来我还是没达到要求。所以，我完全接受这个结果。"], "vocabulary": [{"en": "beat around the bush", "phonetic": "/biːt əˈraʊnd ðə bʊʃ/", "pos": "idiom", "zh": "拐弯抹角", "source": "don't want to beat around the bush"}, {"en": "come out with it", "phonetic": "/kʌm aʊt wɪð ɪt/", "pos": "v. phr.", "zh": "直说；摊牌", "source": "just gonna come out with it"}, {"en": "performance outcome", "phonetic": "/pərˈfɔːr.məns ˈaʊt.kʌm/", "pos": "n. phr.", "zh": "绩效结果", "source": "performance outcome for this cycle"}, {"en": "F (grade)", "phonetic": "/ef/", "pos": "n.", "zh": "F级(不及格)", "source": "an F"}, {"en": "not up to scratch", "phonetic": "/nɑːt ʌp tə skrætʃ/", "pos": "idiom", "zh": "未达标；不合格", "source": "not up to scratch"}, {"en": "not cut out for", "phonetic": "/nɑːt kʌt aʊt fər/", "pos": "idiom", "zh": "不适合；不是...的料", "source": "I'm not cut out for this role"}], "grammar": [{"title": "I don't want to beat around the bush, so I'm just gonna come out with it.", "structure": "I don't want to + 委婉动词, so I'll + 直接动词", "example": "I don't want to beat around the bush, so I'm just gonna come out with it.", "explanation": "直接+诚实的开场白，适合必须传达坏消息的场景。先宣告'我不拐弯抹角'再直接说。"}], "coreSentences": [{"original": "This is not going to be an easy conversation.", "function": "预告坏消息", "alternative": "I have difficult news to share. / This is a tough conversation."}, {"original": "I don't want to beat around the bush.", "function": "表示直接", "alternative": "Let me be direct. / I'll get straight to the point."}, {"original": "Your performance outcome is an F, not up to scratch.", "function": "告知绩效结果", "alternative": "Your review didn't meet our standards. / The performance rating is below expectations."}, {"original": "I admit I'm not cut out for this role.", "function": "承认不匹配", "alternative": "I acknowledge this role wasn't the right fit. / I recognize my performance fell short."}], "exercises": {"vocabChoice": [{"question": "\"beat around the bush\" 意思是？", "options": ["打灌木丛", "拐弯抹角/不直说", "打草惊蛇", "收拾"], "answer": 1}, {"question": "\"not up to scratch\" 表示？", "options": ["没刮干净", "未达标/不合格", "很好的", "优秀的"], "answer": 1}], "fillBlank": [{"sentence": "I don't want to ______ around the bush.", "answer": "beat", "hint": "拐弯抹角"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "劝退(pip out/let go)是管理者最难的对话。原则：直接(不拐弯抹角)，尊重(承认对方的努力)，清晰(明确原因和后续步骤)。'not cut out for'是温和地表示不适合的说法。", "interviewTip": "", "difficulty": "🔴进阶"}, {"id": 101, "file": "101-体面告别", "title": "体面告别", "roles": {"A": "John (面试官)", "B": "Steve (候选人)"}, "dialogueEN": ["Before we end this meeting, there is one more topic I want to address with all of you. Unfortunately, I have to inform you that Steve will be leaving end of this month. Steve has been part of our team for three years now, he has been very instrumental in growing our business and always contribute new ideas to team members. He will be moving onto his new role as a PMO, and his new company is very lucky to have him. So steve, would you like to say something?", "Thank you for the kind words. It's a sincere pleasure to be part of this high-performing team and have such lovely working relationships like this, but All good things came to an end, it's definitely bittersweet to say goodbyes. I hope we can meet up over a meal or coffee somewhere in the future. And thank you all again for your support along the way.", "Thank you Steve, wish you all the best, and thank you for everything you've done, keep in touch."], "dialogueZH": ["在我们结束会议之前，我还有一个话题想和大家讨论一下。不幸的是，我必须通知大家，Steve 将在本月底离职。Steve 加入我们团队已经三年了，他在业务增长方面发挥了非常重要的作用，并且总是向团队成员贡献新的想法。他将转任新的 PMO 职位，他的新公司能拥有他是非常幸运的。那么 Steve，你想说点什么吗？", "谢谢你的夸奖。能成为这个高绩效团队的一员，并拥有这样美好的工作关系，我感到非常荣幸，但天下没有不散的筵席，说再见确实让人感到苦乐参半。希望我们未来能在某个地方聚餐或喝杯咖啡。再次感谢大家一路以来的支持。", "谢谢你，Steve，祝你一切顺利，也感谢你所做的一切，保持联系。"], "vocabulary": [{"en": "address", "phonetic": "/əˈdres/", "pos": "v.", "zh": "向...讲话；处理", "source": "one more topic I want to address"}, {"en": "leaving end of this month", "phonetic": "/ˈliː.vɪŋ end əv ðɪs mʌnθ/", "pos": "phr.", "zh": "本月底离职", "source": "leaving end of this month"}, {"en": "pivotal role", "phonetic": "/ˈpɪv.ə.təl roʊl/", "pos": "n. phr.", "zh": "关键作用", "source": "played a pivotal role"}, {"en": "new endeavor", "phonetic": "/nuː enˈdev.ər/", "pos": "n. phr.", "zh": "新的努力/新事业", "source": "his new endeavor"}, {"en": "bittersweet", "phonetic": "/ˈbɪt.ər.swiːt/", "pos": "adj.", "zh": "苦乐参半的", "source": "definitely bittersweet"}, {"en": "keep in touch", "phonetic": "/kiːp ɪn tʌtʃ/", "pos": "phr.", "zh": "保持联系", "source": "keep in touch"}], "grammar": [{"title": "All good things came to an end...", "structure": "All good things came to an end, 主句", "example": "All good things came to an end, it's definitely bittersweet to say goodbye.", "explanation": "'天下没有不散的宴席'的英文版。离职告别最富哲理的开场白，优雅地承认离别。"}], "coreSentences": [{"original": "Before we end this meeting, there is one more topic to address.", "function": "在会议上引出告别", "alternative": "One last thing before we close. / I have an announcement to make."}, {"original": "I have to inform you that Steve will be leaving end of this month.", "function": "正式告知离职", "alternative": "I'm sad to share that Steve will be moving on at the end of the month."}, {"original": "He has played a pivotal role in our team.", "function": "肯定贡献", "alternative": "He's been instrumental to our success. / His contribution has been invaluable."}, {"original": "All good things came to an end — it's bittersweet.", "function": "离别感言", "alternative": "It's hard to say goodbye. / This is a bittersweet moment."}, {"original": "Thank you for everything you've done. Keep in touch.", "function": "最后祝福", "alternative": "We'll miss you. Stay in touch. / All the best — don't be a stranger."}], "exercises": {"vocabChoice": [{"question": "\"pivotal role\" 表示？", "options": ["小角色", "关键作用/核心角色", "支持角色", "旋转角色"], "answer": 1}, {"question": "\"bittersweet\" 意思是？", "options": ["甜的", "苦乐参半", "苦的", "辣的"], "answer": 1}], "fillBlank": [{"sentence": "All good things came to an ______.", "answer": "end", "hint": "结束(谚语)"}], "grammarChoice": [], "sentenceReorder": []}, "cultureNote": "西方职场告别(farewell)通常由manager在团队会议上正式宣布，离职者有机会说几句感言。好的farewell温暖、感恩、积极。'bittersweet'和'keep in touch'是告别必备词汇。", "interviewTip": "", "difficulty": "🟢入门"}];
